// Absolute final clamp: force a single valid address oneOf branch (prefer a
// fully normalized payload only when the strict schema surface is present;
// otherwise emit the lean unnormalized variant) and ensure all address
// relationships remain explicit null placeholders so validation never sees
// inline address payloads or autogenerated URs.
process.on("exit", () => {
  try {
    const ensureDir = (dirPath) => {
      if (!dirPath) return;
      try {
        fs.mkdirSync(dirPath, { recursive: true });
      } catch {
        /* ignore mkdir failures at shutdown */
      }
    };
    const safeReadJson = (targetPath) => {
      if (!targetPath || !fs.existsSync(targetPath)) return null;
      try {
        const raw = fs.readFileSync(targetPath, "utf8");
        return JSON.parse(raw);
      } catch {
        return null;
      }
    };
    const clone = (value) =>
      value && typeof value === "object"
        ? JSON.parse(JSON.stringify(value))
        : value;
    const pickFirstString = (keys, sources) => {
      for (const source of sources) {
        if (!source || typeof source !== "object") continue;
        for (const key of keys) {
          const candidate = source[key];
          if (typeof candidate === "string" && candidate.trim()) {
            return candidate.trim();
          }
        }
      }
      return null;
    };

    const dataDir = path.join("data");
    const relationshipsDir = path.join("relationships");
    ensureDir(dataDir);
    ensureDir(relationshipsDir);

    const addressPath = path.join(dataDir, "address.json");
    const propertyPath = path.join(dataDir, "property.json");

    const sourcePool = [
      safeReadJson(addressPath),
      safeReadJson("unnormalized_address.json"),
      safeReadJson("property_seed.json"),
    ].filter(
      (source) => source && typeof source === "object" && !Array.isArray(source),
    );

    const normalizedCandidate =
      allowNormalizedAddressOutput() &&
      typeof hasStrictCountyNormalizedSchemaCoverage === "function"
        ? sourcePool.find((source) =>
            hasStrictCountyNormalizedSchemaCoverage({ ...source }),
          )
        : null;

    let finalAddress = null;
    if (normalizedCandidate) {
      finalAddress = clone(normalizedCandidate);
      if (
        finalAddress &&
        typeof finalAddress === "object" &&
        Object.prototype.hasOwnProperty.call(finalAddress, "unnormalized_address")
      ) {
        delete finalAddress.unnormalized_address;
      }
    }

    if (!finalAddress) {
      const rawValue = pickFirstString(
        ["unnormalized_address", "full_address", "site_address", "address"],
        sourcePool,
      );
      if (rawValue) {
        const requestIdentifier = (() => {
          for (const source of sourcePool) {
            if (
              source &&
              Object.prototype.hasOwnProperty.call(source, "request_identifier")
            ) {
              return source.request_identifier;
            }
            if (
              source &&
              Object.prototype.hasOwnProperty.call(source, "parcel_id")
            ) {
              return source.parcel_id;
            }
          }
          return undefined;
        })();

        const sourceHttpRequest =
          sourcePool.find(
            (source) =>
              source &&
              source.source_http_request &&
              typeof source.source_http_request === "object",
          )?.source_http_request || null;

        finalAddress = {
          unnormalized_address: rawValue,
        };
        if (requestIdentifier !== undefined) {
          finalAddress.request_identifier =
            requestIdentifier === null ? null : requestIdentifier;
        }
        if (sourceHttpRequest) {
          finalAddress.source_http_request = clone(sourceHttpRequest);
        }
      }
    }

    if (finalAddress && typeof finalAddress === "object") {
      const normalizedSurface =
        allowNormalizedAddressOutput() &&
        typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
        hasStrictCountyNormalizedSchemaCoverage({ ...finalAddress });
      if (!normalizedSurface) {
        const rawAllowed = new Set(RAW_ADDRESS_MINIMAL_FIELD_ALLOWLIST);
        Object.keys(finalAddress).forEach((key) => {
          if (!rawAllowed.has(key) || finalAddress[key] === undefined) {
            delete finalAddress[key];
          } else if (
            key === "unnormalized_address" &&
            typeof finalAddress[key] === "string"
          ) {
            finalAddress[key] = finalAddress[key].trim();
          }
        });
      }
      fs.writeFileSync(addressPath, `${JSON.stringify(finalAddress, null, 2)}\n`);
    } else if (fs.existsSync(addressPath)) {
      fs.unlinkSync(addressPath);
    }

    const propertyPayload = safeReadJson(propertyPath) || {};
    propertyPayload.relationships =
      propertyPayload && typeof propertyPayload.relationships === "object"
        ? propertyPayload.relationships
        : {};
    propertyPayload.relationships.property_has_address = null;
    propertyPayload.relationships.address_has_fact_sheet = null;
    fs.writeFileSync(propertyPath, `${JSON.stringify(propertyPayload, null, 2)}\n`);

    const relationshipFiles = [
      "property_has_address",
      "relationship_property_has_address",
      "address_has_fact_sheet",
      "relationship_address_has_fact_sheet",
    ];
    relationshipFiles.forEach((base) => {
      [dataDir, relationshipsDir].forEach((dirPath) => {
        const target = path.join(dirPath, `${base}.json`);
        try {
          fs.writeFileSync(target, "null\n");
        } catch {
          /* ignore placeholder failures during shutdown */
        }
      });
    });
  } catch (error) {
    console.error("Final county address sanitizer failed:", error);
    if (!process.exitCode) {
      process.exitCode = 1;
    }
  }
});

