function hasMinimalNormalizedAddressCoverage(address, options = {}) {
  if (!address || typeof address !== "object") {
    return false;
  }
  const requiredFields =
    Array.isArray(options.requiredFields) && options.requiredFields.length
      ? options.requiredFields
      : COUNTY_MINIMAL_NORMALIZED_FIELDS;
  const hasCoreCoverage = requiredFields.every((field) =>
    hasMeaningfulAddressValue(address[field]),
  );
  if (!hasCoreCoverage) {
    return false;
  }
  if (options.requireCoordinates === false) {
    return true;
  }
  const latitude = parseCoordinate(address.latitude);
  const longitude = parseCoordinate(address.longitude);
  return Number.isFinite(latitude) && Number.isFinite(longitude);
}

function emitNormalizedAddressPayload(addressPath, payload, options = {}) {
  if (!addressPath || !payload || typeof payload !== "object") {
    return false;
  }

  const normalized = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(payload, field)) {
      continue;
    }
    const value = payload[field];
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      if (Number.isFinite(numeric)) {
        normalized[field] = numeric;
      }
      continue;
    }
    if (typeof value === "string") {
      const trimmed = value.trim();
      normalized[field] = trimmed.length ? trimmed : null;
      continue;
    }
    normalized[field] = value == null ? null : value;
  }

  const coordinateCandidates = [
    { latitude: normalized.latitude, longitude: normalized.longitude },
    ...(Array.isArray(options.coordinateCandidates)
      ? options.coordinateCandidates
      : []),
  ].filter(Boolean);
  if (
    (!Number.isFinite(normalized.latitude) ||
      !Number.isFinite(normalized.longitude)) &&
    coordinateCandidates.length
  ) {
    const resolvedCoordinate =
      resolveCoordinateFromCandidates(coordinateCandidates);
    if (resolvedCoordinate) {
      normalized.latitude = resolvedCoordinate.latitude;
      normalized.longitude = resolvedCoordinate.longitude;
    }
  }

  if (
    !Number.isFinite(normalized.latitude) ||
    !Number.isFinite(normalized.longitude)
  ) {
    return false;
  }

  if (!normalized.county_name && options.defaultCountyName) {
    normalized.county_name = options.defaultCountyName;
  }
  if (!normalized.state_code && options.defaultStateCode) {
    normalized.state_code = options.defaultStateCode;
  }
  if (!normalized.country_code && options.defaultCountryCode) {
    normalized.country_code = options.defaultCountryCode;
  } else if (
    normalized.state_code &&
    !hasMeaningfulAddressValue(normalized.country_code)
  ) {
    normalized.country_code = "US";
  }

  if (!normalized.postal_code) {
    normalized.plus_four_postal_code = null;
  }

  const requestIdentifier = resolveRequestIdentifierCandidate(
    ...(Array.isArray(options.requestIdentifierCandidates)
      ? options.requestIdentifierCandidates
      : []),
    payload.request_identifier,
  );
  normalized.request_identifier =
    requestIdentifier === undefined
      ? null
      : requestIdentifier === null
        ? null
        : requestIdentifier;

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    ...(Array.isArray(options.sourceHttpRequestCandidates)
      ? options.sourceHttpRequestCandidates
      : []),
    payload.source_http_request,
  );
  normalized.source_http_request = sourceHttpRequest
    ? prepareSourceHttpRequest(sourceHttpRequest)
    : null;

  if (
    Object.prototype.hasOwnProperty.call(normalized, "unnormalized_address")
  ) {
    delete normalized.unnormalized_address;
  }

  const normalizedProbe = { ...normalized };
  const hasStrictCoverage =
    typeof hasNormalizedCountyCoverage === "function"
      ? hasNormalizedCountyCoverage(normalizedProbe)
      : COUNTY_REQUIRED_NORMALIZED_FIELDS.every((field) => {
          if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
            return Number.isFinite(parseCoordinate(normalizedProbe[field]));
          }
          return hasMeaningfulAddressValue(normalizedProbe[field]);
        });

  if (!hasStrictCoverage) {
    if (process.env.DEBUG_ADDRESS_FIELDS === "1") {
      console.error(
        "[emitNormalizedAddressPayload] missing strict fields",
        COUNTY_REQUIRED_NORMALIZED_FIELDS.filter((field) => {
          if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
            return !Number.isFinite(parseCoordinate(normalizedProbe[field]));
          }
          return !hasMeaningfulAddressValue(normalizedProbe[field]);
        }),
      );
    }
    return false;
  }

  return writeAddressPayloadDirect(addressPath, normalizedProbe);
}

function stripNormalizedFieldsFromRawPayload(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return address;
  }

  const sanitized = {
    ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      continue;
    }
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      continue;
    }
    const normalizedValue =
      typeof normalizeAddressFieldForSchema === "function"
        ? normalizeAddressFieldForSchema(field, address[field])
        : address[field];
    sanitized[field] =
      normalizedValue === undefined || normalizedValue === null
        ? null
        : normalizedValue;
  }

  const latitude = parseCoordinate(address.latitude);
  const longitude = parseCoordinate(address.longitude);
  if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
    sanitized.latitude = latitude;
    sanitized.longitude = longitude;
  }

  if (Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
    const requestIdentifier = safeNullIfEmpty(address.request_identifier);
    if (requestIdentifier !== undefined) {
      sanitized.request_identifier =
        requestIdentifier === null ? null : requestIdentifier;
    }
  }

  if (Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    if (prepared) {
      sanitized.source_http_request = deepClone(prepared);
    } else if (address.source_http_request === null) {
      sanitized.source_http_request = null;
    }
  }

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, sanitized);
  return address;
}

const RAW_ADDRESS_EXCLUDED_FIELDS = new Set();

const RAW_ADDRESS_ALLOWED_FIELDS = Object.freeze(
  Array.from(
    new Set([
      ...RAW_SCHEMA_CORE_FIELDS,
      ...RAW_ADDRESS_REQUIRED_NULLABLE_FIELDS,
    ]),
  ),
);
const RAW_TERMINAL_FIELD_LIST = Object.freeze(
  Array.from(
    new Set([
      ...RAW_ADDRESS_ALLOWED_FIELDS,
      "source_http_request",
    ]),
  ),
);
const RAW_TERMINAL_FIELD_SET = new Set(RAW_TERMINAL_FIELD_LIST);
const RAW_VARIANT_OPTIONAL_PRESERVABLE_FIELDS = Object.freeze(
  Array.from(
    new Set([
      ...MINIMAL_RAW_ADDRESS_FIELDS,
      ...RAW_FALLBACK_COPY_FIELDS,
      ...RAW_ADDRESS_REQUIRED_NULLABLE_FIELDS,
    ]),
  ),
);
const RAW_VARIANT_OPTIONAL_FIELD_SET = new Set(
  RAW_VARIANT_OPTIONAL_PRESERVABLE_FIELDS,
);
const RAW_STRICT_RAW_FIELD_WHITELIST = Object.freeze([
  ...RAW_VARIANT_OPTIONAL_PRESERVABLE_FIELDS,
]);
const RAW_ADDRESS_RAW_VARIANT_FIELDS = [
  "unnormalized_address",
  ...RAW_ADDRESS_ALLOWED_FIELDS,
];

const RAW_ADDRESS_MINIMAL_ALLOWED_FIELDS = Object.freeze([
  ...RAW_ADDRESS_ALLOWED_FIELDS,
]);

// Preserve the raw-only surface so every payload consistently carries the
// locality/grid metadata that the schema allows for this branch.
const RAW_ADDRESS_RAW_SURFACE_FIELDS = Object.freeze(
  Array.from(
    new Set([
      ...RAW_UNNORMALIZED_ONLY_FIELDS,
      ...RAW_ADDRESS_ALLOWED_FIELDS,
    ]),
  ),
);
const RAW_ADDRESS_RAW_SURFACE_FIELD_SET = new Set(
  RAW_ADDRESS_RAW_SURFACE_FIELDS,
);

// Emit the normalized surface (nullable) plus metadata alongside the raw value
// so the payload clearly targets the unnormalized schema branch without losing
// required keys.
const RAW_ADDRESS_MINIMAL_FIELD_ALLOWLIST = new Set([
  "unnormalized_address",
  "request_identifier",
  "source_http_request",
  ...RAW_ADDRESS_ALLOWED_FIELDS,
]);


function aggregateRawSourcesForUnnormalizedSurface(sources = []) {
  const resolvedSources = Array.isArray(sources)
    ? sources.filter((source) => source && typeof source === "object")
    : [];
  if (!resolvedSources.length) {
    return {};
  }
  const aggregate = {};
  resolvedSources.forEach((source) => {
    RAW_UNNORMALIZED_ONLY_FIELDS.forEach((field) => {
      if (!Object.prototype.hasOwnProperty.call(source, field)) {
        return;
      }
      if (
        field !== "unnormalized_address" &&
        Object.prototype.hasOwnProperty.call(aggregate, field)
      ) {
        return;
      }
      aggregate[field] = source[field];
    });
  });
  if (!hasMeaningfulAddressValue(aggregate.unnormalized_address)) {
    aggregate.unnormalized_address =
      resolveRawAddressStringFromSources(resolvedSources) || null;
  }
  return aggregate;
}

function buildUnnormalizedOnlyAddressSurface(address, defaults = {}) {
  if (!address || typeof address !== "object") {
    return null;
  }
  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return null;
  }

  const projected = { unnormalized_address: rawValue };
  RAW_UNNORMALIZED_ONLY_FIELDS.forEach((field) => {
    if (field === "unnormalized_address") {
      return;
    }
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      return;
    }
    const sanitized = sanitizeAddressFieldValue
      ? sanitizeAddressFieldValue(field, address[field])
      : address[field];
    if (!hasMeaningfulAddressValue(sanitized)) {
      return;
    }
    projected[field] = sanitized;
  });

  const {
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = defaults || {};

  if (
    !hasMeaningfulAddressValue(projected.county_name) &&
    hasMeaningfulAddressValue(defaultCountyName)
  ) {
    projected.county_name = titleCaseCounty(defaultCountyName);
  }
  if (
    !hasMeaningfulAddressValue(projected.state_code) &&
    hasMeaningfulAddressValue(defaultStateCode)
  ) {
    projected.state_code = defaultStateCode;
  }
  if (
    hasMeaningfulAddressValue(projected.state_code) &&
    !hasMeaningfulAddressValue(projected.country_code)
  ) {
    projected.country_code = (defaultCountryCode || "US").toUpperCase();
  } else if (
    !hasMeaningfulAddressValue(projected.country_code) &&
    hasMeaningfulAddressValue(defaultCountryCode)
  ) {
    projected.country_code = defaultCountryCode.toUpperCase();
  }

  if (!hasMeaningfulAddressValue(projected.postal_code)) {
    if (Object.prototype.hasOwnProperty.call(projected, "plus_four_postal_code")) {
      delete projected.plus_four_postal_code;
    }
  }

  return enforceUnnormalizedAddressFieldAllowlist(projected);
}

function buildMinimalRawSubmissionPayload(address, metadataSources = []) {
  if (!address || typeof address !== "object") {
    return null;
  }

  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return null;
  }

  const baselineSource = {
    ...address,
    unnormalized_address: rawValue,
  };
  const rawSurface =
    buildRawOnlySubmissionPayload(baselineSource) || {
      unnormalized_address: rawValue,
    };
  const minimal = rawSurface && typeof rawSurface === "object"
    ? rawSurface
    : { unnormalized_address: rawValue };

  const resolvedSources = [];
  if (Array.isArray(metadataSources)) {
    for (const source of metadataSources) {
      if (source && typeof source === "object") {
        resolvedSources.push(source);
      }
    }
  }

  const ensureField = (field) => {
    if (
      hasMeaningfulAddressValue(minimal[field]) ||
      typeof minimal[field] === "number"
    ) {
      return;
    }
    for (const source of [address, ...resolvedSources]) {
      if (!source || typeof source !== "object") continue;
      if (!Object.prototype.hasOwnProperty.call(source, field)) {
        continue;
      }
      const candidate = sanitizeAddressFieldValue(field, source[field]);
      if (candidate === undefined) {
        continue;
      }
      if (typeof candidate === "string") {
        const trimmed = candidate.trim();
        minimal[field] = trimmed.length ? trimmed : null;
        return;
      }
      minimal[field] = candidate === null ? null : candidate;
      return;
    }
    if (!Object.prototype.hasOwnProperty.call(minimal, field)) {
      minimal[field] = null;
    }
  };

  RAW_ADDRESS_ALLOWED_FIELDS.forEach(ensureField);

  attachAddressMetadataForSchema(minimal, [address, ...resolvedSources]);

  if (!Object.prototype.hasOwnProperty.call(minimal, "request_identifier")) {
    minimal.request_identifier = null;
  }
  if (!Object.prototype.hasOwnProperty.call(minimal, "source_http_request")) {
    minimal.source_http_request = null;
  }

  Object.keys(minimal).forEach((key) => {
    if (!RAW_ADDRESS_MINIMAL_FIELD_ALLOWLIST.has(key)) {
      delete minimal[key];
    }
  });

  return minimal;
}

function enforceMinimalRawAddressEnvelope(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  let payload = null;
  try {
    payload = readJSON(addressPath);
  } catch {
    removeFileIfExists(addressPath);
    return;
  }

  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressPath);
    return;
  }

  const metadataSources = [];
  const metadataPaths = Array.isArray(options.metadataPaths)
    ? options.metadataPaths
    : [];
  for (const metadataPath of metadataPaths) {
    if (typeof metadataPath !== "string" || !metadataPath.trim()) {
      continue;
    }
    const source = readJSONIfExists(metadataPath);
    if (source && typeof source === "object") {
      metadataSources.push(source);
    }
  }

  const hasNormalizedCoverage =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...payload });

  if (hasNormalizedCoverage) {
    const normalized =
      buildNormalizedAddressOutputForSchema({ ...payload }) || null;
    if (normalized && typeof normalized === "object") {
      if (
        Object.prototype.hasOwnProperty.call(
          normalized,
          "unnormalized_address",
        )
      ) {
        delete normalized.unnormalized_address;
      }
      writeAddressJSONBypass(addressPath, normalized);
    }
    return;
  }

  const rawSources = [payload];
  if (Array.isArray(options.rawFallbackPaths)) {
    for (const fallbackPath of options.rawFallbackPaths) {
      if (typeof fallbackPath !== "string" || !fallbackPath.trim()) {
        continue;
      }
      const fallbackSource = readJSONIfExists(fallbackPath);
      if (fallbackSource && typeof fallbackSource === "object") {
        rawSources.push(fallbackSource);
        metadataSources.push(fallbackSource);
      }
    }
  }

  const rawCandidates = [];
  for (const source of rawSources) {
    if (!source || typeof source !== "object") {
      continue;
    }
    rawCandidates.push(
      source.unnormalized_address,
      source.full_address,
      source.site_address,
      source.address,
    );
    if (Array.isArray(source.lines)) {
      rawCandidates.push(
        source.lines
          .map((line) => safeNullIfEmpty(line))
          .filter(Boolean)
          .join(", "),
      );
    }
  }

  const resolvedRaw = resolveFirstNonEmptyString(
    flattenCandidateValues(...rawCandidates),
  );
  if (!resolvedRaw) {
    removeFileIfExists(addressPath);
    return;
  }

  const minimalPayload = buildMinimalRawSubmissionPayload(
    {
      ...payload,
      unnormalized_address: resolvedRaw,
    },
    metadataSources,
  );

  if (minimalPayload) {
    writeAddressJSONBypass(addressPath, minimalPayload);
  } else {
    removeFileIfExists(addressPath);
  }
}

const RAW_LEAN_OUTPUT_FIELDS = Object.freeze([
  "unnormalized_address",
  "section",
  "township",
  "range",
  "block",
  "lot",
  "county_name",
  "country_code",
  "latitude",
  "longitude",
  "request_identifier",
  "source_http_request",
]);

function projectRawAddressToOneOfSurface(address, defaults = {}) {
  if (!address || typeof address !== "object") {
    return null;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return null;
  }

  const normalizedDefaults = {
    county_name: defaults.defaultCountyName
      ? titleCaseCounty(defaults.defaultCountyName)
      : null,
    state_code: defaults.defaultStateCode || null,
    country_code: defaults.defaultCountryCode || "US",
  };

  const projected = { unnormalized_address: rawValue };

  const assignField = (field) => {
    let candidate = address[field];
    if (!hasMeaningfulAddressValue(candidate)) {
      if (
        field === "county_name" &&
        hasMeaningfulAddressValue(normalizedDefaults.county_name)
      ) {
        candidate = normalizedDefaults.county_name;
      } else if (
        field === "state_code" &&
        hasMeaningfulAddressValue(normalizedDefaults.state_code)
      ) {
        candidate = normalizedDefaults.state_code;
      } else if (
        field === "country_code" &&
        hasMeaningfulAddressValue(normalizedDefaults.country_code)
      ) {
        candidate = normalizedDefaults.country_code;
      }
    }

    const sanitized = sanitizeAddressFieldValue(field, candidate);
    if (sanitized === undefined || sanitized === null) {
      return;
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      if (!trimmed.length) {
        return;
      }
      projected[field] = trimmed;
      return;
    }
    projected[field] = sanitized;
  };

  RAW_STRICT_RAW_FIELD_WHITELIST.forEach(assignField);

  const identifier = safeNullIfEmpty(address.request_identifier);
  projected.request_identifier =
    identifier === undefined ? null : identifier === null ? null : identifier;

  if (
    Object.prototype.hasOwnProperty.call(address, "source_http_request")
  ) {
    const prepared = prepareSourceHttpRequest(
      address.source_http_request,
    );
    if (prepared) {
      projected.source_http_request = deepClone(prepared);
    } else if (address.source_http_request === null) {
      projected.source_http_request = null;
    }
  } else {
    projected.source_http_request = null;
  }

  return projected;
}

function enforceRawAddressOneOfProjection(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return false;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  const addressPayload = readJSONIfExists(addressPath) || null;
  if (!addressPayload || typeof addressPayload !== "object") {
    return false;
  }

  if (hasStrictCountyNormalizedSchemaCoverage({ ...addressPayload })) {
    if (
      Object.prototype.hasOwnProperty.call(
        addressPayload,
        "unnormalized_address",
      )
    ) {
      delete addressPayload.unnormalized_address;
      writeAddressPayloadDirect(addressPath, addressPayload);
    }
    return true;
  }

  const supplementalSources = [addressPayload];
  const unnormalizedSource = readJSONIfExists(unnormalizedPath) || null;
  const seedSource = readJSONIfExists(seedPath) || null;

  if (unnormalizedSource && typeof unnormalizedSource === "object") {
    supplementalSources.push(unnormalizedSource);
  }
  if (seedSource && typeof seedSource === "object") {
    supplementalSources.push(seedSource);
  }

  const resolvedRaw =
    resolveRawAddressStringFromSources(supplementalSources) ||
    resolveRawAddressStringFromSource(addressPayload) ||
    null;
  if (!resolvedRaw) {
    return false;
  }

  const mergedSource = supplementalSources.reduce(
    (acc, source) => (source ? Object.assign(acc, source) : acc),
    {},
  );
  mergedSource.unnormalized_address = resolvedRaw;

  const projected = projectRawAddressToOneOfSurface(mergedSource, {
    defaultCountyName,
    defaultStateCode,
    defaultCountryCode,
  });
  if (!projected) {
    return false;
  }

  return writeAddressPayloadDirect(addressPath, projected);
}

const STRICT_RAW_OPTIONAL_FIELDS = Object.freeze([]);

const RAW_ADDRESS_REQUIRED_PRESENCE_FIELDS = new Set([
  ...RAW_ADDRESS_ALLOWED_FIELDS,
  "request_identifier",
  "source_http_request",
  "unnormalized_address",
]);

function enforceMinimalRawAddressSurface(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  RAW_UNNORMALIZED_ONLY_FIELDS.forEach((field) => {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
      return;
    }
    const value = address[field];
    if (typeof value === "string") {
      const trimmed = value.trim();
      address[field] = trimmed.length ? trimmed : null;
      return;
    }
    if (value === undefined) {
      address[field] = null;
    }
  });

  if (!Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
    address.request_identifier = null;
  } else if (
    typeof address.request_identifier === "string" &&
    !address.request_identifier.trim().length
  ) {
    address.request_identifier = null;
  }

  if (!Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    address.source_http_request = null;
  } else if (address.source_http_request === undefined) {
    address.source_http_request = null;
  }

  Object.keys(address).forEach((key) => {
    if (
      RAW_ADDRESS_RAW_SURFACE_FIELD_SET.has(key) ||
      RAW_MINIMAL_SURFACE_META_FIELDS.has(key)
    ) {
      return;
    }
    delete address[key];
  });

  RAW_ADDRESS_REQUIRED_NULLABLE_FIELDS.forEach((field) => {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
      return;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(address[field]);
      address[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }
    if (address[field] === undefined) {
      address[field] = null;
      return;
    }
    if (typeof address[field] === "string" && !address[field].trim().length) {
      address[field] = null;
    }
  });

  return address;
}

function applyRawAddressPresenceDefaults(address) {
  if (!address || typeof address !== "object") {
    return address;
  }
  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...address });

  if (!hasNormalizedSurface) {
    if (!Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
      address.request_identifier = null;
    } else if (address.request_identifier === undefined) {
      address.request_identifier = null;
    }
    if (!Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
      address.source_http_request = null;
    } else if (address.source_http_request === undefined) {
      address.source_http_request = null;
    }

    Object.keys(address).forEach((key) => {
      if (
        RAW_ADDRESS_MINIMAL_FIELD_ALLOWLIST.has(key) ||
        RAW_VARIANT_META_FIELD_ALLOWLIST.has(key)
      ) {
        if (ADDRESS_COORDINATE_FIELDS.includes(key)) {
          const numeric = parseCoordinate(address[key]);
          address[key] = Number.isFinite(numeric) ? numeric : null;
          return;
        }
        if (
          typeof address[key] === "string" &&
          !address[key].trim().length
        ) {
          address[key] = null;
        }
        return;
      }
      delete address[key];
    });

    enforceMinimalRawAddressSurface(address);
    RAW_ADDRESS_REQUIRED_NULLABLE_FIELDS.forEach((field) => {
      if (!Object.prototype.hasOwnProperty.call(address, field)) {
        address[field] = null;
        return;
      }
      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const numeric = parseCoordinate(address[field]);
        address[field] = Number.isFinite(numeric) ? numeric : null;
        return;
      }
      if (address[field] === undefined) {
        address[field] = null;
        return;
      }
      if (
        typeof address[field] === "string" &&
        !address[field].trim().length
      ) {
        address[field] = null;
      }
    });
    return address;
  }

  for (const field of RAW_ADDRESS_REQUIRED_PRESENCE_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
    }
  }
  return address;
}

function hydrateNormalizedFieldSurface(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  NORMALIZED_ADDRESS_FIELDS.forEach((field) => {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
      return;
    }
    if (address[field] === undefined) {
      address[field] = null;
    }
  });

  if (!Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
    address.request_identifier = null;
  } else if (
    typeof address.request_identifier === "string" &&
    !address.request_identifier.trim().length
  ) {
    address.request_identifier = null;
  } else if (address.request_identifier === undefined) {
    address.request_identifier = null;
  }

  if (!Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    address.source_http_request = null;
  } else if (address.source_http_request === undefined) {
    address.source_http_request = null;
  }

  return address;
}

function ensureCountyStructuredFieldPresence(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  COUNTY_STRUCTURED_ADDRESS_REQUIRED_FIELDS.forEach((field) => {
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(address[field]);
      address[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }

    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
      return;
    }

    const value = address[field];
    if (value === undefined || value === null) {
      address[field] = null;
      return;
    }
    if (typeof value === "string" && !value.trim().length) {
      address[field] = null;
    }
  });

  return address;
}

function collapseRawAddressToMinimalSurface(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...address });
  if (hasNormalizedSurface) {
    return address;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";

  if (!rawValue.length) {
    NORMALIZED_ADDRESS_FIELDS.forEach((field) => {
      if (Object.prototype.hasOwnProperty.call(address, field)) {
        delete address[field];
      }
    });
    return address;
  }

  const preservedMeta = {};
  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      preservedMeta[field] = address[field];
    }
  });

  const rawSurface = buildRawOnlySubmissionPayload(address);
  if (!rawSurface) {
    delete address.unnormalized_address;
    Object.assign(address, preservedMeta);
    return address;
  }

  const mergedSurface = {
    ...rawSurface,
    ...preservedMeta,
  };

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, mergedSurface);
  return address;
}

function enforceRawVariantAllowedFields(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const forceRaw =
    Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
    address.__force_raw_variant === true;

  const preferredAllowList = RAW_UNNORMALIZED_SURFACE_FIELD_SET;

  Object.keys(address).forEach((key) => {
    if (key === "__force_raw_variant") {
      return;
    }
    if (preferredAllowList.has(key)) {
      if (!hasMeaningfulAddressValue(address[key])) {
        address[key] = null;
        return;
      }
      if (ADDRESS_COORDINATE_FIELDS.includes(key)) {
        const numeric = parseCoordinate(address[key]);
        address[key] = Number.isFinite(numeric) ? numeric : null;
        return;
      }
      return;
    }
    if (RAW_VARIANT_META_FIELD_ALLOWLIST.has(key)) {
      return;
    }
    if (
      key === "__preserve_structured_fields" &&
      address.__preserve_structured_fields === true
    ) {
      return;
    }
    if (!preferredAllowList.has(key)) {
      delete address[key];
    }
  });

  if (forceRaw) {
    address.__force_raw_variant = true;
  } else if (Object.prototype.hasOwnProperty.call(address, "__force_raw_variant")) {
    delete address.__force_raw_variant;
  }

  return address;
}

function collapseRawAddressToUnnormalizedOnly(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return address;
  }

  const hydrated =
    buildRawOnlySubmissionPayload({
      ...address,
      unnormalized_address: rawValue,
    }) || null;
  if (!hydrated) {
    return address;
  }

  const projected =
    projectRawUnnormalizedOnlyPayload(hydrated) ||
    ensureRawAddressRequiredCoverage(hydrated, rawValue);
  if (!projected) {
    return address;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...address });
  if (hasNormalizedSurface) {
    return address;
  }

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, projected);
  address.__force_raw_variant = true;
  return address;
}

function enforceUnnormalizedOnlyAddressSurface(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const existingPayload = readJSONIfExists(addressPath);
  if (!existingPayload || typeof existingPayload !== "object") {
    removeFileIfExists(addressPath);
    return;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...existingPayload });
  if (hasNormalizedSurface) {
    if (
      Object.prototype.hasOwnProperty.call(existingPayload, "unnormalized_address")
    ) {
      delete existingPayload.unnormalized_address;
      writeJSON(addressPath, existingPayload);
    }
    return;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    extraRawCandidates = [],
    requestIdentifierCandidates = [],
    sourceHttpRequestCandidates = [],
  } = options || {};

  const rawSource = readJSONIfExists(unnormalizedPath) || null;
  const seedSource = readJSONIfExists(seedPath) || null;

  const rawCandidates = [];
  collectRawAddressCandidatesFromSource(rawCandidates, existingPayload);
  collectRawAddressCandidatesFromSource(rawCandidates, rawSource);
  collectRawAddressCandidatesFromSource(rawCandidates, seedSource);

  if (Array.isArray(extraRawCandidates)) {
    extraRawCandidates.forEach((candidate) => {
      if (typeof candidate === "string" && candidate.trim().length) {
        rawCandidates.push(candidate);
      }
    });
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates.forEach((candidate) => {
      if (typeof candidate === "string" && candidate.trim().length) {
        rawCandidates.push(candidate);
      }
    });
  }

  const resolvedRaw = resolveFirstNonEmptyString(rawCandidates);
  const trimmedRaw =
    typeof resolvedRaw === "string" ? resolvedRaw.trim() : "";
  if (!trimmedRaw.length) {
    removeFileIfExists(addressPath);
    return;
  }

  const fieldSources = [existingPayload, rawSource, seedSource].filter(
    (source) => source && typeof source === "object",
  );

  const assignField = (field, fallbackValue = null) => {
    const resolved =
      resolveFirstMeaningfulAddressField(field, fieldSources) ||
      fallbackValue;
    if (resolved === undefined || resolved === null) {
      return null;
    }
    const sanitized =
      typeof sanitizeAddressFieldValue === "function"
        ? sanitizeAddressFieldValue(field, resolved)
        : resolved;
    if (sanitized === undefined || sanitized === null) {
      return null;
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      return trimmed.length ? trimmed : null;
    }
    return sanitized;
  };

  const requestIdentifier = resolveRequestIdentifierCandidate(
    existingPayload && existingPayload.request_identifier,
    rawSource && rawSource.request_identifier,
    seedSource && seedSource.request_identifier,
    seedSource && seedSource.parcel_id,
    ...(Array.isArray(requestIdentifierCandidates)
      ? requestIdentifierCandidates
      : []),
    ...(ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates)
      ? ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates
      : []),
  );

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    existingPayload && existingPayload.source_http_request,
    rawSource && rawSource.source_http_request,
    seedSource && seedSource.source_http_request,
    ...(Array.isArray(sourceHttpRequestCandidates)
      ? sourceHttpRequestCandidates
      : []),
    ...(ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates)
      ? ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates
      : []),
  );

  const leanPayload = {
    unnormalized_address: trimmedRaw,
  };

  const city = assignField("city_name");
  if (city) {
    leanPayload.city_name = city.toUpperCase();
  }

  const municipality = assignField("municipality_name");
  if (municipality) {
    leanPayload.municipality_name = toTitleCase(municipality);
  }

  const state =
    assignField("state_code") ||
    (defaultStateCode ? defaultStateCode.trim().toUpperCase() : null);
  if (state) {
    leanPayload.state_code = state.toUpperCase();
  }

  const postal = assignField("postal_code");
  if (postal) {
    leanPayload.postal_code = postal;
  }

  const plus4 = assignField("plus_four_postal_code");
  if (plus4) {
    leanPayload.plus_four_postal_code = plus4;
  }

  let county = assignField("county_name");
  if (!county && defaultCountyName) {
    county = titleCaseCounty(defaultCountyName);
  }
  if (county) {
    leanPayload.county_name = titleCaseCounty(county);
  }

  const country =
    assignField("country_code") ||
    (leanPayload.state_code ? defaultCountryCode : null) ||
    defaultCountryCode;
  if (country) {
    leanPayload.country_code = country.toUpperCase();
  }

  if (requestIdentifier !== undefined) {
    leanPayload.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }

  if (sourceHttpRequest) {
    const prepared = prepareSourceHttpRequest(sourceHttpRequest);
    leanPayload.source_http_request = prepared ? deepClone(prepared) : null;
  } else {
    leanPayload.source_http_request = null;
  }

  const schemaAlignedPayload =
    ensureRawAddressRequiredCoverage(leanPayload, trimmedRaw) || {
      ...RAW_ADDRESS_SCHEMA_TEMPLATE,
      ...leanPayload,
    };

  Object.keys(schemaAlignedPayload).forEach((key) => {
    if (!RAW_UNNORMALIZED_SURFACE_FIELD_SET.has(key)) {
      delete schemaAlignedPayload[key];
    }
  });

  writeJSON(addressPath, schemaAlignedPayload);
}

function enforceUnnormalizedAddressFieldAllowlist(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  Object.keys(address).forEach((key) => {
    if (RAW_VARIANT_META_FIELD_ALLOWLIST.has(key)) {
      return;
    }
    if (!RAW_UNNORMALIZED_SURFACE_FIELD_SET.has(key)) {
      delete address[key];
      return;
    }
    if (
      key === "unnormalized_address" ||
      key === "request_identifier" ||
      key === "source_http_request"
    ) {
      return;
    }
    if (
      !hasMeaningfulAddressValue(address[key]) &&
      !COUNTY_STRUCTURED_ADDRESS_REQUIRED_FIELDS.includes(key)
    ) {
      delete address[key];
    }
  });

  if (
    Object.prototype.hasOwnProperty.call(address, RAW_ADDRESS_DERIVED_FLAG) &&
    !RAW_UNNORMALIZED_SURFACE_FIELD_SET.has(RAW_ADDRESS_DERIVED_FLAG)
  ) {
    delete address[RAW_ADDRESS_DERIVED_FLAG];
  }

  return address;
}

function projectRawUnnormalizedOnlyPayload(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return null;
  }
  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return null;
  }

  const seeded = {
    ...address,
    unnormalized_address: rawValue,
  };

  const hydrated =
    ensureRawAddressRequiredCoverage(seeded, rawValue) || {
      unnormalized_address: rawValue,
    };

  if (Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
    const normalizedIdentifier = safeNullIfEmpty(address.request_identifier);
    hydrated.request_identifier =
      normalizedIdentifier === undefined
        ? null
        : normalizedIdentifier === null
          ? null
          : normalizedIdentifier;
  } else if (!Object.prototype.hasOwnProperty.call(hydrated, "request_identifier")) {
    hydrated.request_identifier = null;
  }

  if (Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    hydrated.source_http_request = prepared ? deepClone(prepared) : null;
  } else if (!Object.prototype.hasOwnProperty.call(hydrated, "source_http_request")) {
    hydrated.source_http_request = null;
  }

  const projected = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: hydrated.unnormalized_address,
  };

  RAW_ADDRESS_ALLOWED_FIELDS.forEach((field) => {
    if (!Object.prototype.hasOwnProperty.call(hydrated, field)) {
      return;
    }
    const sanitized = sanitizeAddressFieldValue(field, hydrated[field]);
    projected[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  });

  const normalizedIdentifier = safeNullIfEmpty(hydrated.request_identifier);
  projected.request_identifier =
    normalizedIdentifier === undefined
      ? null
      : normalizedIdentifier === null
        ? null
        : normalizedIdentifier;

  const preparedSource = prepareSourceHttpRequest(
    hydrated.source_http_request,
  );
  projected.source_http_request = preparedSource
    ? deepClone(preparedSource)
    : null;

  const latitude = parseCoordinate(hydrated.latitude);
  const longitude = parseCoordinate(hydrated.longitude);
  if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
    projected.latitude = latitude;
    projected.longitude = longitude;
  }

  if (
    Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
    address.__force_raw_variant === true
  ) {
    projected.__force_raw_variant = true;
  }

  return projected;
}

function enforceRawFieldAllowlistOnDisk(addressPath) {
  if (!addressPath || typeof addressPath !== "string") {
    return;
  }
  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }
  if (
    typeof payload.unnormalized_address !== "string" ||
    !payload.unnormalized_address.trim().length
  ) {
    return;
  }
  const sanitized = enforceRawVariantAllowedFields({ ...payload });
  originalWriteFileSync.call(
    fs,
    addressPath,
    `${JSON.stringify(sanitized, null, 2)}\n`,
  );
}

function enforceDeterministicAddressOneOf(addressPath, options = {}) {
  if (!addressPath || typeof addressPath !== "string") {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const {
    rawSources = [],
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
  } = options || {};

  const normalizedSurfaceAvailable =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...payload });
  if (normalizedSurfaceAvailable) {
    const normalizedOutput =
      buildNormalizedAddressOutputForSchema({ ...payload }) || null;
    if (normalizedOutput) {
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "unnormalized_address",
        )
      ) {
        delete normalizedOutput.unnormalized_address;
      }
      writeAddressJSONBypass(addressPath, normalizedOutput);
    }
    return;
  }

  const sourcePool = Array.isArray(rawSources)
    ? rawSources.filter((source) => source && typeof source === "object")
    : [];
  sourcePool.unshift(payload);

  const leanRaw =
    buildLeanRawAddressPayloadFromSources(sourcePool, {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) || null;

  if (
    !leanRaw ||
    !hasMeaningfulAddressValue(leanRaw.unnormalized_address)
  ) {
    enforceDeterministicRawAddressFromSources(addressPath, {
      existingAddress: payload,
      unnormalizedPath,
      seedPath,
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    });
    return;
  }

  const normalizedIdentifier = safeNullIfEmpty(payload.request_identifier);
  if (normalizedIdentifier !== undefined) {
    leanRaw.request_identifier =
      normalizedIdentifier === null ? null : normalizedIdentifier;
  }

  const preparedSource = prepareSourceHttpRequest(
    payload.source_http_request,
  );
  leanRaw.source_http_request = preparedSource
    ? deepClone(preparedSource)
    : null;

  const minimalSurface =
    pruneAddressToMinimalRawFields(
      { ...leanRaw, __force_raw_variant: true },
      sourcePool,
    ) || { ...leanRaw, __force_raw_variant: true };

  collapseRawAddressToUnnormalizedOnly(minimalSurface);
  writeAddressJSONBypass(addressPath, minimalSurface);
}

function stripRawVariantStructuredFields(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const preserveStructured =
    Object.prototype.hasOwnProperty.call(
      address,
      "__preserve_structured_fields",
    ) && address.__preserve_structured_fields === true;
  const hasForceRawFlag =
    Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
    address.__force_raw_variant === true;
  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  const hasNormalizedSurface =
    typeof hasNormalizedCountyCoverage === "function" &&
    hasNormalizedCountyCoverage({ ...address });
  const requireRawSurface =
    FORCE_RAW_ONLY_ADDRESS_OUTPUT ||
    forceRawAddressVariantOutput ||
    hasForceRawFlag ||
    (!preserveStructured && !hasNormalizedSurface && rawValue.length > 0);

  if (preserveStructured && !hasForceRawFlag && hasNormalizedSurface) {
    return address;
  }

  if (!requireRawSurface) {
    if (hasForceRawFlag) {
      delete address.__force_raw_variant;
    }
    return address;
  }

  const preservedMeta = {};
  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      preservedMeta[field] = address[field];
    }
  });
  if (
    Object.prototype.hasOwnProperty.call(preservedMeta, "__preserve_structured_fields")
  ) {
    delete preservedMeta.__preserve_structured_fields;
  }

  if (
    Object.prototype.hasOwnProperty.call(address, "__preserve_structured_fields") &&
    address.__preserve_structured_fields === true
  ) {
    delete address.__preserve_structured_fields;
  }

  if (hasNormalizedSurface) {
    if (Object.prototype.hasOwnProperty.call(address, "unnormalized_address")) {
      delete address.unnormalized_address;
    }
    Object.assign(address, preservedMeta);
    return address;
  }

  if (!rawValue.length) {
    if (Object.prototype.hasOwnProperty.call(address, "unnormalized_address")) {
      delete address.unnormalized_address;
    }
    Object.assign(address, preservedMeta);
    return address;
  }

  const rawSurface = buildRawOnlySubmissionPayload({
    ...address,
    unnormalized_address: rawValue,
  });
  if (!rawSurface) {
    delete address.unnormalized_address;
    Object.assign(address, preservedMeta);
    return address;
  }

  pruneRawAddressFieldSurface(rawSurface);
  enforceRawVariantAllowedFields(rawSurface);

  const mergedSurface = {
    ...rawSurface,
    ...preservedMeta,
  };

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, mergedSurface);
  applyRawAddressPresenceDefaults(address);

  return address;
}

function enforceMinimalRawSubmissionSurface(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const preserveStructured =
    Object.prototype.hasOwnProperty.call(
      address,
      "__preserve_structured_fields",
    ) && address.__preserve_structured_fields === true;
  const hasForceRawFlag =
    Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
    address.__force_raw_variant === true;
  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...address });
  if (preserveStructured && !hasForceRawFlag && hasNormalizedSurface) {
    return address;
  }
  if (hasNormalizedSurface) {
    return address;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";

  const preservedMeta = {};
  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      preservedMeta[field] = address[field];
    }
  });

  if (!rawValue.length) {
    Object.keys(address).forEach((key) => {
      if (RAW_VARIANT_META_FIELD_ALLOWLIST.has(key)) {
        return;
      }
      delete address[key];
    });
    Object.assign(address, preservedMeta);
    return address;
  }

  const rawSurface = buildRawOnlySubmissionPayload({
    ...address,
    unnormalized_address: rawValue,
  });
  if (!rawSurface) {
    delete address.unnormalized_address;
    Object.assign(address, preservedMeta);
    return address;
  }

  pruneRawAddressFieldSurface(rawSurface);
  const mergedSurface = {
    ...rawSurface,
    ...preservedMeta,
  };

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, mergedSurface);
  return address;
}

function pruneRawAddressFieldSurface(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return address;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return address;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...address });
  if (hasNormalizedSurface) {
    return address;
  }

  const preservedMeta = {};
  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      preservedMeta[field] = address[field];
    }
  });
  if (
    Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
    address.__force_raw_variant === true
  ) {
    preservedMeta.__force_raw_variant = true;
  }

  const leanSurface = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  RAW_ADDRESS_OUTPUT_FIELDS.forEach((field) => {
    if (field === "unnormalized_address") {
      return;
    }
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      return;
    }

    const originalValue = address[field];
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(originalValue);
      leanSurface[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }

    const sanitizedValue = sanitizeAddressFieldValue
      ? sanitizeAddressFieldValue(field, originalValue)
      : originalValue;
    if (!hasMeaningfulAddressValue(sanitizedValue)) {
      leanSurface[field] = null;
      return;
    }

    if (typeof sanitizedValue === "string") {
      const trimmed = sanitizedValue.trim();
      leanSurface[field] = trimmed.length ? trimmed : null;
      return;
    }

    leanSurface[field] = sanitizedValue;
  });

  if (!leanSurface.postal_code) {
    leanSurface.plus_four_postal_code = null;
  }
  if (
    hasMeaningfulAddressValue(leanSurface.state_code) &&
    !hasMeaningfulAddressValue(leanSurface.country_code)
  ) {
    leanSurface.country_code = "US";
  }

  const hasLatitude = Number.isFinite(leanSurface.latitude);
  const hasLongitude = Number.isFinite(leanSurface.longitude);
  if (hasLatitude !== hasLongitude) {
    leanSurface.latitude = null;
    leanSurface.longitude = null;
  }

  if (
    !Object.prototype.hasOwnProperty.call(preservedMeta, "request_identifier")
  ) {
    preservedMeta.request_identifier = null;
  }
  if (
    !Object.prototype.hasOwnProperty.call(
      preservedMeta,
      "source_http_request",
    )
  ) {
    preservedMeta.source_http_request = null;
  }

  Object.keys(address).forEach((key) => {
    delete address[key];
  });
  Object.assign(address, leanSurface, preservedMeta);
  return address;
}

function buildTerminalRawSubmissionSnapshot(address) {
  if (!address || typeof address !== "object" || Array.isArray(address)) {
    return null;
  }
  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return null;
  }

  // Start from the full raw schema surface so all nullable required fields
  // (street grid, coordinates, etc.) are present even when the source only
  // provides an unnormalized string. This keeps validation on the raw oneOf
  // branch instead of reporting missing normalized fields.
  const snapshot = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  RAW_TERMINAL_FIELD_LIST.forEach((field) => {
    if (field === "unnormalized_address") {
      return;
    }

    if (field === "request_identifier") {
      const identifier = safeNullIfEmpty(address.request_identifier);
      snapshot.request_identifier =
        identifier === undefined
          ? null
          : identifier === null
            ? null
            : identifier;
      return;
    }

    if (field === "source_http_request") {
      const prepared = prepareSourceHttpRequest(address.source_http_request);
      snapshot.source_http_request = prepared ? deepClone(prepared) : null;
      return;
    }

    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      return;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(address[field]);
      snapshot[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }

    const sanitized = sanitizeAddressFieldValue
      ? sanitizeAddressFieldValue(field, address[field])
      : address[field];
    if (sanitized === undefined) {
      snapshot[field] = null;
      return;
    }

    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      snapshot[field] = trimmed.length ? trimmed : null;
      return;
    }

    snapshot[field] = sanitized === null ? null : sanitized;
  });

  if (!Object.prototype.hasOwnProperty.call(snapshot, "request_identifier")) {
    snapshot.request_identifier = null;
  }
  if (!Object.prototype.hasOwnProperty.call(snapshot, "source_http_request")) {
    snapshot.source_http_request = null;
  }

  const fallbackFieldSources =
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.fieldSources)
      ? ADDRESS_FALLBACK_CONTEXT.fieldSources.filter(
          (source) =>
            source &&
            typeof source === "object" &&
            !Array.isArray(source),
        )
      : [];

  if (fallbackFieldSources.length) {
    MINIMAL_RAW_ADDRESS_FIELDS.forEach((field) => {
      if (field === "unnormalized_address") {
        return;
      }
      if (hasMeaningfulAddressValue(snapshot[field])) {
        return;
      }
      let fallbackValue = resolveFirstMeaningfulAddressField(
        field,
        fallbackFieldSources,
      );
      if (
        !hasMeaningfulAddressValue(fallbackValue) &&
        field === "county_name"
      ) {
        fallbackValue = resolveFirstMeaningfulAddressField(
          "county_jurisdiction",
          fallbackFieldSources,
        );
      }
      if (!hasMeaningfulAddressValue(fallbackValue)) {
        return;
      }
      const sanitized =
        typeof sanitizeAddressFieldValue === "function"
          ? sanitizeAddressFieldValue(field, fallbackValue)
          : fallbackValue;
      if (sanitized !== undefined && sanitized !== null) {
        snapshot[field] = sanitized;
      }
    });
  }

  if (!hasMeaningfulAddressValue(snapshot.county_name)) {
    snapshot.county_name = titleCaseCounty("Palm Beach");
  }
  if (!hasMeaningfulAddressValue(snapshot.state_code)) {
    snapshot.state_code = "FL";
  }
  if (
    hasMeaningfulAddressValue(snapshot.state_code) &&
    !hasMeaningfulAddressValue(snapshot.country_code)
  ) {
    snapshot.country_code = "US";
  }
  if (!hasMeaningfulAddressValue(snapshot.postal_code)) {
    snapshot.plus_four_postal_code = null;
  }

  if (!hasMeaningfulAddressValue(snapshot.request_identifier)) {
    const identifierCandidates =
      ADDRESS_FALLBACK_CONTEXT &&
      Array.isArray(ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates)
        ? ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates
        : [];
    if (identifierCandidates.length) {
      const resolvedIdentifier = resolveRequestIdentifierCandidate(
        snapshot.request_identifier,
        ...identifierCandidates,
      );
      if (hasMeaningfulAddressValue(resolvedIdentifier)) {
        snapshot.request_identifier = resolvedIdentifier;
      }
    }
  }

  if (
    (snapshot.source_http_request === null ||
      snapshot.source_http_request === undefined) &&
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates) &&
    ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates.length
  ) {
    const resolvedSource = resolveSourceHttpRequestCandidate(
      snapshot.source_http_request,
      ...ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates,
    );
    snapshot.source_http_request = resolvedSource
      ? prepareSourceHttpRequest(resolvedSource)
      : null;
  }

  // Keep the raw payload on the unnormalized oneOf branch by dropping any
  // structured fields that may have been inferred during hydration.
  enforceRawVariantAllowedFields(snapshot);

  RAW_ADDRESS_ALLOWED_FIELDS.forEach((field) => {
    if (field === "unnormalized_address") {
      return;
    }
    if (!Object.prototype.hasOwnProperty.call(snapshot, field)) {
      snapshot[field] = null;
    }
  });

  stripAddressMetaFields(snapshot);
  return snapshot;
}

function finalizePalmBeachRawAddressSnapshot(addressPath, options = {}) {
  if (!addressPath || typeof addressPath !== "string") {
    return false;
  }
  if (!fs.existsSync(addressPath)) {
    return false;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return false;
  }

  const rawValue = safeNullIfEmpty(payload.unnormalized_address);
  if (!rawValue) {
    return false;
  }

  const {
    defaultCountyName = titleCaseCounty("Palm Beach"),
    defaultStateCode = "FL",
    defaultCountryCode = "US",
  } = options || {};

  const enriched = {
    ...payload,
    unnormalized_address: rawValue,
  };

  if (!hasMeaningfulAddressValue(enriched.county_name) && defaultCountyName) {
    enriched.county_name = titleCaseCounty(defaultCountyName);
  }
  if (!hasMeaningfulAddressValue(enriched.state_code) && defaultStateCode) {
    enriched.state_code = defaultStateCode;
  }
  if (!hasMeaningfulAddressValue(enriched.country_code) && defaultCountryCode) {
    enriched.country_code = defaultCountryCode;
  }

  const derived = deriveNormalizedAddressFieldsFromRaw(rawValue);
  if (derived && typeof derived === "object") {
    ["city_name", "state_code", "postal_code", "plus_four_postal_code"].forEach(
      (field) => {
        if (
          !hasMeaningfulAddressValue(enriched[field]) &&
          hasMeaningfulAddressValue(derived[field])
        ) {
          const sanitized = sanitizeAddressFieldValue
            ? sanitizeAddressFieldValue(field, derived[field])
            : derived[field];
          if (sanitized !== undefined) {
            enriched[field] = sanitized;
          }
        }
      },
    );
  }

  const snapshot = buildTerminalRawSubmissionSnapshot(enriched);
  if (!snapshot) {
    return false;
  }

  if (!hasMeaningfulAddressValue(snapshot.county_name) && defaultCountyName) {
    snapshot.county_name = titleCaseCounty(defaultCountyName);
  }
  if (!hasMeaningfulAddressValue(snapshot.state_code) && defaultStateCode) {
    snapshot.state_code = defaultStateCode;
  }
  if (!hasMeaningfulAddressValue(snapshot.country_code) && defaultCountryCode) {
    snapshot.country_code = defaultCountryCode;
  }

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(snapshot, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to persist finalized Palm Beach raw address:", error);
    throw error;
  }
  return true;
}

function enforceLeanRawAddressFile(addressPath) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const rawValue =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...payload });
  if (hasNormalizedSurface) {
    return;
  }

  const working = { ...payload };
  pruneRawAddressFieldSurface(working);
  enforceRawVariantAllowedFields(working);

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(working, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to enforce lean raw address file:", error);
  }
}

function enforceRawAddressOneOfFallback(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const hasNormalizedSurface =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...payload });
  if (hasNormalizedSurface) {
    return;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  const supplementalSources = [];
  for (const candidatePath of [unnormalizedPath, seedPath]) {
    if (!candidatePath) continue;
    const source = readJSONIfExists(candidatePath);
    if (source && typeof source === "object") {
      supplementalSources.push(source);
    }
  }

  const rawSourceCandidates = [payload, ...supplementalSources];
  const resolvedRaw =
    resolveRawAddressStringFromSources(rawSourceCandidates) || null;
  if (!resolvedRaw) {
    return;
  }

  const payloadWithRaw = {
    ...payload,
    unnormalized_address: resolvedRaw,
  };

  const minimalRaw =
    buildMinimalRawAddressForSchema(payloadWithRaw, rawSourceCandidates, {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) || null;

  if (!minimalRaw || typeof minimalRaw !== "object") {
    return;
  }

  if (!hasMeaningfulAddressValue(minimalRaw.unnormalized_address)) {
    minimalRaw.unnormalized_address = resolvedRaw.trim();
  }

  if (!minimalRaw.postal_code) {
    minimalRaw.plus_four_postal_code = null;
  }

  if (
    hasMeaningfulAddressValue(minimalRaw.state_code) &&
    !hasMeaningfulAddressValue(minimalRaw.country_code)
  ) {
    minimalRaw.country_code = defaultCountryCode || "US";
  }

  if (
    (minimalRaw.latitude == null && minimalRaw.longitude != null) ||
    (minimalRaw.latitude != null && minimalRaw.longitude == null)
  ) {
    minimalRaw.latitude = null;
    minimalRaw.longitude = null;
  }

  minimalRaw.__force_raw_variant = true;
  minimalRaw.__preserve_request_metadata = true;

  writeAddressJSONBypass(addressPath, minimalRaw);
}

function emitRawAddressSchemaSurface(addressPath) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (
    !payload ||
    typeof payload !== "object" ||
    typeof payload.unnormalized_address !== "string" ||
    !payload.unnormalized_address.trim().length
  ) {
    return;
  }

  const surfaced = applyRawAddressPresenceDefaults({ ...payload });
  if (
    Object.prototype.hasOwnProperty.call(surfaced, RAW_MINIMAL_SURFACE_FLAG)
  ) {
    delete surfaced[RAW_MINIMAL_SURFACE_FLAG];
  }

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(surfaced, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to emit raw address schema surface:", error);
  }
}

const RAW_ADDRESS_REQUIRED_FIELDS = [
  "unnormalized_address",
];

const STRUCTURED_ADDRESS_STRICT_FIELDS = [
  "street_number",
  "street_name",
  "street_pre_directional_text",
  "street_post_directional_text",
  "street_suffix_type",
  "unit_identifier",
  "route_number",
  "city_name",
  "state_code",
  "postal_code",
  "plus_four_postal_code",
  "country_code",
  "county_name",
  "township",
  "range",
  "section",
  "block",
  "latitude",
  "longitude",
];

// Raw variant only requires the persisted unnormalized string. Downstream
// validators will populate normalized fields when available, but their absence
// should not disqualify the raw payload.
const RAW_SCHEMA_REQUIRED_FIELDS = [];

const RAW_ADDRESS_REQUIRED_FIELD_SURFACE = [];

const RAW_ADDRESS_STRICT_VALUE_FIELDS = [];

const RAW_ADDRESS_STRICT_GRID_FIELDS = [];

const ADDRESS_SCHEMA_FIELDS = [
  ...new Set([
    ...NORMALIZED_ADDRESS_FIELDS,
    ...RAW_ADDRESS_ALLOWED_FIELDS,
    "unnormalized_address",
  ]),
];

const RAW_ADDRESS_OUTPUT_FIELDS = Object.freeze([
  "unnormalized_address",
  ...Array.from(new Set([...RAW_ADDRESS_ALLOWED_FIELDS])),
]);

const RAW_MINIMAL_ADDRESS_FIELDS = [
  "unnormalized_address",
  ...RAW_ADDRESS_OUTPUT_FIELDS,
  "request_identifier",
  "source_http_request",
];
const RAW_MINIMAL_ADDRESS_FIELD_SET = new Set(RAW_MINIMAL_ADDRESS_FIELDS);

const RAW_ADDRESS_SCHEMA_RAW_ONLY_FIELDS = new Set(RAW_ADDRESS_MINIMAL_FIELD_ALLOWLIST);

const RAW_ADDRESS_TEMPLATE_FIELDS = Object.freeze(
  Array.from(
    new Set([
      ...RAW_ADDRESS_OUTPUT_FIELDS,
      "request_identifier",
      "source_http_request",
    ]),
  ),
);

const RAW_ADDRESS_SCHEMA_TEMPLATE = Object.freeze(
  RAW_ADDRESS_TEMPLATE_FIELDS.reduce((acc, field) => {
    acc[field] = null;
    return acc;
  }, {}),
);

// Keep the raw surface aligned to the schema-required nullable fields so the
// unnormalized oneOf branch validates (latitude/longitude, street components,
// etc. must still be present as nulls when unknown).
const RAW_UNNORMALIZED_SURFACE_ALLOWLIST = Object.freeze(
  Array.from(
    new Set([
      ...RAW_ADDRESS_OUTPUT_FIELDS,
      "request_identifier",
      "source_http_request",
    ]),
  ),
);
const RAW_UNNORMALIZED_SURFACE_FIELD_SET = new Set(
  RAW_UNNORMALIZED_SURFACE_ALLOWLIST,
);

const RAW_ONLY_ADDRESS_FIELDS = Object.freeze([]);
const RAW_ONLY_ADDRESS_FIELD_SET = new Set(RAW_ONLY_ADDRESS_FIELDS);
const RAW_MINIMAL_SURFACE_FLAG = "__prefer_minimal_raw_surface";
const RAW_VARIANT_META_FIELD_ALLOWLIST = new Set([
  RAW_MINIMAL_SURFACE_FLAG,
  "__force_raw_variant",
  "__preserve_structured_fields",
  "__raw_minimal_surface",
  "__preserve_request_metadata",
  "request_identifier",
  "source_http_request",
]);
const RAW_MINIMAL_SURFACE_META_FIELDS = new Set([
  RAW_ADDRESS_DERIVED_FLAG,
  ...RAW_VARIANT_META_FIELD_ALLOWLIST,
]);

function stripRawVariantForbiddenFields(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  RAW_VARIANT_FORBIDDEN_FIELDS.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      delete address[field];
    }
  });

  return address;
}

function buildRawOnlySubmissionPayload(address) {
  if (!address || typeof address !== "object") {
    return null;
  }

  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return null;
  }

  const rawPayload = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  RAW_ADDRESS_ALLOWED_FIELDS.forEach((field) => {
    let sanitized = null;
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      sanitized = sanitizeAddressFieldValue(field, address[field]);
      if (sanitized === undefined) {
        sanitized = null;
      }
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      sanitized = trimmed.length ? trimmed : null;
    }
    rawPayload[field] = sanitized;
  });

  const identifier = safeNullIfEmpty(address.request_identifier);
  if (identifier !== undefined) {
    rawPayload.request_identifier = identifier === null ? null : identifier;
  }

  if (
    Object.prototype.hasOwnProperty.call(address, "source_http_request") &&
    address.source_http_request
  ) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    rawPayload.source_http_request = prepared ? deepClone(prepared) : null;
  } else if (
    Object.prototype.hasOwnProperty.call(address, "source_http_request") &&
    address.source_http_request === null
  ) {
    rawPayload.source_http_request = null;
  }

  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (
      field === "request_identifier" ||
      field === "source_http_request"
    ) {
      return;
    }
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      rawPayload[field] = address[field];
    }
  });

  RAW_ONLY_ADDRESS_FIELDS.forEach((field) => {
    const coordinate = parseCoordinate(address[field]);
    rawPayload[field] = Number.isFinite(coordinate) ? coordinate : null;
  });

  if (!Object.prototype.hasOwnProperty.call(rawPayload, "request_identifier")) {
    rawPayload.request_identifier = null;
  }
  if (!Object.prototype.hasOwnProperty.call(rawPayload, "source_http_request")) {
    rawPayload.source_http_request = null;
  }

  stripRawVariantForbiddenFields(rawPayload);

  const minimalPayload = projectRawUnnormalizedOnlyPayload(rawPayload);
  if (minimalPayload) {
    if (
      Object.prototype.hasOwnProperty.call(address, "__force_raw_variant") &&
      address.__force_raw_variant === true
    ) {
      minimalPayload.__force_raw_variant = true;
    }
    stripRawVariantForbiddenFields(minimalPayload);
    return enforceUnnormalizedAddressFieldAllowlist(minimalPayload);
  }

  return enforceUnnormalizedAddressFieldAllowlist(rawPayload);
}

function buildRawOnlyAddressSurface(address) {
  const rawPayload = buildRawOnlySubmissionPayload(address);
  if (!rawPayload) {
    return null;
  }
  rawPayload.__force_raw_variant = true;
  return enforceRawVariantAllowedFields(rawPayload);
}

function buildLeanRawAddressPayload(source, overrides = {}) {
  if (!source || typeof source !== "object") {
    return null;
  }

  const rawCandidate =
    Object.prototype.hasOwnProperty.call(overrides, "unnormalized_address") &&
    typeof overrides.unnormalized_address === "string"
      ? overrides.unnormalized_address
      : source.unnormalized_address;
  const trimmedRaw = safeNullIfEmpty(rawCandidate);
  if (!trimmedRaw) {
    return null;
  }

  const lean = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: trimmedRaw,
  };

  const latitudeCandidate = Object.prototype.hasOwnProperty.call(
    overrides,
    "latitude",
  )
    ? overrides.latitude
    : source.latitude;
  const longitudeCandidate = Object.prototype.hasOwnProperty.call(
    overrides,
    "longitude",
  )
    ? overrides.longitude
    : source.longitude;
  const latitude = parseCoordinate(latitudeCandidate);
  const longitude = parseCoordinate(longitudeCandidate);
  if (Number.isFinite(latitude)) {
    lean.latitude = latitude;
  }
  if (Number.isFinite(longitude)) {
    lean.longitude = longitude;
  }
  if (
    (lean.latitude == null && lean.longitude != null) ||
    (lean.latitude != null && lean.longitude == null)
  ) {
    lean.latitude = null;
    lean.longitude = null;
  }

  const copyField = (field) => {
    const candidate = Object.prototype.hasOwnProperty.call(overrides, field)
      ? overrides[field]
      : source[field];
    const normalized =
      typeof normalizeAddressFieldForSchema === "function"
        ? normalizeAddressFieldForSchema(field, candidate)
        : candidate;
    if (normalized === undefined || normalized === null) {
      return;
    }
    if (typeof normalized === "string") {
      const trimmed = normalized.trim();
      if (trimmed.length) {
        lean[field] = trimmed;
      }
      return;
    }
    lean[field] = normalized;
  };

  const coordinateFields = new Set(["latitude", "longitude"]);
  RAW_ADDRESS_ALLOWED_FIELDS.filter(
    (field) => !coordinateFields.has(field),
  ).forEach(copyField);

  if (!lean.postal_code) {
    lean.plus_four_postal_code = null;
  }
  if (lean.state_code && !lean.country_code) {
    lean.country_code = "US";
  }

  const requestIdentifierOverride = Object.prototype.hasOwnProperty.call(
    overrides,
    "requestIdentifier",
  )
    ? overrides.requestIdentifier
    : source.request_identifier;
  const normalizedRequestIdentifier = safeNullIfEmpty(
    requestIdentifierOverride,
  );
  lean.request_identifier =
    normalizedRequestIdentifier === undefined
      ? null
      : normalizedRequestIdentifier === null
        ? null
        : normalizedRequestIdentifier;

  const sourceHttpRequestOverride = Object.prototype.hasOwnProperty.call(
    overrides,
    "sourceHttpRequest",
  )
    ? overrides.sourceHttpRequest
    : source.source_http_request;
  const preparedSource = prepareSourceHttpRequest(sourceHttpRequestOverride);
  if (preparedSource) {
    lean.source_http_request = deepClone(preparedSource);
  } else {
    lean.source_http_request = null;
  }

  return enforceRawVariantAllowedFields(lean);
}

function pruneAddressToMinimalRawFields(address, metadataSources = []) {
  if (!address || typeof address !== "object") {
    return address;
  }

  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return address;
  }

  const resolvedMetadataSources = Array.isArray(metadataSources)
    ? metadataSources.filter((source) => source && typeof source === "object")
    : [];

  const minimal =
    buildMinimalRawSubmissionPayload(
      {
        ...address,
        unnormalized_address: rawValue,
      },
      resolvedMetadataSources,
    ) || null;

  if (minimal) {
    return minimal;
  }

  const requestIdentifier = safeNullIfEmpty(address.request_identifier);
  const preparedSource = prepareSourceHttpRequest(
    address.source_http_request,
  );

  return {
    unnormalized_address: rawValue,
    request_identifier:
      requestIdentifier === undefined ? null : requestIdentifier,
    source_http_request: preparedSource ? deepClone(preparedSource) : null,
  };
}

function ensureRawVariantFieldSurface(address) {
  if (!address || typeof address !== "object") {
    return address;
  }

  const rawValue = safeNullIfEmpty(address.unnormalized_address);
  if (!rawValue) {
    return address;
  }

  const surfaced =
    buildMinimalRawSubmissionPayload(address) ||
    buildRawOnlySubmissionPayload(address);

  if (!surfaced) {
    return address;
  }

  RAW_VARIANT_META_FIELD_ALLOWLIST.forEach((field) => {
    if (field === "request_identifier" || field === "source_http_request") {
      return;
    }
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      surfaced[field] = address[field];
    }
  });

  return surfaced;
}

function persistAddressPayload(addressPath, payload) {
  if (!addressPath || !payload || typeof payload !== "object") {
    return;
  }

  let workingPayload =
    payload && typeof payload === "object" ? deepClone(payload) : payload;
  if (workingPayload && typeof workingPayload === "object") {
    workingPayload =
      ensureRawAddressFieldCompleteness(workingPayload) || workingPayload;
    stripRawVariantStructuredFields(workingPayload);
    projectAddressPayloadForSchema(workingPayload);
  }

  ensureDir(path.dirname(addressPath));
  originalWriteFileSync.call(
    fs,
    addressPath,
    `${JSON.stringify(workingPayload, null, 2)}\n`,
  );
}

function materializeRawAddressSchemaSurface(addressPath) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const rawValue =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return;
  }

  if (
    typeof shouldTreatAddressAsNormalized === "function" &&
    shouldTreatAddressAsNormalized({ ...payload })
  ) {
    return;
  }

  const derivedFromRaw =
    typeof deriveNormalizedAddressFieldsFromRaw === "function"
      ? deriveNormalizedAddressFieldsFromRaw(rawValue) || {}
      : {};

  const surfaced = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  const assignRawField = (field) => {
    const sourceValue = Object.prototype.hasOwnProperty.call(payload, field)
      ? payload[field]
      : derivedFromRaw[field];

    const sanitized =
      typeof sanitizeAddressFieldValue === "function"
        ? sanitizeAddressFieldValue(field, sourceValue)
        : sourceValue;

    if (sanitized === undefined || sanitized === null) {
      surfaced[field] = null;
      return;
    }

    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      surfaced[field] = trimmed.length ? trimmed : null;
      return;
    }

    surfaced[field] = sanitized;
  };

  RAW_ADDRESS_ALLOWED_FIELDS.forEach(assignRawField);

  if (!hasMeaningfulAddressValue(surfaced.postal_code)) {
    surfaced.plus_four_postal_code = null;
  }

  if (
    hasMeaningfulAddressValue(surfaced.state_code) &&
    !hasMeaningfulAddressValue(surfaced.country_code)
  ) {
    surfaced.country_code = "US";
  }

  if (Object.prototype.hasOwnProperty.call(payload, "request_identifier")) {
    const identifier = safeNullIfEmpty(payload.request_identifier);
    surfaced.request_identifier =
      identifier === undefined ? null : identifier;
  }

  if (Object.prototype.hasOwnProperty.call(payload, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(payload.source_http_request);
    if (prepared) {
      surfaced.source_http_request = deepClone(prepared);
    } else if (payload.source_http_request === null) {
      surfaced.source_http_request = null;
    }
  }

  if (
    Object.prototype.hasOwnProperty.call(payload, "__force_raw_variant") &&
    payload.__force_raw_variant === true
  ) {
    surfaced.__force_raw_variant = true;
  }

  persistAddressPayload(addressPath, surfaced);
}

const RAW_VARIANT_METADATA_FIELDS = [
  "request_identifier",
  "source_http_request",
];
// County raw branch is intentionally minimal: keep the coarse locality/grid
// surface (plus optional coordinates) aligned with the allowlist so every raw
// projection emits only the fields the schema actually permits.
const RAW_VARIANT_MINIMAL_SURFACE_FIELDS = Object.freeze(
  Array.from(
    new Set([
      ...RAW_ADDRESS_RAW_SURFACE_FIELDS,
      ...RAW_ADDRESS_ALLOWED_FIELDS,
    ]),
  ),
);
const RAW_VARIANT_MINIMAL_SURFACE_FIELD_SET = new Set(
  RAW_VARIANT_MINIMAL_SURFACE_FIELDS,
);
const RAW_VARIANT_OUTPUT_ALLOWLIST = Object.freeze(
  Array.from(
    new Set([
      ...RAW_ADDRESS_RAW_SURFACE_FIELDS,
      ...RAW_ADDRESS_ALLOWED_FIELDS,
    ]),
  ),
);
const RAW_VARIANT_ALLOWED_OUTPUT_FIELDS = Object.freeze([
  "unnormalized_address",
  ...RAW_VARIANT_OUTPUT_ALLOWLIST,
  ...RAW_VARIANT_METADATA_FIELDS,
]);
const RAW_VARIANT_ALLOWED_OUTPUT_FIELD_SET = new Set(
  RAW_VARIANT_ALLOWED_OUTPUT_FIELDS,
);
const RAW_VARIANT_FIELD_WHITELIST = [...RAW_VARIANT_ALLOWED_OUTPUT_FIELDS];
const RAW_VARIANT_FIELD_WHITELIST_SET = new Set(RAW_VARIANT_FIELD_WHITELIST);
const RAW_VARIANT_METADATA_FIELD_SET = new Set(RAW_VARIANT_METADATA_FIELDS);

const RAW_VARIANT_PRESERVED_FIELDS = Object.freeze([
  ...RAW_VARIANT_OUTPUT_ALLOWLIST,
]);
const RAW_VARIANT_PRESERVED_FIELD_SET = new Set(RAW_VARIANT_PRESERVED_FIELDS);

const RAW_ADDRESS_TERMINAL_FIELD_WHITELIST = Object.freeze([
  "unnormalized_address",
  ...RAW_VARIANT_OUTPUT_ALLOWLIST,
  ...RAW_VARIANT_METADATA_FIELDS,
]);
const RAW_ADDRESS_TERMINAL_FIELD_SET = new Set(
  RAW_ADDRESS_TERMINAL_FIELD_WHITELIST,
);

const RAW_ADDRESS_SURFACE_FIELDS = [
  "unnormalized_address",
  ...RAW_ADDRESS_OUTPUT_FIELDS,
  "request_identifier",
  "source_http_request",
];
const RAW_ADDRESS_ALLOWED_WITH_UNNORMALIZED_SET = new Set(RAW_ADDRESS_SURFACE_FIELDS);
const RAW_ADDRESS_OUTPUT_FIELD_SET = new Set(RAW_ADDRESS_OUTPUT_FIELDS);
const RAW_VARIANT_ALLOWED_FIELD_SET = new Set(RAW_VARIANT_OUTPUT_ALLOWLIST);
const NORMALIZED_ADDRESS_ALLOWED_KEY_SET = new Set([
  ...NORMALIZED_ADDRESS_FIELDS,
  "request_identifier",
  "source_http_request",
]);
const RAW_ADDRESS_FINAL_ALLOWED_FIELDS = [
  "unnormalized_address",
  ...RAW_ADDRESS_ALLOWED_FIELDS,
];

process.on("exit", () => {
  if (ADDRESS_FINALIZATION_COMPLETE) {
    try {
      enforceAutogeneratedRelationshipNulls([
        path.join("data"),
        path.join("relationships"),
      ]);
    } catch (error) {
      console.error("Failed to enforce null relationships during exit:", error);
    }
    return;
  }
  if (!FORCE_RAW_ONLY_ADDRESS_OUTPUT && !forceRawAddressVariantOutput) {
    return;
  }
  try {
    enforceFinalRawAddressSnapshot();
  } catch (error) {
    console.error("Failed to write the final raw address snapshot:", error);
  }
});

function hasStructuredAddressCoverage(address) {
  if (!address || typeof address !== "object") {
    return false;
  }

  const normalizedSurface =
    typeof ensureNormalizedAddressSchemaSurface === "function"
      ? ensureNormalizedAddressSchemaSurface({ ...address })
      : { ...address };

  const strictSurface = { ...normalizedSurface };

  if (
    typeof hasRobustNormalizedAddress === "function" &&
    !hasRobustNormalizedAddress(strictSurface)
  ) {
    return false;
  }

  const hasExtendedCoverage = STRUCTURED_ADDRESS_STRICT_FIELDS.every(
    (field) => {
      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const numeric = parseCoordinate(strictSurface[field]);
        if (!Number.isFinite(numeric)) {
          return false;
        }
        strictSurface[field] = numeric;
        return true;
      }

      const sanitized = sanitizeAddressFieldValue(
        field,
        strictSurface[field],
      );
      if (!hasMeaningfulAddressValue(sanitized)) {
        return false;
      }
      strictSurface[field] = sanitized;
      return true;
    },
  );

  if (!hasExtendedCoverage) {
    return false;
  }

  for (const field of ADDRESS_COORDINATE_FIELDS) {
    const numeric = parseCoordinate(strictSurface[field]);
    strictSurface[field] = Number.isFinite(numeric) ? numeric : null;
  }

  Object.assign(address, strictSurface);
  return true;
}

// Raw variant should only expose the subset of normalized fields that the
// schema allows alongside an unnormalized string.
const RAW_VARIANT_SCHEMA_FIELDS = [...RAW_ADDRESS_ALLOWED_FIELDS];
const RAW_VARIANT_SCHEMA_FIELD_SET = new Set(RAW_VARIANT_SCHEMA_FIELDS);
const RAW_VARIANT_CRITICAL_FIELDS = [
  "latitude",
  "longitude",
  "street_number",
  "street_name",
  "street_suffix_type",
  "postal_code",
  "plus_four_postal_code",
  "city_name",
  "state_code",
  "county_name",
];

const RAW_VARIANT_OPTIONAL_FIELDS_FOR_ONE_OF = [
  "city_name",
  "state_code",
  "postal_code",
  "plus_four_postal_code",
  "country_code",
  "county_name",
  "municipality_name",
  "street_number",
  "street_name",
  "street_pre_directional_text",
  "street_post_directional_text",
  "street_suffix_type",
  "unit_identifier",
  "route_number",
  "township",
  "range",
  "section",
  "block",
  "lot",
];

const RAW_SCHEMA_VARIANT_ALLOWED_FIELDS = [
  "latitude",
  "longitude",
  "city_name",
  "municipality_name",
  "county_name",
  "state_code",
  "country_code",
  "postal_code",
  "plus_four_postal_code",
  "street_number",
  "street_name",
  "street_suffix_type",
  "street_pre_directional_text",
  "street_post_directional_text",
  "unit_identifier",
  "route_number",
  "township",
  "range",
  "section",
  "block",
  "lot",
];

function applyAddressSchemaDefaultsForVariant(address, variantHint) {
  if (!address || typeof address !== "object") return null;

  const hasRawString =
    typeof address.unnormalized_address === "string" &&
    address.unnormalized_address.trim().length > 0;
  const resolveVariant =
    variantHint === "normalized"
      ? "normalized"
      : variantHint === "raw"
        ? "raw"
        : hasRawString
          ? "raw"
          : "normalized";

  const surfaceFields =
    resolveVariant === "raw"
      ? RAW_ADDRESS_OUTPUT_FIELDS
      : NORMALIZED_ADDRESS_FIELDS;

  const materialized = {};

  if (resolveVariant === "raw") {
    materialized.unnormalized_address = hasRawString
      ? address.unnormalized_address.trim()
      : null;
  }

  for (const field of surfaceFields) {
    const candidate = Object.prototype.hasOwnProperty.call(address, field)
      ? address[field]
      : null;
    const normalizedValue = normalizeAddressFieldForSchema(field, candidate);
    materialized[field] =
      normalizedValue === undefined || normalizedValue === null
        ? null
        : normalizedValue;
  }

  if (resolveVariant === "normalized") {
    if (Object.prototype.hasOwnProperty.call(materialized, "unnormalized_address")) {
      delete materialized.unnormalized_address;
    }
  }

  if (!materialized.postal_code) {
    materialized.plus_four_postal_code = null;
  }

  if (materialized.state_code && !materialized.country_code) {
    materialized.country_code = "US";
  }

  if (Object.prototype.hasOwnProperty.call(address, "request_identifier")) {
    const trimmedRequest =
      typeof address.request_identifier === "string"
        ? address.request_identifier.trim()
        : address.request_identifier;
    materialized.request_identifier =
      trimmedRequest && String(trimmedRequest).length
        ? trimmedRequest
        : null;
  }

  if (Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    if (prepared) {
      materialized.source_http_request = prepared;
    }
  }

  return materialized;
}

function buildAddressOutputPayload(address) {
  if (!address || typeof address !== "object") return null;

  const hasUnnormalized =
    typeof address.unnormalized_address === "string" &&
    address.unnormalized_address.trim().length > 0;

  const trimmedUnnormalized = hasUnnormalized
    ? address.unnormalized_address.trim()
    : "";
  if (hasUnnormalized && !trimmedUnnormalized.length) {
    return null;
  }

  const targetFields = hasUnnormalized
    ? RAW_ADDRESS_OUTPUT_FIELDS
    : NORMALIZED_ADDRESS_FIELDS;

  const output = {};

  if (hasUnnormalized) {
    output.unnormalized_address = trimmedUnnormalized;
  }

  for (const field of targetFields) {
    if (field === "unnormalized_address") continue;

    const value = Object.prototype.hasOwnProperty.call(address, field)
      ? address[field]
      : null;

    if (value === undefined || value === null) {
      output[field] = null;
      continue;
    }

    if (typeof value === "string") {
      const trimmed = value.trim();
      output[field] = trimmed.length ? trimmed : null;
      continue;
    }

    if (typeof value === "number") {
      output[field] = Number.isFinite(value) ? value : null;
      continue;
    }

    output[field] = value;
  }

  if (!output.postal_code) {
    output.plus_four_postal_code = null;
  }

  if (output.state_code && !output.country_code) {
    output.country_code = "US";
  }

  return output;
}

function ensureRawAddressFieldCoverage(address, allowedFields = RAW_ADDRESS_ALLOWED_FIELDS) {
  if (!address || typeof address !== "object") return null;

  const unnormalized =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!unnormalized.length) {
    return null;
  }

  const fields =
    Array.isArray(allowedFields) && allowedFields.length
      ? allowedFields
      : RAW_ADDRESS_ALLOWED_FIELDS;
  const allowedSet = new Set(fields);
  const result = {
    unnormalized_address: unnormalized,
  };

  for (const field of fields) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      continue;
    }
    const value = address[field];
    if (value === undefined || value === null) {
      continue;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      if (Number.isFinite(numeric)) {
        result[field] = numeric;
      }
      continue;
    }

    const sanitized = sanitizeAddressFieldValue
      ? sanitizeAddressFieldValue(field, value)
      : value;
    if (sanitized === undefined || sanitized === null) {
      continue;
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      if (!trimmed.length) {
        continue;
      }
      result[field] = trimmed;
      continue;
    }
    result[field] = sanitized;
  }

  if (result.state_code && !result.country_code) {
    result.country_code = "US";
  }

  if (
    !result.postal_code &&
    Object.prototype.hasOwnProperty.call(result, "plus_four_postal_code")
  ) {
    delete result.plus_four_postal_code;
  }

  for (const [key, value] of Object.entries(address)) {
    if (key === "unnormalized_address") continue;
    if (allowedSet.has(key)) continue;
    if (value === undefined) continue;

    if (key === "request_identifier") {
      const normalizedIdentifier = safeNullIfEmpty(
        typeof value === "string" ? value : null,
      );
      result.request_identifier =
        normalizedIdentifier === undefined ? null : normalizedIdentifier;
      continue;
    }

    if (key === "source_http_request") {
      const prepared = prepareSourceHttpRequest(value);
      if (prepared) {
        result.source_http_request = deepClone(prepared);
      }
      continue;
    }

    result[key] = value;
  }

  return result;
}

function writeAddressPayload(addressPath, payload) {
  if (!addressPath || !payload || typeof payload !== "object") {
    return;
  }

  const workingPayload = deepClone(payload);
  if (shouldTreatAddressAsNormalized(workingPayload)) {
    if (
      Object.prototype.hasOwnProperty.call(
        workingPayload,
        "unnormalized_address",
      )
    ) {
      delete workingPayload.unnormalized_address;
    }
    const normalizedOutput =
      ensureAddressOutputFieldPresence(workingPayload) || workingPayload;
    if (!writeSchemaAlignedAddress(addressPath, normalizedOutput)) {
      removeFileIfExists(addressPath);
    }
    return;
  }

  const rawValue =
    typeof workingPayload.unnormalized_address === "string"
      ? workingPayload.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    removeFileIfExists(addressPath);
    return;
  }

  if (
    hasMeaningfulAddressValue(workingPayload.state_code) &&
    !hasMeaningfulAddressValue(workingPayload.country_code)
  ) {
    workingPayload.country_code = "US";
  }

  if (
    Object.prototype.hasOwnProperty.call(
      workingPayload,
      "request_identifier",
    )
  ) {
    const normalizedIdentifier = safeNullIfEmpty(
      workingPayload.request_identifier,
    );
    if (normalizedIdentifier === undefined) {
      delete workingPayload.request_identifier;
    } else {
      workingPayload.request_identifier =
        normalizedIdentifier === null ? null : normalizedIdentifier;
    }
  }

  const minimalPayload = buildMinimalRawAddressSurface({
    ...workingPayload,
    unnormalized_address: rawValue,
  });

  if (!writeSchemaAlignedAddress(addressPath, minimalPayload)) {
    removeFileIfExists(addressPath);
  }
}

function enforceMinimalRawAddressOutput(addressPath) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressPath);
    return;
  }

  const normalizedSurface =
    ensureAddressOutputFieldPresence({ ...payload }) || { ...payload };
  const hasStructuredCoverage = COUNTY_STRICT_NORMALIZED_FIELDS.every(
    (field) => hasMeaningfulAddressValue(normalizedSurface[field]),
  );

  if (hasStructuredCoverage) {
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedSurface,
        "unnormalized_address",
      )
    ) {
      delete normalizedSurface.unnormalized_address;
    }
    writeAddressPayload(addressPath, normalizedSurface);
    return;
  }

  const rawValue =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    removeFileIfExists(addressPath);
    return;
  }

  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const preparedPayload = {
    ...payload,
    unnormalized_address: rawValue,
  };

  if (requestIdentifier !== undefined) {
    preparedPayload.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  } else if (
    !Object.prototype.hasOwnProperty.call(
      preparedPayload,
      "request_identifier",
    )
  ) {
    preparedPayload.request_identifier = null;
  }

  const paddedPayload =
    ensureCountyRawRequiredFieldSurface(preparedPayload) || preparedPayload;
  enforceMinimalRawAddressSurface(paddedPayload);
  paddedPayload.__force_raw_variant = true;

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(paddedPayload, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to persist minimal raw address output:", error);
  }
}

function enforceAddressOneOfTerminalVariant(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressPath);
    return;
  }

  const normalizedSurface =
    typeof ensureNormalizedAddressSchemaSurface === "function"
      ? ensureNormalizedAddressSchemaSurface({ ...payload })
      : { ...payload };

  const canEmitStrictNormalized =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...normalizedSurface });

  if (canEmitStrictNormalized) {
    const normalizedOutput =
      typeof buildNormalizedAddressOutputForSchema === "function"
        ? buildNormalizedAddressOutputForSchema(normalizedSurface)
        : { ...normalizedSurface };

    if (normalizedOutput && typeof normalizedOutput === "object") {
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "unnormalized_address",
        )
      ) {
        delete normalizedOutput.unnormalized_address;
      }

      const normalizedRequestId = safeNullIfEmpty(
        payload.request_identifier != null
          ? payload.request_identifier
          : normalizedOutput.request_identifier,
      );
      if (normalizedRequestId !== undefined) {
        normalizedOutput.request_identifier =
          normalizedRequestId === null ? null : normalizedRequestId;
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "request_identifier",
        )
      ) {
        normalizedOutput.request_identifier = null;
      }

      const preparedSource = prepareSourceHttpRequest(
        payload.source_http_request || normalizedOutput.source_http_request,
      );
      if (preparedSource) {
        normalizedOutput.source_http_request = deepClone(preparedSource);
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "source_http_request",
        )
      ) {
        normalizedOutput.source_http_request = null;
      }

      writeAddressJSONBypass(addressPath, normalizedOutput);
      overwriteAddressRelationshipFilesWithNull([
        path.dirname(addressPath),
        path.join("relationships"),
      ]);
      return;
    }
  }

  const {
    rawFallbackPaths = [],
    requestIdentifierCandidates = [],
    sourceHttpRequestCandidates = [],
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};
  const rawCandidates = [payload.unnormalized_address];
  const fallbackPayloads = [];

  if (Array.isArray(rawFallbackPaths)) {
    for (const candidatePath of rawFallbackPaths) {
      if (typeof candidatePath !== "string" || !candidatePath.trim().length) {
        continue;
      }
      const fallbackPayload = readJSONIfExists(candidatePath);
      if (
        fallbackPayload &&
        typeof fallbackPayload.unnormalized_address === "string" &&
        fallbackPayload.unnormalized_address.trim().length
      ) {
        rawCandidates.push(fallbackPayload.unnormalized_address);
        fallbackPayloads.push(fallbackPayload);
      }
    }
  }

  const resolvedRaw = resolveFirstNonEmptyString(rawCandidates);
  if (!resolvedRaw) {
    removeFileIfExists(addressPath);
    return;
  }

  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const supplementalRequestIdentifiers = Array.isArray(
    requestIdentifierCandidates,
  )
    ? requestIdentifierCandidates
    : [];
  let resolvedRequestIdentifier =
    requestIdentifier !== undefined && requestIdentifier !== null
      ? requestIdentifier
      : null;
  if (
    resolvedRequestIdentifier === null ||
    resolvedRequestIdentifier === undefined
  ) {
    for (const candidate of supplementalRequestIdentifiers) {
      const normalizedCandidate =
        candidate === undefined || candidate === null
          ? null
          : safeNullIfEmpty(String(candidate));
      if (normalizedCandidate) {
        resolvedRequestIdentifier = normalizedCandidate;
        break;
      }
    }
  }

  let preparedSource = prepareSourceHttpRequest(payload.source_http_request);
  if (!preparedSource && Array.isArray(sourceHttpRequestCandidates)) {
    for (const candidate of sourceHttpRequestCandidates) {
      const normalizedSource = prepareSourceHttpRequest(candidate);
      if (normalizedSource) {
        preparedSource = deepClone(normalizedSource);
        break;
      }
    }
  }

  const latitude = parseCoordinate(payload.latitude);
  const longitude = parseCoordinate(payload.longitude);
  const rawFieldSources = [payload, ...fallbackPayloads].filter(
    (source) => source && typeof source === "object",
  );

  const strictRawPayload =
    buildStrictMinimalRawAddressPayload(resolvedRaw, {
      fieldSources: rawFieldSources,
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) || {
      unnormalized_address: resolvedRaw.trim(),
    };

  strictRawPayload.request_identifier =
    resolvedRequestIdentifier === undefined
      ? null
      : resolvedRequestIdentifier === null
        ? null
        : resolvedRequestIdentifier;

  if (preparedSource) {
    strictRawPayload.source_http_request = deepClone(preparedSource);
  } else if (
    Object.prototype.hasOwnProperty.call(payload, "source_http_request") &&
    payload.source_http_request === null
  ) {
    strictRawPayload.source_http_request = null;
  } else if (
    !Object.prototype.hasOwnProperty.call(strictRawPayload, "source_http_request")
  ) {
    strictRawPayload.source_http_request = null;
  }

  if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
    strictRawPayload.latitude = latitude;
    strictRawPayload.longitude = longitude;
  }

  collapseRawAddressToUnnormalizedOnly(strictRawPayload);
  writeAddressJSONBypass(addressPath, strictRawPayload);
}

function rehydrateRawAddressPayloadOnDisk(addressPath, options = {}) {
  const {
    rawFallbackPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const fallbackRawSource = readJSONIfExists(rawFallbackPath);
  const seedSource = readJSONIfExists(seedPath);

  const rawValue =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";

  let hydrated = null;
  if (rawValue.length) {
    const mergedSource = Object.assign(
      {},
      fallbackRawSource && typeof fallbackRawSource === "object"
        ? fallbackRawSource
        : {},
      seedSource && typeof seedSource === "object" ? seedSource : {},
      payload,
    );
    hydrated =
      ensureRawAddressSchemaSurface(mergedSource) ||
      ensureRawAddressSchemaSurface(payload);
    if (!hydrated) {
      hydrated = {
        ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE,
        unnormalized_address: rawValue,
      };
    }

    const resolvedCounty = resolveFirstNonEmptyString([
      payload.county_name,
      fallbackRawSource && fallbackRawSource.county_name,
      fallbackRawSource && fallbackRawSource.county_jurisdiction,
      seedSource && seedSource.county_name,
      defaultCountyName,
    ]);
    if (!hasMeaningfulAddressValue(hydrated.county_name) && resolvedCounty) {
      hydrated.county_name = resolvedCounty;
    }

    const resolvedState = resolveFirstNonEmptyString([
      payload.state_code,
      fallbackRawSource && fallbackRawSource.state_code,
      defaultStateCode,
    ]);
    if (!hasMeaningfulAddressValue(hydrated.state_code) && resolvedState) {
      hydrated.state_code = resolvedState;
    }

    if (
      hasMeaningfulAddressValue(hydrated.state_code) &&
      !hasMeaningfulAddressValue(hydrated.country_code)
    ) {
      hydrated.country_code = (defaultCountryCode || "US").toUpperCase();
    }

    if (!hasMeaningfulAddressValue(hydrated.postal_code)) {
      hydrated.plus_four_postal_code = null;
    }

    const resolvedRequestIdentifier = resolveRequestIdentifierCandidate(
      payload.request_identifier,
      fallbackRawSource && fallbackRawSource.request_identifier,
      seedSource && seedSource.request_identifier,
    );
    hydrated.request_identifier =
      resolvedRequestIdentifier === undefined
        ? null
        : resolvedRequestIdentifier;

    const resolvedSource = resolveSourceHttpRequestCandidate(
      payload.source_http_request,
      fallbackRawSource && fallbackRawSource.source_http_request,
      seedSource && seedSource.source_http_request,
    );
    hydrated.source_http_request = resolvedSource
      ? deepClone(prepareSourceHttpRequest(resolvedSource))
      : null;
  } else if (typeof ensureAddressOutputFieldPresence === "function") {
    hydrated = ensureAddressOutputFieldPresence({ ...payload });
  }

  if (!hydrated) {
    return;
  }

  if (!hydrated.postal_code) {
    hydrated.plus_four_postal_code = null;
  }
  if (hydrated.state_code && !hydrated.country_code) {
    hydrated.country_code = (defaultCountryCode || "US").toUpperCase();
  }

  writeJSON(addressPath, hydrated);
}


function ensureRawAddressSchemaSurface(address, options = {}) {
  if (!address || typeof address !== "object") return null;

  const trimmedUnnormalized =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!trimmedUnnormalized.length) {
    return null;
  }

  const normalized = {
    unnormalized_address: trimmedUnnormalized,
  };

  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      normalized[field] = null;
      continue;
    }

    let value = address[field];

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      value = parseCoordinate(value);
    } else if (typeof value === "string") {
      value = value.trim();
      if (!value.length) {
        value = null;
      }
    }

    normalized[field] =
      value === undefined || value === "" ? null : value;
  }

  if (!normalized.postal_code) {
    normalized.plus_four_postal_code = null;
  }
  if (normalized.state_code && !normalized.country_code) {
    normalized.country_code = "US";
  }

  return normalized;
}

function enforceAddressSchemaOneOfSurface(addressPath, options = {}) {
  const {
    rawFallbackPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  if (!addressPath) {
    return;
  }

  const existingPayload = readJSONIfExists(addressPath);
  const rawFallbackSource = readJSONIfExists(rawFallbackPath);
  const seedSource = readJSONIfExists(seedPath);

  const normalizedProbe =
    existingPayload && typeof existingPayload === "object"
      ? ensureAddressOutputFieldPresence
        ? ensureAddressOutputFieldPresence({ ...existingPayload })
        : { ...existingPayload }
      : null;

  if (
    normalizedProbe &&
    hasStrictNormalizedAddressCoverage({ ...normalizedProbe })
  ) {
    const normalizedOutput =
      buildNormalizedAddressOutputForSchema({ ...normalizedProbe }) || null;
    if (normalizedOutput) {
      const normalizedRequestIdentifier = resolveRequestIdentifierCandidate(
        existingPayload && existingPayload.request_identifier,
        rawFallbackSource && rawFallbackSource.request_identifier,
        seedSource && seedSource.request_identifier,
      );
      if (normalizedRequestIdentifier !== undefined) {
        normalizedOutput.request_identifier =
          normalizedRequestIdentifier === null
            ? null
            : normalizedRequestIdentifier;
      }
      const normalizedSource = resolveSourceHttpRequestCandidate(
        existingPayload && existingPayload.source_http_request,
        rawFallbackSource && rawFallbackSource.source_http_request,
        seedSource && seedSource.source_http_request,
      );
      if (normalizedSource) {
        normalizedOutput.source_http_request = deepClone(
          prepareSourceHttpRequest(normalizedSource),
        );
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "source_http_request",
        )
      ) {
        normalizedOutput.source_http_request = null;
      }
      writeJSON(addressPath, normalizedOutput);
      return;
    }
  }

  const sources = [existingPayload, rawFallbackSource, seedSource].filter(
    (source) => source && typeof source === "object",
  );

  const rawCandidates = [];
  const pushRawCandidate = (value) => {
    if (typeof value !== "string") return;
    const trimmed = value.trim();
    if (trimmed.length) {
      rawCandidates.push(trimmed);
    }
  };

  const RAW_SOURCE_FIELDS = [
    "unnormalized_address",
    "full_address",
    "site_address",
    "address",
    "raw_address",
    "location_address",
    "mail_address",
  ];

  for (const source of sources) {
    for (const field of RAW_SOURCE_FIELDS) {
      pushRawCandidate(source[field]);
    }
    if (Array.isArray(source.lines) && source.lines.length) {
      const joined = source.lines
        .map((line) => (typeof line === "string" ? line.trim() : ""))
        .filter((line) => line.length)
        .join(", ");
      pushRawCandidate(joined);
    }
  }

  if (typeof composeFallbackUnnormalizedAddressFromFields === "function") {
    pushRawCandidate(
      composeFallbackUnnormalizedAddressFromFields(
        Object.assign({}, ...sources),
      ),
    );
  }

  const resolvedRaw = resolveFirstNonEmptyString(rawCandidates);
  if (!resolvedRaw) {
    removeFileIfExists(addressPath);
    return;
  }

  const aggregated = {};
  const adoptFromSource = (source, { overwrite = false } = {}) => {
    if (!source || typeof source !== "object") return;
    for (const field of RAW_ADDRESS_ALLOWED_FIELDS) {
      if (
        !overwrite &&
        hasMeaningfulAddressValue(aggregated[field])
      ) {
        continue;
      }
      if (!Object.prototype.hasOwnProperty.call(source, field)) {
        continue;
      }
      let value = source[field];
      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const coordinate = parseCoordinate(value);
        if (Number.isFinite(coordinate)) {
          aggregated[field] = coordinate;
        } else if (overwrite) {
          aggregated[field] = null;
        }
        continue;
      }
      if (typeof value === "string") {
        const trimmed = value.trim();
        if (!trimmed.length) {
          if (overwrite) {
            aggregated[field] = null;
          }
          continue;
        }
        aggregated[field] = trimmed;
        continue;
      }
      if (value !== undefined) {
        aggregated[field] = value;
      }
    }
    if (
      !hasMeaningfulAddressValue(aggregated.county_name) &&
      hasMeaningfulAddressValue(source.county_jurisdiction)
    ) {
      aggregated.county_name = source.county_jurisdiction;
    }
  };

  adoptFromSource(rawFallbackSource);
  adoptFromSource(seedSource);
  adoptFromSource(existingPayload, { overwrite: true });

  aggregated.unnormalized_address = resolvedRaw;

  if (!hasMeaningfulAddressValue(aggregated.county_name) && defaultCountyName) {
    aggregated.county_name = defaultCountyName;
  }
  if (!hasMeaningfulAddressValue(aggregated.state_code) && defaultStateCode) {
    aggregated.state_code = defaultStateCode;
  }
  if (
    hasMeaningfulAddressValue(aggregated.state_code) &&
    !hasMeaningfulAddressValue(aggregated.country_code)
  ) {
    aggregated.country_code = (defaultCountryCode || "US").toUpperCase();
  }

  if (!hasMeaningfulAddressValue(aggregated.postal_code)) {
    aggregated.plus_four_postal_code = null;
  }

  const requestIdentifier = resolveRequestIdentifierCandidate(
    existingPayload && existingPayload.request_identifier,
    rawFallbackSource && rawFallbackSource.request_identifier,
    seedSource && seedSource.request_identifier,
  );

  const sourceCandidate = resolveSourceHttpRequestCandidate(
    existingPayload && existingPayload.source_http_request,
    rawFallbackSource && rawFallbackSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );

  if (requestIdentifier !== undefined) {
    aggregated.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }

  if (sourceCandidate) {
    aggregated.source_http_request = deepClone(
      prepareSourceHttpRequest(sourceCandidate),
    );
  } else if (
    Object.prototype.hasOwnProperty.call(aggregated, "source_http_request")
  ) {
    aggregated.source_http_request = null;
  }

  let surfaced =
    ensureRawAddressSchemaSurface(aggregated) ||
    ensureRawVariantFieldSurface(aggregated) ||
    null;

  if (!surfaced) {
    surfaced = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
  }

  surfaced.unnormalized_address = resolvedRaw;

  if (!surfaced.postal_code) {
    surfaced.plus_four_postal_code = null;
  }
  if (surfaced.state_code && !surfaced.country_code) {
    surfaced.country_code = (defaultCountryCode || "US").toUpperCase();
  }

  if (!Object.prototype.hasOwnProperty.call(surfaced, "request_identifier")) {
    surfaced.request_identifier =
      requestIdentifier === undefined ? null : requestIdentifier;
  } else if (requestIdentifier !== undefined) {
    surfaced.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }

  if (sourceCandidate) {
    surfaced.source_http_request = deepClone(
      prepareSourceHttpRequest(sourceCandidate),
    );
  } else if (
    Object.prototype.hasOwnProperty.call(surfaced, "source_http_request")
  ) {
    surfaced.source_http_request = null;
  }

  let finalPayload =
    buildStrictRawOnlyAddress(surfaced) ||
    buildMinimalRawAddressForSchema(surfaced) || {
      unnormalized_address: resolvedRaw,
    };

  if (
    requestIdentifier !== undefined &&
    !Object.prototype.hasOwnProperty.call(finalPayload, "request_identifier")
  ) {
    finalPayload.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }

  if (
    sourceCandidate &&
    !Object.prototype.hasOwnProperty.call(finalPayload, "source_http_request")
  ) {
    const prepared = prepareSourceHttpRequest(sourceCandidate);
    if (prepared) {
      finalPayload.source_http_request = deepClone(prepared);
    }
  }

  fs.writeFileSync(addressPath, JSON.stringify(finalPayload, null, 2));
}

function hasMeaningfulAddressValue(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === "number") return Number.isFinite(value);
  if (typeof value === "string") {
    return value.trim().length > 0;
  }
  return true;
}

function hasStrictCountyAddressCoverage(address) {
  if (!address || typeof address !== "object") {
    return false;
  }

  const normalizedSurface =
    typeof ensureNormalizedAddressSchemaSurface === "function"
      ? ensureNormalizedAddressSchemaSurface({ ...address })
      : { ...address };

  const strictSurface = { ...normalizedSurface };

  const hasAllRequiredFields = COUNTY_NORMALIZED_REQUIRED_FIELDS.every((field) => {
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(strictSurface[field]);
      if (!Number.isFinite(numeric)) {
        return false;
      }
      strictSurface[field] = numeric;
      return true;
    }

    const sanitized = sanitizeAddressFieldValue(field, strictSurface[field]);
    if (!hasMeaningfulAddressValue(sanitized)) {
      return false;
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      if (!trimmed.length) {
        return false;
      }
      strictSurface[field] = trimmed;
      return true;
    }
    strictSurface[field] = sanitized;
    return true;
  });

  if (!hasAllRequiredFields) {
    return false;
  }

  Object.assign(address, strictSurface);
  return true;
}

function hasNormalizedCoreFieldCoverage(address) {
  if (!address || typeof address !== "object") {
    return false;
  }

  const surfaced =
    typeof ensureNormalizedAddressSchemaSurface === "function"
      ? ensureNormalizedAddressSchemaSurface({ ...address })
      : { ...address };

  for (const field of COUNTY_NORMALIZED_CORE_FIELDS) {
    const value = surfaced[field];
    if (!hasMeaningfulAddressValue(value)) {
      return false;
    }
    if (typeof value === "string") {
      surfaced[field] = value.trim();
    }
  }

  for (const coordinateField of ADDRESS_COORDINATE_FIELDS) {
    const numeric = parseCoordinate(surfaced[coordinateField]);
    if (!Number.isFinite(numeric)) {
      return false;
    }
    surfaced[coordinateField] = numeric;
  }

  if (!surfaced.postal_code) {
    surfaced.plus_four_postal_code = null;
  }

  if (surfaced.state_code && !surfaced.country_code) {
    surfaced.country_code = "US";
  }

  Object.assign(address, surfaced);
  return true;
}

function writeAddressPayloadDirect(addressPath, payload) {
  if (
    !addressPath ||
    typeof addressPath !== "string" ||
    !payload ||
    typeof payload !== "object"
  ) {
    return false;
  }

  let payloadToWrite = payload;
  if (!Array.isArray(payload) && typeof payload === "object") {
    payloadToWrite = deepClone(payload) || {};
    const rawValue =
      typeof payloadToWrite.unnormalized_address === "string"
        ? payloadToWrite.unnormalized_address.trim()
        : "";

    const hasNormalizedCoverage =
      typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
      hasStrictCountyNormalizedSchemaCoverage({ ...payloadToWrite });

    if (hasNormalizedCoverage) {
      if (rawValue.length) {
        delete payloadToWrite.unnormalized_address;
      }
    } else if (rawValue.length) {
      payloadToWrite.unnormalized_address = rawValue;
      enforceRawVariantAllowedFields(payloadToWrite);
    }
  }

  try {
    addressWriteLocked = true;
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(payloadToWrite, null, 2)}\n`,
    );
    return true;
  } catch (error) {
    console.error("Failed to persist projected address payload:", error);
    return false;
  } finally {
    addressWriteLocked = false;
  }
}

function emitFinalNormalizedOrRawAddress(addressPath, options = {}) {
  enforceCountyAddressSchemaVariant(addressPath, options);
}

function buildStrictRawOnlyAddress(address) {
  if (!address || typeof address !== "object") {
    return null;
  }

  const rawValue =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return null;
  }

  const strictRaw = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: rawValue,
  };

  if (
    Object.prototype.hasOwnProperty.call(address, "request_identifier")
  ) {
    const normalizedIdentifier = safeNullIfEmpty(address.request_identifier);
    strictRaw.request_identifier =
      normalizedIdentifier === undefined ? null : normalizedIdentifier;
  }

  if (
    Object.prototype.hasOwnProperty.call(address, "source_http_request")
  ) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    if (prepared) {
      strictRaw.source_http_request = deepClone(prepared);
    }
  }

  for (const field of RAW_ADDRESS_ALLOWED_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      continue;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(address[field]);
      strictRaw[field] = Number.isFinite(numeric) ? numeric : null;
      continue;
    }
    const sanitized = normalizeAddressFieldForSchema(field, address[field]);
    if (sanitized !== undefined && sanitized !== null) {
      strictRaw[field] = sanitized;
    }
  }

  if (
    (strictRaw.latitude == null && strictRaw.longitude != null) ||
    (strictRaw.latitude != null && strictRaw.longitude == null)
  ) {
    strictRaw.latitude = null;
    strictRaw.longitude = null;
  }

  return strictRaw;
}

function buildOneOfCompliantRawPayload(rawValue, options = {}) {
  const trimmed =
    typeof rawValue === "string" && rawValue.trim().length
      ? rawValue.trim()
      : "";
  if (!trimmed.length) {
    return null;
  }

  const {
    fieldSources = [],
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = null,
  } = options || {};

  const workingSources = Array.isArray(fieldSources)
    ? fieldSources.filter((source) => source && typeof source === "object")
    : [];

  const derivedFromRaw =
    typeof deriveNormalizedAddressFieldsFromRaw === "function"
      ? deriveNormalizedAddressFieldsFromRaw(trimmed)
      : null;
  if (derivedFromRaw && typeof derivedFromRaw === "object") {
    workingSources.unshift(derivedFromRaw);
  }

  const parcelIdentifiers = [];
  workingSources.forEach((source) => {
    ["parcel_identifier", "parcel_id", "pcn"].forEach((key) => {
      if (hasMeaningfulAddressValue(source[key])) {
        parcelIdentifiers.push(String(source[key]));
      }
    });
  });
  parcelIdentifiers.forEach((identifier) => {
    const grid = parseGridFromPcn(identifier);
    if (grid) {
      workingSources.unshift(grid);
    }
  });

  const payload = {
    unnormalized_address: trimmed,
  };

  const normalizedCounty =
    typeof defaultCountyName === "string" && defaultCountyName.length
      ? titleCaseCounty(defaultCountyName)
      : null;

  COUNTY_REQUIRED_NORMALIZED_FIELDS.forEach((field) => {
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const coordinateSource = resolveFirstMeaningfulAddressField(
        field,
        workingSources,
      );
      const numeric = parseCoordinate(coordinateSource);
      payload[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }

    let resolved = resolveFirstMeaningfulAddressField(field, workingSources);
    if (!hasMeaningfulAddressValue(resolved)) {
      if (field === "county_name") {
        resolved = normalizedCounty || null;
      } else if (field === "state_code") {
        resolved = defaultStateCode || null;
      } else if (field === "country_code") {
        resolved = defaultCountryCode || null;
      } else {
        resolved = null;
      }
    }

    if (resolved === undefined || resolved === null) {
      payload[field] = null;
      return;
    }

    const sanitized = sanitizeAddressFieldValue
      ? sanitizeAddressFieldValue(field, resolved)
      : resolved;
    payload[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  });

  if (
    !Object.prototype.hasOwnProperty.call(payload, "plus_four_postal_code") ||
    !hasMeaningfulAddressValue(payload.plus_four_postal_code)
  ) {
    payload.plus_four_postal_code = null;
  }

  return payload;
}

function hasRawAddressRequiredFields(address) {
  if (!address || typeof address !== "object") return false;

  const trimmedUnnormalized =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!trimmedUnnormalized.length) {
    return false;
  }

  address.unnormalized_address = trimmedUnnormalized;

  const parsedLatitude = parseCoordinate(address.latitude);
  const parsedLongitude = parseCoordinate(address.longitude);
  const hasLatitude = Number.isFinite(parsedLatitude);
  const hasLongitude = Number.isFinite(parsedLongitude);

  address.latitude = hasLatitude ? parsedLatitude : null;
  address.longitude = hasLongitude ? parsedLongitude : null;

  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      continue;
    }

    if (Object.prototype.hasOwnProperty.call(address, field)) {
      const normalized = normalizeAddressFieldForSchema(field, address[field]);
      address[field] =
        normalized === undefined || normalized === null ? null : normalized;
    } else {
      address[field] = null;
    }
  }

  if (
    hasMeaningfulAddressValue(address.state_code) &&
    !hasMeaningfulAddressValue(address.country_code)
  ) {
    address.country_code = "US";
  }

  if (!hasMeaningfulAddressValue(address.postal_code)) {
    address.plus_four_postal_code = null;
  } else if (
    !Object.prototype.hasOwnProperty.call(address, "plus_four_postal_code")
  ) {
    address.plus_four_postal_code = null;
  }

  return true;
}

function hasRawAddressStrictValues(address) {
  if (!address || typeof address !== "object") return false;

  const hasCoreValues = RAW_ADDRESS_STRICT_VALUE_FIELDS.every((field) =>
    hasMeaningfulAddressValue(address[field]),
  );
  if (!hasCoreValues) {
    return false;
  }

  return RAW_ADDRESS_STRICT_GRID_FIELDS.every((field) =>
    hasMeaningfulAddressValue(address[field]),
  );
}

function hasRawAddressSurfaceCoverage(address) {
  if (!address || typeof address !== "object") return false;
  for (const field of RAW_ADDRESS_REQUIRED_FIELD_SURFACE) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      return false;
    }
  }
  return true;
}

function ensureRawAddressRequiredCoverage(rawAddress, unnormalizedValue) {
  if (!rawAddress || typeof rawAddress !== "object") return null;

  const normalizedUnnormalized =
    typeof unnormalizedValue === "string" ? unnormalizedValue.trim() : "";

  const candidate = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    ...rawAddress,
  };

  if (
    normalizedUnnormalized.length &&
    (!Object.prototype.hasOwnProperty.call(candidate, "unnormalized_address") ||
      !hasMeaningfulAddressValue(candidate.unnormalized_address))
  ) {
    candidate.unnormalized_address = normalizedUnnormalized;
  }

  const trimmedUnnormalized =
    typeof candidate.unnormalized_address === "string"
      ? candidate.unnormalized_address.trim()
      : "";
  if (!trimmedUnnormalized.length) {
    return null;
  }
  candidate.unnormalized_address = trimmedUnnormalized;

  if (
    hasMeaningfulAddressValue(candidate.state_code) &&
    !hasMeaningfulAddressValue(candidate.country_code)
  ) {
    candidate.country_code = "US";
  }

  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(candidate, field)) {
      candidate[field] = null;
      continue;
    }

    const value = candidate[field];
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      candidate[field] = numeric != null ? numeric : null;
      continue;
    }

    if (typeof value === "string") {
      const trimmed = value.trim();
      candidate[field] = trimmed.length ? trimmed : null;
      continue;
    }

    if (value === undefined) {
      candidate[field] = null;
    }
  }

  if (!candidate.postal_code) {
    candidate.plus_four_postal_code = null;
  }

  backfillNormalizedAddressFields(candidate, {
    unnormalized: trimmedUnnormalized,
  });

  const hasLatitude = Number.isFinite(candidate.latitude);
  const hasLongitude = Number.isFinite(candidate.longitude);
  if (hasLatitude !== hasLongitude) {
    candidate.latitude = null;
    candidate.longitude = null;
  }

  return candidate;
}

function isRawAddressSchemaReady(address) {
  if (!address || typeof address !== "object") return false;
  const unnormalized =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!unnormalized.length) {
    return false;
  }

  for (const field of RAW_ADDRESS_ALLOWED_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      return false;
    }
  }

  if (!hasRawAddressRequiredFields(address)) {
    return false;
  }

  return true;
}

function enforceRawAddressSchemaSurface(address, allowedFields = RAW_ADDRESS_OUTPUT_FIELDS) {
  if (!address || typeof address !== "object") return null;

  const unnormalized =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!unnormalized.length) {
    return null;
  }

  const fields =
    Array.isArray(allowedFields) && allowedFields.length
      ? allowedFields
      : RAW_ADDRESS_OUTPUT_FIELDS;

  const normalized = { unnormalized_address: unnormalized };
  for (const field of fields) {
    let value = Object.prototype.hasOwnProperty.call(address, field)
      ? address[field]
      : null;

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      value = parseCoordinate(value);
    } else if (value === undefined) {
      value = null;
    } else if (typeof value === "string") {
      const trimmed = value.trim();
      value = trimmed.length ? trimmed : null;
    }

    normalized[field] = value != null ? value : null;
  }

  if (!normalized.postal_code) {
    normalized.plus_four_postal_code = null;
  }
  if (normalized.state_code && !normalized.country_code) {
    normalized.country_code = "US";
  }

  for (const field of fields) {
    if (!Object.prototype.hasOwnProperty.call(normalized, field)) {
      normalized[field] = null;
    }
  }

  return normalized;
}

function ensureAddressFieldSurface(target, fields) {
  if (!target || typeof target !== "object") return;
  if (!Array.isArray(fields) || !fields.length) return;
  for (const field of fields) {
    if (!Object.prototype.hasOwnProperty.call(target, field)) {
      target[field] = null;
    }
  }
}

function backfillNormalizedAddressFields(target, options = {}) {
  if (!target || typeof target !== "object") return;

  const {
    unnormalized,
    fallbackCity,
    fallbackState,
    fallbackPostal,
    fallbackPlus4,
    fallbackCounty,
    fallbackCountry = "US",
    fallbackMunicipality,
    fallbackUnit,
    fallbackRoute,
    fallbackLatitude,
    fallbackLongitude,
    fallbackTownship,
    fallbackRange,
    fallbackSection,
    fallbackBlock,
    fallbackLot,
    fallbackStreetNumber,
    fallbackStreetName,
    fallbackStreetPreDirectional,
    fallbackStreetPostDirectional,
    fallbackStreetSuffix,
  } = options || {};

  if (typeof unnormalized === "string" && unnormalized.trim().length) {
    enrichAddressFromUnnormalized(target, unnormalized);
  }

  const assignIfMissing = (field, candidate) => {
    const hasRawUnnormalized =
      typeof target.unnormalized_address === "string" &&
      target.unnormalized_address.trim().length > 0;
    if (hasRawUnnormalized && RAW_ADDRESS_EXCLUDED_FIELDS.has(field)) {
      return;
    }
    if (hasMeaningfulAddressValue(target[field])) return;
    const normalizedValue = normalizeAddressFieldForSchema(field, candidate);
    if (normalizedValue === undefined || normalizedValue === null) return;
    target[field] = normalizedValue;
  };

  const assignCoordinateIfMissing = (field, candidate) => {
    if (Number.isFinite(target[field])) return;
    const numeric = parseCoordinate(candidate);
    if (Number.isFinite(numeric)) {
      target[field] = numeric;
    }
  };

  assignIfMissing("street_number", fallbackStreetNumber);
  assignIfMissing("street_name", fallbackStreetName);
  assignIfMissing("street_pre_directional_text", fallbackStreetPreDirectional);
  assignIfMissing("street_post_directional_text", fallbackStreetPostDirectional);
  assignIfMissing("street_suffix_type", fallbackStreetSuffix);

  assignIfMissing("city_name", fallbackCity);
  assignIfMissing("state_code", fallbackState);
  assignIfMissing("postal_code", fallbackPostal);
  assignIfMissing("plus_four_postal_code", fallbackPlus4);
  assignIfMissing("county_name", fallbackCounty);
  assignIfMissing("municipality_name", fallbackMunicipality);
  assignIfMissing("unit_identifier", fallbackUnit);
  assignIfMissing("route_number", fallbackRoute);
  assignIfMissing("township", fallbackTownship);
  assignIfMissing("range", fallbackRange);
  assignIfMissing("section", fallbackSection);
  assignIfMissing("block", fallbackBlock);
  assignIfMissing("lot", fallbackLot);

  if (hasMeaningfulAddressValue(target.state_code)) {
    assignIfMissing("country_code", fallbackCountry);
  }

  assignCoordinateIfMissing("latitude", fallbackLatitude);
  assignCoordinateIfMissing("longitude", fallbackLongitude);
}

function mergeAddressFieldsFromSource(target, source) {
  if (!target || typeof target !== "object") return;
  if (!source || typeof source !== "object") return;

  for (const field of ADDRESS_SCHEMA_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(source, field)) continue;
    if (
      field !== "unnormalized_address" &&
      typeof target.unnormalized_address === "string" &&
      target.unnormalized_address.trim().length &&
      RAW_ADDRESS_EXCLUDED_FIELDS.has(field)
    ) {
      continue;
    }
    if (field !== "unnormalized_address" && hasMeaningfulAddressValue(target[field])) {
      continue;
    }

    const candidate = source[field];
    if (candidate === undefined || candidate === null) {
      if (field === "unnormalized_address" && !hasMeaningfulAddressValue(target[field])) {
        target[field] = null;
      }
      continue;
    }

    if (field === "unnormalized_address") {
      const trimmed =
        typeof candidate === "string" ? candidate.trim() : String(candidate);
      if (trimmed.length) {
        target[field] = trimmed;
      }
      continue;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(candidate);
      if (Number.isFinite(numeric)) {
        target[field] = numeric;
      }
      continue;
    }

    if (typeof candidate === "string") {
      const normalized = normalizeAddressFieldForSchema(field, candidate);
      if (normalized !== undefined && normalized !== null) {
        target[field] = normalized;
      }
      continue;
    }

    if (typeof candidate === "number") {
      if (Number.isFinite(candidate)) {
        target[field] = candidate;
      }
      continue;
    }

    if (typeof candidate === "boolean") {
      target[field] = candidate;
    }
  }

  if (
    Object.prototype.hasOwnProperty.call(source, "request_identifier") &&
    !hasMeaningfulAddressValue(target.request_identifier)
  ) {
    const requestIdentifier = safeNullIfEmpty(source.request_identifier);
    if (requestIdentifier) {
      target.request_identifier = requestIdentifier;
    }
  }

  if (Object.prototype.hasOwnProperty.call(source, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(source.source_http_request);
    if (prepared) {
      target.source_http_request = deepClone(prepared);
    }
  }
}

function ensureRawVariantCriticalStrings(address, options = {}) {
  if (!address || typeof address !== "object") return;

  const {
    rawCandidates = [],
    parcelCandidates = [],
    defaultCounty = null,
    defaultState = null,
    defaultCountry = "US",
    cityFallbacks = [],
    municipalityFallbacks = [],
    postalFallbacks = [],
    plusFourFallbacks = [],
    coordinateFallback = null,
  } = options || {};

  const ensureFieldPresence = (field) => {
    if (!Object.prototype.hasOwnProperty.call(address, field)) {
      address[field] = null;
    }
  };

  for (const field of RAW_VARIANT_SCHEMA_FIELDS) {
    ensureFieldPresence(field);
  }
  ensureFieldPresence("plus_four_postal_code");
  ensureFieldPresence("route_number");
  ensureFieldPresence("unit_identifier");

  const uniqueRawStrings = [];
  const seenRaw = new Set();
  for (const candidate of rawCandidates) {
    if (typeof candidate !== "string") continue;
    const trimmed = candidate.trim();
    if (!trimmed.length || seenRaw.has(trimmed)) continue;
    seenRaw.add(trimmed);
    uniqueRawStrings.push(trimmed);
  }

  const assignIfMissing = (field, value, formatter) => {
    if (RAW_ADDRESS_EXCLUDED_FIELDS.has(field)) return;
    if (hasMeaningfulAddressValue(address[field])) return;
    if (value === undefined || value === null) return;
    const prepared =
      typeof formatter === "function" ? formatter(value) : value;
    const normalized = normalizeAddressFieldForSchema(field, prepared);
    if (normalized === undefined || normalized === null) return;
    address[field] = normalized;
  };

  const assignFromArray = (field, values, formatter) => {
    if (!Array.isArray(values) || !values.length) return;
    for (const candidate of values) {
      if (candidate === undefined || candidate === null) continue;
      assignIfMissing(field, candidate, formatter);
      if (hasMeaningfulAddressValue(address[field])) break;
    }
  };

  for (const raw of uniqueRawStrings) {
    const streetSegment = raw.includes(",")
      ? raw.split(",")[0].trim()
      : raw;
    const parsedStreet = parseLocationAddress(streetSegment);

    assignIfMissing("street_number", parsedStreet.streetNumber);
    if (parsedStreet.streetName) {
      assignIfMissing(
        "street_name",
        parsedStreet.streetName,
        (value) => {
          const formatted = formatStreetNameCase(value);
          return formatted ? formatted.toUpperCase() : value;
        },
      );
    }
    assignIfMissing(
      "street_pre_directional_text",
      parsedStreet.streetPreDirectional,
      (value) => value && value.toUpperCase(),
    );
    assignIfMissing(
      "street_post_directional_text",
      parsedStreet.streetPostDirectional,
      (value) => value && value.toUpperCase(),
    );
    assignIfMissing("street_suffix_type", parsedStreet.streetSuffix);
    assignIfMissing("unit_identifier", parsedStreet.unitIdentifier);
    assignIfMissing("route_number", parsedStreet.routeNumber);

    const trailingSegments = raw.includes(",")
      ? raw.split(",").slice(1).join(" ").trim()
      : "";
    const cityStateSource = trailingSegments.length ? trailingSegments : raw;
    const parsedCityState = parseCityStatePostal(cityStateSource);

    assignIfMissing(
      "city_name",
      parsedCityState.city,
      (value) => sanitizeCityName(value) || value,
    );
    assignIfMissing(
      "state_code",
      parsedCityState.state,
      (value) => value && value.toUpperCase(),
    );
    assignIfMissing("postal_code", parsedCityState.postal);
    assignIfMissing("plus_four_postal_code", parsedCityState.plus4);

    const postalPieces = extractPostalPieces(raw);
    if (postalPieces) {
      assignIfMissing("postal_code", postalPieces.postal);
      assignIfMissing("plus_four_postal_code", postalPieces.plus4);
    }
  }

  if (!hasMeaningfulAddressValue(address.street_name)) {
    for (const raw of uniqueRawStrings) {
      const candidate = raw.includes(",")
        ? raw.split(",")[0].trim()
        : raw.trim();
      const cleaned = cleanStreetCandidate(candidate);
      if (!cleaned) continue;
      const formatted = formatStreetNameCase(cleaned);
      if (formatted && formatted.trim().length) {
        address.street_name = formatted.toUpperCase();
        break;
      }
    }
  }

  if (
    !hasMeaningfulAddressValue(address.street_suffix_type) &&
    hasMeaningfulAddressValue(address.street_name)
  ) {
    const tokens = address.street_name.split(/\s+/).filter(Boolean);
    if (tokens.length > 1) {
      const suffixCandidate = tokens[tokens.length - 1];
      const mapped = mapStreetSuffixType(suffixCandidate);
      if (mapped) {
        address.street_suffix_type = mapped;
        address.street_name = tokens.slice(0, -1).join(" ");
      }
    }
  }

  assignFromArray("city_name", cityFallbacks, sanitizeCityName);
  assignFromArray("municipality_name", municipalityFallbacks, toTitleCase);
  assignFromArray("postal_code", postalFallbacks);
  assignFromArray("plus_four_postal_code", plusFourFallbacks);

  if (
    !hasMeaningfulAddressValue(address.municipality_name) &&
    hasMeaningfulAddressValue(address.city_name)
  ) {
    address.municipality_name = toTitleCase(address.city_name);
  }

  if (!hasMeaningfulAddressValue(address.county_name) && defaultCounty) {
    address.county_name = toTitleCase(defaultCounty);
  }
  if (!hasMeaningfulAddressValue(address.state_code) && defaultState) {
    address.state_code = defaultState;
  }
  if (!hasMeaningfulAddressValue(address.country_code) && defaultCountry) {
    address.country_code = defaultCountry;
  }

  const gridLengths = { township: 2, range: 2, section: 2, block: 3, lot: 4 };
  for (const candidate of parcelCandidates) {
    const parsed = deriveGridPartsFromPcn(candidate);
    if (!parsed || typeof parsed !== "object") continue;
    assignIfMissing("township", parsed.township);
    assignIfMissing("range", parsed.range);
    assignIfMissing("section", parsed.section);
    assignIfMissing("block", parsed.block);
    assignIfMissing("lot", parsed.lot);
  }
  for (const [field, length] of Object.entries(gridLengths)) {
    if (!hasMeaningfulAddressValue(address[field])) continue;
    address[field] = padGridValue(address[field], length);
  }

  if (coordinateFallback && typeof coordinateFallback === "object") {
    const latitude = parseCoordinate(coordinateFallback.latitude);
    const longitude = parseCoordinate(coordinateFallback.longitude);
    if (!Number.isFinite(address.latitude) && Number.isFinite(latitude)) {
      address.latitude = latitude;
    }
    if (!Number.isFinite(address.longitude) && Number.isFinite(longitude)) {
      address.longitude = longitude;
    }
  }

  if (
    (address.latitude == null && address.longitude != null) ||
    (address.latitude != null && address.longitude == null)
  ) {
    address.latitude = null;
    address.longitude = null;
  }

  if (!hasMeaningfulAddressValue(address.plus_four_postal_code)) {
    address.plus_four_postal_code = null;
  }
}

function normalizeAddressFieldForSchema(field, value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed.length) {
      return null;
    }
    value = trimmed;
  }

  if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
    const numeric = parseCoordinate(value);
    return Number.isFinite(numeric) ? numeric : null;
  }

  switch (field) {
    case "city_name":
      return sanitizeCityName(value);
    case "postal_code":
      return sanitizePostalCode(value);
    case "plus_four_postal_code":
      return sanitizePlus4(value);
    case "state_code": {
      if (typeof value !== "string") return null;
      const trimmed = value.trim().toUpperCase();
      if (!trimmed.length) {
        return null;
      }
      if (trimmed.startsWith("US-") && trimmed.length > 3) {
        return trimmed.slice(3);
      }
      return trimmed;
    }
    case "country_code":
    case "street_pre_directional_text":
    case "street_post_directional_text":
      return typeof value === "string" ? value.toUpperCase() : null;
    case "street_suffix_type": {
      if (typeof value !== "string") return null;
      const mapped = mapStreetSuffixType(value);
      if (mapped) return mapped;
      const trimmed = value.trim();
      return trimmed.length ? trimmed : null;
    }
    case "street_name":
      return typeof value === "string" ? value.toUpperCase() : null;
    case "unit_identifier":
    case "route_number":
      if (typeof value !== "string") return null;
      return value.trim().length ? value.trim() : null;
    case "county_name":
    case "municipality_name":
      return typeof value === "string" ? toTitleCase(value) : null;
    case "township":
      return padGridValue(value, 2);
    case "range":
      return padGridValue(value, 2);
    case "section":
      return padGridValue(value, 2);
    case "block":
      return padGridValue(value, 3);
    case "lot":
      return padGridValue(value, 4);
    default:
      if (typeof value === "number") {
        return Number.isFinite(value) ? value : null;
      }
      return value;
  }
}

function sanitizeAddressFieldValue(field, value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
    const numeric = parseCoordinate(value);
    return Number.isFinite(numeric) ? numeric : null;
  }

  const normalized = normalizeAddressFieldForSchema(field, value);
  if (normalized === undefined || normalized === null) {
    return null;
  }

  if (typeof normalized === "string") {
    const trimmed = normalized.trim();
    return trimmed.length ? trimmed : null;
  }

  if (typeof normalized === "number") {
    return Number.isFinite(normalized) ? normalized : null;
  }

  return normalized;
}

function pruneRawVariantToSchemaSurface(address) {
  if (!address || typeof address !== "object") return null;

  const trimmedRaw =
    typeof address.unnormalized_address === "string"
      ? address.unnormalized_address.trim()
      : "";
  if (!trimmedRaw.length) {
    return null;
  }

  const sanitized =
    ensureRawAddressSchemaDefaults({
      ...address,
      unnormalized_address: trimmedRaw,
    }) || null;

  if (!sanitized || typeof sanitized !== "object") {
    return null;
  }

  if (
    (sanitized.latitude == null && sanitized.longitude != null) ||
    (sanitized.latitude != null && sanitized.longitude == null)
  ) {
    sanitized.latitude = null;
    sanitized.longitude = null;
  }

  if (!hasMeaningfulAddressValue(sanitized.postal_code)) {
    sanitized.plus_four_postal_code = null;
  }

  return stripAddressRequestMetadata(sanitized);
}

function buildNormalizedAddressOutputForSchema(source) {
  if (!source || typeof source !== "object") {
    return null;
  }

  if (isDerivedAddressPayload(source)) {
    return null;
  }

  const normalized = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };

  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const hasField = Object.prototype.hasOwnProperty.call(source, field);
    const sanitized = hasField
      ? normalizeAddressFieldForSchema(field, source[field])
      : null;
    normalized[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  }

  for (const requiredField of NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS) {
    let value = normalized[requiredField];

    if (value === undefined || value === null) {
      return null;
    }

    if (typeof value === "number") {
      value = Number.isFinite(value) ? String(value) : null;
    }

    if (typeof value !== "string") {
      return null;
    }

    const trimmed = value.trim();
    if (!trimmed.length) {
      return null;
    }

    switch (requiredField) {
      case "street_number": {
        normalized[requiredField] = trimmed;
        break;
      }
      case "street_name": {
        const collapsed = trimmed.replace(/\s+/g, " ");
        if (STREET_NAME_FORBIDDEN_DIRECTIONS.test(collapsed.toUpperCase())) {
          return null;
        }
        normalized[requiredField] = collapsed.toUpperCase();
        break;
      }
      case "city_name": {
        const sanitizedCity = sanitizeCityName(trimmed);
        if (!sanitizedCity) {
          return null;
        }
        normalized[requiredField] = sanitizedCity;
        break;
      }
      case "state_code": {
        const upperState = trimmed.toUpperCase();
        if (!/^[A-Z]{2}$/.test(upperState)) {
          return null;
        }
        normalized[requiredField] = upperState;
        break;
      }
      case "postal_code": {
        const sanitizedPostal = sanitizePostalCode(trimmed);
        if (!sanitizedPostal) {
          return null;
        }
        normalized[requiredField] = sanitizedPostal;
        break;
      }
      case "country_code": {
        const upperCountry = trimmed.toUpperCase();
        if (!upperCountry.length) {
          return null;
        }
        normalized[requiredField] = upperCountry;
        break;
      }
      case "county_name": {
        const titledCounty = toTitleCase(trimmed);
        if (!titledCounty || !titledCounty.trim().length) {
          return null;
        }
        normalized[requiredField] = titledCounty;
        break;
      }
      default:
        normalized[requiredField] = trimmed;
    }
  }

  if (!normalized.postal_code) {
    normalized.plus_four_postal_code = null;
  }

  if (normalized.state_code && !normalized.country_code) {
    normalized.country_code = "US";
  }

  const hasStrictCountyCoverage = COUNTY_NORMALIZED_REQUIRED_FIELDS.every(
    (field) => hasMeaningfulAddressValue(normalized[field]),
  );
  if (!hasStrictCountyCoverage) {
    return null;
  }

  const hasExtendedCountyCoverage = COUNTY_NORMALIZED_REQUIRED_VALUE_FIELDS.every(
    (field) => hasMeaningfulAddressValue(normalized[field]),
  );
  if (!hasExtendedCountyCoverage) {
    return null;
  }

  for (const coordinateField of NORMALIZED_ADDRESS_COORDINATE_FIELDS) {
    const numeric = parseCoordinate(normalized[coordinateField]);
    if (!Number.isFinite(numeric)) {
      return null;
    }
    normalized[coordinateField] = numeric;
  }

  for (const supplementalField of COUNTY_SUPPLEMENTAL_NORMALIZED_FIELDS) {
    const value = normalized[supplementalField];
    if (!hasMeaningfulAddressValue(value)) {
      normalized[supplementalField] = null;
      continue;
    }
    if (typeof value === "string") {
      const trimmed = value.trim();
      normalized[supplementalField] = trimmed.length ? trimmed : null;
    }
  }

  return normalized;
}

function enforceAddressSchemaCompliance(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
  } = options || {};

  const currentPayload = readJSONIfExists(addressPath);
  if (!currentPayload || typeof currentPayload !== "object") {
    return;
  }

  if (addressHasStrictNormalizedCoverage(currentPayload)) {
    return;
  }

  const addressDir = path.dirname(addressPath);
  const structuredSnapshot =
    readJSONIfExists(path.join(addressDir, "address_structured_snapshot.json")) ||
    {};

  const unnormalizedSource = readJSONIfExists(unnormalizedPath) || {};
  const seedSource = readJSONIfExists(seedPath) || {};
  const fieldSources = [
    currentPayload,
    structuredSnapshot,
    unnormalizedSource,
    seedSource,
  ];

  const resolvedRequestIdentifier = safeNullIfEmpty(
    resolveRequestIdentifierCandidate(
      currentPayload.request_identifier,
      unnormalizedSource.request_identifier,
      seedSource.request_identifier,
      seedSource.parcel_id,
      seedSource.property_id,
      seedSource.prop_id,
    ),
  );

  const sourceHttpRequestCandidate = resolveSourceHttpRequestCandidate(
    currentPayload.source_http_request,
    unnormalizedSource.source_http_request,
    seedSource.source_http_request,
  );
  const preparedSourceHttpRequest = sourceHttpRequestCandidate
    ? prepareSourceHttpRequest(sourceHttpRequestCandidate)
    : null;
  if (!preparedSourceHttpRequest) {
    return;
  }

  const normalizedSource = { ...structuredSnapshot, ...currentPayload };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    if (hasMeaningfulAddressValue(normalizedSource[field])) {
      continue;
    }
    const resolved = resolveFirstMeaningfulAddressField(field, fieldSources);
    if (resolved !== undefined && resolved !== null) {
      normalizedSource[field] = resolved;
    }
  }

  const normalizedCandidate =
    buildNormalizedAddressOutputForSchema(normalizedSource) || null;

  if (normalizedCandidate) {
    normalizedCandidate.request_identifier =
      resolvedRequestIdentifier === undefined
        ? null
        : resolvedRequestIdentifier;
    normalizedCandidate.source_http_request = deepClone(
      preparedSourceHttpRequest,
    );
    delete normalizedCandidate.__preserve_request_metadata;
    persistSchemaAlignedAddress(addressPath, normalizedCandidate);
    return;
  }

  const rawString = resolveFirstNonEmptyString([
    currentPayload.unnormalized_address,
    unnormalizedSource.unnormalized_address,
    unnormalizedSource.full_address,
    unnormalizedSource.site_address,
    seedSource.unnormalized_address,
    seedSource.full_address,
  ]);
  if (!rawString || !rawString.trim().length) {
    return;
  }

  const latCandidate = parseCoordinate(currentPayload.latitude);
  const lonCandidate = parseCoordinate(currentPayload.longitude);

  const rawPayload = {
    unnormalized_address: rawString.trim(),
    latitude: Number.isFinite(latCandidate)
      ? latCandidate
      : resolveFirstCoordinate(
          fieldSources.map((source) => source && source.latitude),
        ),
    longitude: Number.isFinite(lonCandidate)
      ? lonCandidate
      : resolveFirstCoordinate(
          fieldSources.map((source) => source && source.longitude),
        ),
    request_identifier:
      resolvedRequestIdentifier === undefined
        ? null
        : resolvedRequestIdentifier,
    source_http_request: deepClone(preparedSourceHttpRequest),
    __force_raw_variant: true,
  };
  rawPayload.__preserve_request_metadata = true;

  const rawFieldSources = [
    currentPayload,
    structuredSnapshot,
    unnormalizedSource,
    seedSource,
  ];
  for (const field of RAW_ADDRESS_ALLOWED_FIELDS) {
    if (
      field === "latitude" ||
      field === "longitude" ||
      field === "unnormalized_address"
    ) {
      continue;
    }

    for (const source of rawFieldSources) {
      if (!source || !Object.prototype.hasOwnProperty.call(source, field)) {
        continue;
      }
      const value = sanitizeAddressFieldValue(field, source[field]);
      if (value !== undefined && value !== null) {
        rawPayload[field] = value;
        break;
      }
    }
  }

  const schemaAlignedRaw =
    ensureCountyRawRequiredFieldSurface({ ...rawPayload }) || {
      ...rawPayload,
    };
  stripRawVariantStructuredFields(schemaAlignedRaw);
  delete schemaAlignedRaw.__force_raw_variant;
  delete schemaAlignedRaw.__preserve_request_metadata;
  persistSchemaAlignedAddress(addressPath, schemaAlignedRaw);
}

function persistSchemaAlignedAddress(addressPath, payload) {
  if (
    !addressPath ||
    !payload ||
    typeof payload !== "object" ||
    Array.isArray(payload)
  ) {
    return;
  }

  try {
    ensureDir(path.dirname(addressPath));
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(payload, null, 2)}\n`,
    );
  } catch (error) {
    console.error(
      "Failed to persist schema-aligned address payload:",
      error,
    );
  }
}

function buildStrictRawAddressOutput(source, rawValue) {
  const trimmed =
    typeof rawValue === "string" ? rawValue.trim() : "";
  if (!trimmed.length) {
    return null;
  }

  const rawOutput = {
    ...RAW_ADDRESS_SCHEMA_TEMPLATE,
    unnormalized_address: trimmed,
  };

  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    const hasField = Object.prototype.hasOwnProperty.call(source, field);
    if (!hasField) continue;
    const candidate = sanitizeAddressFieldValue(field, source[field]);
    if (candidate === undefined) continue;
    rawOutput[field] = candidate;
  }

  if (
    (rawOutput.latitude == null) !== (rawOutput.longitude == null)
  ) {
    rawOutput.latitude = null;
    rawOutput.longitude = null;
  }

  if (!hasMeaningfulAddressValue(rawOutput.postal_code)) {
    rawOutput.plus_four_postal_code = null;
  }

  if (
    hasMeaningfulAddressValue(rawOutput.state_code) &&
    !hasMeaningfulAddressValue(rawOutput.country_code)
  ) {
    rawOutput.country_code = "US";
  }

  stripRawVariantStructuredFields(rawOutput);
  return rawOutput;
}

function buildRawAddressVariantForSchema(
  source,
  rawValue,
  preparedSourceHttpRequest = null,
  resolvedRequestIdentifier = undefined,
) {
  if (!source || typeof source !== "object") {
    return null;
  }

  const trimmed =
    typeof rawValue === "string" ? rawValue.trim() : "";
  if (!trimmed.length) {
    return null;
  }

  const rawOutput = {
    unnormalized_address: trimmed,
  };

  for (const field of RAW_SCHEMA_VARIANT_ALLOWED_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(source, field)) {
      continue;
    }
    const normalizedValue = normalizeAddressFieldForSchema(
      field,
      source[field],
    );
    if (normalizedValue === undefined || normalizedValue === null) {
      continue;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(normalizedValue);
      if (!Number.isFinite(numeric)) continue;
      rawOutput[field] = numeric;
      continue;
    }
    rawOutput[field] = normalizedValue;
  }

  if (!rawOutput.postal_code) {
    rawOutput.plus_four_postal_code = null;
  }

  if (rawOutput.state_code && !rawOutput.country_code) {
    rawOutput.country_code = "US";
  }

  const requestIdentifier =
    resolvedRequestIdentifier !== undefined
      ? resolvedRequestIdentifier
      : safeNullIfEmpty(source.request_identifier);
  if (requestIdentifier !== undefined) {
    rawOutput.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }

  const preparedSource =
    preparedSourceHttpRequest ||
    prepareSourceHttpRequest(source.source_http_request);
  if (preparedSource) {
    rawOutput.source_http_request = deepClone(preparedSource);
  }

  return rawOutput;
}

function enforceAddressBranchOutput(addressFilePath) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressFilePath);
    return;
  }

  const normalizedSnapshot = { ...payload };
  const normalizedReady = hasStrictNormalizedAddressCoverage(
    normalizedSnapshot,
  );

  if (normalizedReady) {
    const normalizedOutput =
      buildNormalizedAddressOutputForSchema(normalizedSnapshot) ||
      resolveNormalizedAddressVariantForOneOf(normalizedSnapshot);
    if (normalizedOutput && typeof normalizedOutput === "object") {
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "unnormalized_address",
        )
      ) {
        delete normalizedOutput.unnormalized_address;
      }
      const sanitized = stripAddressRequestMetadata(normalizedOutput);
      ensureDir(path.dirname(addressFilePath));
      fs.writeFileSync(
        addressFilePath,
        JSON.stringify(sanitized, null, 2),
      );
      return;
    }
  }

  const trimmedUnnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  const fallbackRaw =
    trimmedUnnormalized.length > 0
      ? trimmedUnnormalized
      : composeFallbackUnnormalizedAddressFromFields(payload);

  const rawOutput = buildStrictRawAddressOutput(payload, fallbackRaw);
  if (!rawOutput) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const sanitizedRaw = stripAddressRequestMetadata(rawOutput);
  ensureDir(path.dirname(addressFilePath));
  fs.writeFileSync(
    addressFilePath,
    JSON.stringify(sanitizedRaw, null, 2),
  );
}

function enforceFinalAddressSurface(addressFilePath) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const normalizedProbe =
    ensureAddressOutputFieldPresence({ ...payload }) || { ...payload };

  const trimmedUnnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  const normalizedSurface =
    ensureNormalizedAddressSchemaSurface(payload) || { ...payload };
  const normalizedCoverage =
    (typeof hasRobustNormalizedAddress === "function" &&
      hasRobustNormalizedAddress({ ...normalizedSurface })) ||
    hasNormalizedCountyCoverage(normalizedSurface);

  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const buildNormalizedOutput = () => {
    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      let value = sanitizeAddressFieldValue(field, normalizedSurface[field]);
      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const numeric = parseCoordinate(value);
        value = Number.isFinite(numeric) ? numeric : null;
      } else if (value === undefined || value === null) {
        value = null;
      } else if (typeof value === "string") {
        const trimmed = value.trim();
        value = trimmed.length ? trimmed : null;
      } else if (typeof value === "number") {
        value = Number.isFinite(value) ? value : null;
      }
      normalizedOutput[field] = value;
    }
    if (!normalizedOutput.postal_code) {
      normalizedOutput.plus_four_postal_code = null;
    }
    if (
      normalizedOutput.state_code &&
      !normalizedOutput.country_code
    ) {
      normalizedOutput.country_code = "US";
    }
    if (
      (normalizedOutput.latitude == null) !==
      (normalizedOutput.longitude == null)
    ) {
      normalizedOutput.latitude = null;
      normalizedOutput.longitude = null;
    }
    return normalizedOutput;
  };

  const buildRawOutput = () => {
    const composedRaw =
      trimmedUnnormalized ||
      composeFallbackUnnormalizedAddressFromFields(payload);
    if (!composedRaw) {
      return null;
    }
    const rawOutput = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
      let value = sanitizeAddressFieldValue(field, payload[field]);
      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const numeric = parseCoordinate(value);
        value = Number.isFinite(numeric) ? numeric : null;
      } else if (value === undefined || value === null) {
        value = null;
      } else if (typeof value === "string") {
        const trimmed = value.trim();
        value = trimmed.length ? trimmed : null;
      } else if (typeof value === "number") {
        value = Number.isFinite(value) ? value : null;
      }
      rawOutput[field] = value;
    }
    if (!rawOutput.postal_code) {
      rawOutput.plus_four_postal_code = null;
    }
    if (rawOutput.state_code && !rawOutput.country_code) {
      rawOutput.country_code = "US";
    }
    if (
      (rawOutput.latitude == null) !==
      (rawOutput.longitude == null)
    ) {
      rawOutput.latitude = null;
      rawOutput.longitude = null;
    }
    rawOutput.unnormalized_address = composedRaw;
    return rawOutput;
  };

  let outputPayload = normalizedCoverage
    ? buildNormalizedOutput()
    : buildRawOutput();

  if (!outputPayload) {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (normalizedCoverage) {
    if (
      Object.prototype.hasOwnProperty.call(
        outputPayload,
        "unnormalized_address",
      )
    ) {
      delete outputPayload.unnormalized_address;
    }
  } else if (
    typeof outputPayload.unnormalized_address === "string"
  ) {
    outputPayload.unnormalized_address =
      outputPayload.unnormalized_address.trim();
  }

  if (Object.prototype.hasOwnProperty.call(outputPayload, "source_http_request")) {
    delete outputPayload.source_http_request;
  }

  if (
    Object.prototype.hasOwnProperty.call(payload, "request_identifier")
  ) {
    outputPayload.request_identifier =
      requestIdentifier !== undefined && requestIdentifier !== null
        ? requestIdentifier
        : null;
  }

  fs.writeFileSync(
    addressFilePath,
    JSON.stringify(outputPayload, null, 2),
  );
}

function buildRawAddressOutputForSchema(unnormalizedAddress, source) {
  const trimmed =
    typeof unnormalizedAddress === "string"
      ? unnormalizedAddress.trim()
      : "";
  if (!trimmed.length) {
    return null;
  }

  const raw = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };

  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    const hasField =
      source && Object.prototype.hasOwnProperty.call(source, field);
    const sanitized = hasField
      ? normalizeAddressFieldForSchema(field, source[field])
      : null;
    raw[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  }

  if (!raw.postal_code) {
    raw.plus_four_postal_code = null;
  }

  if (raw.state_code && !raw.country_code) {
    raw.country_code = "US";
  }

  raw.unnormalized_address = trimmed;

  return raw;
}

const COUNTY_RAW_ADDRESS_FIELDS = [...RAW_ADDRESS_ALLOWED_FIELDS];

function buildCountyRawAddressPayload(base, unnormalizedValue) {
  const trimmed =
    typeof unnormalizedValue === "string"
      ? unnormalizedValue.trim()
      : "";
  if (!trimmed.length) {
    return null;
  }

  const payload = { unnormalized_address: trimmed };
  const ensureValue = (field, original) => {
    const sanitized = normalizeAddressFieldForSchema(field, original);
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(sanitized);
      return Number.isFinite(numeric) ? numeric : null;
    }
    if (sanitized === undefined || sanitized === null) {
      return null;
    }
    if (typeof sanitized === "string") {
      const collapsed = sanitized.trim();
      return collapsed.length ? collapsed : null;
    }
    if (typeof sanitized === "number") {
      return Number.isFinite(sanitized) ? sanitized : null;
    }
    return sanitized;
  };

  for (const field of COUNTY_RAW_ADDRESS_FIELDS) {
    const candidate =
      base && Object.prototype.hasOwnProperty.call(base, field)
        ? base[field]
        : null;
    payload[field] = ensureValue(field, candidate);
  }

  return payload;
}

function resolveRawAddressCandidateFromFiles(filePaths = []) {
  if (!Array.isArray(filePaths)) {
    return null;
  }
  const candidateFields = [
    "unnormalized_address",
    "full_address",
    "site_address",
    "address",
    "raw_address",
    "location_address",
    "mail_address",
  ];
  for (const filePath of filePaths) {
    if (!filePath) continue;
    const record = readJSONIfExists(filePath);
    if (!record || typeof record !== "object") continue;
    for (const field of candidateFields) {
      const candidate = safeNullIfEmpty(record[field]);
      if (candidate) {
        return candidate;
      }
    }
    if (Array.isArray(record.lines)) {
      const joined = record.lines
        .map((line) => (typeof line === "string" ? line.trim() : ""))
        .filter((line) => line && line.length)
        .join(", ");
      if (joined.length) {
        return joined;
      }
    }
  }
  return null;
}

function enforceAddressSchemaVariantOutput(addressFilePath, options = {}) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const surface =
    ensureAddressOutputFieldPresence({ ...payload }) || { ...payload };

  if (!hasMeaningfulAddressValue(surface.county_name) && options.defaultCountyName) {
    surface.county_name = options.defaultCountyName;
  }
  if (
    !hasMeaningfulAddressValue(surface.country_code) &&
    hasMeaningfulAddressValue(surface.state_code)
  ) {
    surface.country_code = options.defaultCountryCode || "US";
  }

  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const preparedSource = prepareSourceHttpRequest(payload.source_http_request);

  const writeFinalPayload = (output) => {
    if (!output || typeof output !== "object") {
      removeFileIfExists(addressFilePath);
      return;
    }
    const sanitized =
      stripAddressRequestMetadata(output) || output;
    try {
      writeJSON(addressFilePath, sanitized);
    } catch {
      removeFileIfExists(addressFilePath);
    }
  };

  const normalizedProbe =
    ensureAddressOutputFieldPresence({ ...surface }) || { ...surface };
  const normalizedCandidate =
    hasNormalizedCountyCoverage({ ...normalizedProbe })
      ? buildNormalizedAddressOutputForSchema(normalizedProbe)
      : null;

  if (normalizedCandidate) {
    if (requestIdentifier !== undefined) {
      normalizedCandidate.request_identifier =
        requestIdentifier === null ? null : requestIdentifier;
    }
    if (preparedSource) {
      normalizedCandidate.source_http_request = deepClone(preparedSource);
    }
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedCandidate,
        "unnormalized_address",
      )
    ) {
      delete normalizedCandidate.unnormalized_address;
    }
    writeFinalPayload(normalizedCandidate);
    return;
  }

  const explicitRaw =
    typeof surface.unnormalized_address === "string" &&
    surface.unnormalized_address.trim().length
      ? surface.unnormalized_address.trim()
      : null;
  const fallbackRaw =
    resolveRawAddressCandidateFromFiles(options.rawFallbackPaths || []) || null;
  const rawValue = explicitRaw || fallbackRaw;

  if (!rawValue) {
    removeFileIfExists(addressFilePath);
    return;
  }

  let rawOutput =
    buildRawAddressOutputForSchema(rawValue, surface) || null;

  if (!rawOutput) {
    rawOutput = {
      ...RAW_ADDRESS_SCHEMA_TEMPLATE,
      unnormalized_address: rawValue,
    };
  }

  rawOutput.__force_raw_variant = true;

  if (requestIdentifier !== undefined) {
    rawOutput.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  }
  if (preparedSource) {
    rawOutput.source_http_request = deepClone(preparedSource);
  }

  writeFinalPayload(rawOutput);
}

function pruneRawAddressPayloadForOutput(payload, options = {}) {
  if (!payload || typeof payload !== "object") return null;

  const unnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!unnormalized.length) {
    return null;
  }

  const { fillMissing = true } = options || {};
  const surface = fillMissing ? { ...RAW_ADDRESS_SCHEMA_TEMPLATE } : {};

  const result = {
    ...surface,
    unnormalized_address: unnormalized,
  };

  const assignIfMeaningful = (field, value) => {
    if (value === undefined || value === null) {
      return;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const coordinate = parseCoordinate(value);
      if (Number.isFinite(coordinate)) {
        result[field] = coordinate;
      }
      return;
    }

    if (typeof value === "string") {
      const trimmed = value.trim();
      if (trimmed.length) {
        result[field] = trimmed;
      }
      return;
    }

    if (typeof value === "number") {
      if (Number.isFinite(value)) {
        result[field] = value;
      }
      return;
    }

    if (typeof value === "boolean") {
      result[field] = value;
      return;
    }

    if (value && typeof value === "object") {
      result[field] = deepClone(value);
    }
  };

  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    if (field === "unnormalized_address") continue;
    const hasField = Object.prototype.hasOwnProperty.call(payload, field);
    const candidate = hasField ? payload[field] : null;
    const normalizedValue = normalizeAddressFieldForSchema(field, candidate);
    assignIfMeaningful(field, normalizedValue);
  }

  if (
    Object.prototype.hasOwnProperty.call(result, "state_code") &&
    result.state_code &&
    !Object.prototype.hasOwnProperty.call(result, "country_code")
  ) {
    result.country_code = "US";
  }

  const requestIdentifier =
    typeof payload.request_identifier === "string"
      ? payload.request_identifier.trim()
      : null;
  if (requestIdentifier) {
    result.request_identifier = requestIdentifier;
  }

  const preparedSource = prepareSourceHttpRequest(
    payload.source_http_request,
  );
  if (preparedSource) {
    result.source_http_request = preparedSource;
  }

  if (fillMissing) {
    for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
      if (!Object.prototype.hasOwnProperty.call(result, field)) {
        result[field] = null;
      }
    }
  }

  return result;
}

function materializeAddressForSchema(payload, variant, options = {}) {
  if (!payload || typeof payload !== "object") return null;

  const sourceHttpRequest =
    options && options.sourceHttpRequest
      ? deepClone(options.sourceHttpRequest)
      : null;

  if (variant === "normalized") {
    const normalizedOutput = {};
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      const candidate = Object.prototype.hasOwnProperty.call(payload, field)
        ? payload[field]
        : null;
      const normalizedValue = normalizeAddressFieldForSchema(field, candidate);
      normalizedOutput[field] =
        normalizedValue === undefined || normalizedValue === null
          ? null
          : normalizedValue;
    }

    if (!normalizedOutput.postal_code) {
      normalizedOutput.plus_four_postal_code = null;
    }
    if (normalizedOutput.state_code && !normalizedOutput.country_code) {
      normalizedOutput.country_code = "US";
    }

    for (const field of NORMALIZED_SCHEMA_REQUIRED_FIELDS) {
      const value = normalizedOutput[field];
      if (typeof value !== "string" || !value.trim().length) {
        return null;
      }
    }
    for (const field of NORMALIZED_ADDRESS_COORDINATE_FIELDS) {
      if (
        normalizedOutput[field] != null &&
        !Number.isFinite(normalizedOutput[field])
      ) {
        normalizedOutput[field] = null;
      }
    }

    const result = {
      ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE,
      ...normalizedOutput,
    };

    if (sourceHttpRequest) {
      result.source_http_request = sourceHttpRequest;
    }

    return result;
  }

  if (variant === "raw") {
    const unnormalized =
      typeof payload.unnormalized_address === "string"
        ? payload.unnormalized_address.trim()
        : "";
    if (!unnormalized.length) {
      return null;
    }

    const rawOutput = {};
    for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
      const candidate = Object.prototype.hasOwnProperty.call(payload, field)
        ? payload[field]
        : null;
      const normalizedValue = normalizeAddressFieldForSchema(field, candidate);
      rawOutput[field] =
        normalizedValue === undefined || normalizedValue === null
          ? null
          : normalizedValue;
    }

    if (!rawOutput.postal_code) {
      rawOutput.plus_four_postal_code = null;
    }
    if (rawOutput.state_code && !rawOutput.country_code) {
      rawOutput.country_code = "US";
    }

    const result = {
      ...RAW_ADDRESS_SCHEMA_TEMPLATE,
      ...rawOutput,
      unnormalized_address: unnormalized,
    };

    if (sourceHttpRequest) {
      result.source_http_request = sourceHttpRequest;
    }

    return result;
  }

  return null;
}

function prepareAddressOutputForSchema(candidate, options = {}) {
  if (!candidate || typeof candidate !== "object") return null;

  const {
    fallbackUnnormalized,
    preferRaw = false,
    preferredVariant = null,
  } = options || {};

  const fallbackValue =
    typeof fallbackUnnormalized === "string"
      ? fallbackUnnormalized.trim()
      : "";

  const normalizedSeed = { ...candidate };
  delete normalizedSeed.unnormalized_address;
  delete normalizedSeed.request_identifier;
  delete normalizedSeed.source_http_request;

  const shouldAttemptNormalized =
    !preferRaw && preferredVariant !== "raw";

  if (shouldAttemptNormalized) {
    const normalizedCandidate = materializeAddressForSchema(
      normalizedSeed,
      "normalized",
    );
    if (normalizedCandidate) {
      return normalizedCandidate;
    }
  }

  const enforceRaw = preferRaw || preferredVariant === "raw";

  const rawUnnormalized = resolveFirstNonEmptyString([
    typeof candidate.unnormalized_address === "string"
      ? candidate.unnormalized_address
      : null,
    fallbackValue,
  ]);

  if (!rawUnnormalized || !rawUnnormalized.trim().length) {
    return enforceRaw ? null : null;
  }

  const rawSeed = {
    ...candidate,
    unnormalized_address: rawUnnormalized.trim(),
  };
  delete rawSeed.request_identifier;
  delete rawSeed.source_http_request;

  return materializeAddressForSchema(rawSeed, "raw");
}

function ensureAddressSchemaSurfaceCoverage(address) {
  if (!address || typeof address !== "object") return null;

  const hasUnnormalized =
    typeof address.unnormalized_address === "string" &&
    address.unnormalized_address.trim().length > 0;

  const surfaceFields = hasUnnormalized
    ? RAW_ADDRESS_OUTPUT_FIELDS
    : NORMALIZED_ADDRESS_FIELDS;
  const template = hasUnnormalized
    ? RAW_ADDRESS_SCHEMA_TEMPLATE
    : NORMALIZED_ADDRESS_SCHEMA_TEMPLATE;

  const hydrated = { ...template };

  for (const field of surfaceFields) {
    if (Object.prototype.hasOwnProperty.call(address, field)) {
      const value = address[field];
      hydrated[field] = value === undefined ? null : value;
    }
  }

  for (const field of surfaceFields) {
    if (!Object.prototype.hasOwnProperty.call(hydrated, field)) {
      hydrated[field] = null;
    }
    if (
      ADDRESS_COORDINATE_FIELDS.includes(field) &&
      hydrated[field] != null &&
      !Number.isFinite(hydrated[field])
    ) {
      hydrated[field] = null;
    }
  }

  if (hasUnnormalized) {
    const trimmed = address.unnormalized_address.trim();
    if (!trimmed.length) {
      return null;
    }
    hydrated.unnormalized_address = trimmed;
  } else if (Object.prototype.hasOwnProperty.call(hydrated, "unnormalized_address")) {
    delete hydrated.unnormalized_address;
  }

  if (
    Object.prototype.hasOwnProperty.call(address, "request_identifier") &&
    address.request_identifier != null
  ) {
    hydrated.request_identifier = address.request_identifier;
  }

  if (Object.prototype.hasOwnProperty.call(address, "source_http_request")) {
    const prepared = prepareSourceHttpRequest(address.source_http_request);
    if (prepared) {
      hydrated.source_http_request = prepared;
    }
  }

  if (!hydrated.postal_code) {
    hydrated.plus_four_postal_code = null;
  }

  if (hydrated.state_code && !hydrated.country_code) {
    hydrated.country_code = "US";
  }

  return hydrated;
}

function normalizeCountyAddressForSchemaOutput(addressFilePath) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    return;
  }

  if (!payload || typeof payload !== "object") {
    return;
  }

  const trimmedUnnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    const hasField = Object.prototype.hasOwnProperty.call(payload, field);
    const rawValue = hasField ? payload[field] : null;
    const normalizedValue = normalizeAddressFieldForSchema(field, rawValue);

    if (normalizedValue === undefined || normalizedValue === null) {
      normalizedSurface[field] = null;
      continue;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(normalizedValue);
      normalizedSurface[field] = Number.isFinite(numeric) ? numeric : null;
      continue;
    }

    if (typeof normalizedValue === "string") {
      const trimmed = normalizedValue.trim();
      normalizedSurface[field] = trimmed.length ? trimmed : null;
      continue;
    }

    normalizedSurface[field] = normalizedValue;
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }

  if (normalizedSurface.state_code && !normalizedSurface.country_code) {
    normalizedSurface.country_code = "US";
  }

  const hasNormalizedCoverage =
    NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every(
      (field) =>
        typeof normalizedSurface[field] === "string" &&
        normalizedSurface[field].trim().length > 0,
    );

  if (hasNormalizedCoverage) {
    writeJSON(addressFilePath, normalizedSurface);
    return;
  }

  if (trimmedUnnormalized.length > 0) {
    const rawOutput = {
      ...normalizedSurface,
      unnormalized_address: trimmedUnnormalized,
    };

    if (!rawOutput.postal_code) {
      rawOutput.plus_four_postal_code = null;
    }
    if (rawOutput.state_code && !rawOutput.country_code) {
      rawOutput.country_code = "US";
    }

    writeJSON(addressFilePath, rawOutput);
    return;
  }

  fs.writeFileSync(
    addressFilePath,
    JSON.stringify(normalizedSurface, null, 2),
  );
}

