function enforceFinalAddressFromSourcePreferences(options = {}) {
  const {
    addressPath = path.join("data", "address.json"),
    propertyPath = path.join("data", "property.json"),
    relationshipsDir = path.join("relationships"),
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = titleCaseCounty("Palm Beach"),
    defaultStateCode = "FL",
    defaultCountryCode = "US",
  } = options || {};

  if (!addressPath) {
    return;
  }

  const dataDir = path.dirname(addressPath);
  const structuredSnapshotPath = path.join(
    dataDir,
    "address_structured_snapshot.json",
  );

  const addressPayload = readJSONIfExists(addressPath) || null;
  const unnormalizedSource =
    unnormalizedPath && readJSONIfExists(unnormalizedPath);
  const seedSource = seedPath && readJSONIfExists(seedPath);

  const sourceCandidates = [addressPayload, unnormalizedSource, seedSource].filter(
    (source) => source && typeof source === "object" && !Array.isArray(source),
  );

  const cleanupRelationships = () => {
    removeFileIfExists(structuredSnapshotPath);
    enforceNullPropertyAddressRelationships(propertyPath);
    overwriteAddressRelationshipFilesWithNull([dataDir, relationshipsDir]);
  };

  const hasNormalizedCoverage =
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    sourceCandidates.some((source) =>
      hasStrictCountyNormalizedSchemaCoverage({ ...source }),
    );

  if (hasNormalizedCoverage) {
    const normalizedSource =
      sourceCandidates.find((source) =>
        hasStrictCountyNormalizedSchemaCoverage({ ...source }),
      ) || null;
    let normalizedOutput =
      normalizedSource &&
      typeof buildNormalizedAddressOutputForSchema === "function"
        ? buildNormalizedAddressOutputForSchema({ ...normalizedSource })
        : normalizedSource
          ? deepClone(normalizedSource)
          : null;
    if (normalizedOutput && typeof normalizedOutput === "object") {
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "unnormalized_address",
        )
      ) {
        delete normalizedOutput.unnormalized_address;
      }
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          RAW_ADDRESS_DERIVED_FLAG,
        )
      ) {
        delete normalizedOutput[RAW_ADDRESS_DERIVED_FLAG];
      }
      writeAddressJSONBypass(addressPath, normalizedOutput);
      cleanupRelationships();
      return;
    }
  }

  const rawValue =
    resolveRawAddressStringFromSources(sourceCandidates) || null;
  if (!rawValue) {
    removeFileIfExists(addressPath);
    cleanupRelationships();
    return;
  }

  const basePayload =
    addressPayload && typeof addressPayload === "object"
      ? { ...addressPayload, unnormalized_address: rawValue }
      : { unnormalized_address: rawValue };

  const rawPayload =
    buildMinimalRawAddressForSchema(basePayload, sourceCandidates, {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) || null;
  if (!rawPayload) {
    removeFileIfExists(addressPath);
    cleanupRelationships();
    return;
  }

  const projectedRaw =
    collapseRawAddressToUnnormalizedOnly({ ...rawPayload }) || rawPayload;
  enforceRawVariantAllowedFields(projectedRaw);
  stripDerivedAddressFlag(projectedRaw);
  projectedRaw.__force_raw_variant = true;

  writeAddressJSONBypass(addressPath, projectedRaw);
  cleanupRelationships();
}

process.on("exit", () => {
  try {
    enforceFinalAddressFromSourcePreferences({
      addressPath: path.join("data", "address.json"),
      propertyPath: path.join("data", "property.json"),
      relationshipsDir: path.join("relationships"),
      unnormalizedPath: "unnormalized_address.json",
      seedPath: "property_seed.json",
      defaultCountyName: titleCaseCounty("Palm Beach"),
      defaultStateCode: "FL",
      defaultCountryCode: "US",
    });
  } catch (error) {
    console.error(
      "Failed to enforce final county address variant from sources:",
      error,
    );
    if (!process.exitCode) {
      process.exitCode = 1;
    }
  }
});

function persistRawOnlyAddressSnapshot(addressPath, context = {}) {
  if (!addressPath) {
    return false;
  }

  const {
    existingPayload = null,
    rawSource = null,
    seedSource = null,
    requestIdentifier = undefined,
    sourceHttpRequest = null,
  } = context || {};

  const joinedLines =
    rawSource &&
    Array.isArray(rawSource.lines) &&
    rawSource.lines
      .map((line) => (typeof line === "string" ? line.trim() : ""))
      .filter((line) => line.length)
      .join(", ");

  const rawCandidates = flattenCandidateValues(
    existingPayload && existingPayload.unnormalized_address,
    existingPayload && existingPayload.full_address,
    existingPayload && existingPayload.address,
    rawSource && rawSource.unnormalized_address,
    rawSource && rawSource.full_address,
    rawSource && rawSource.site_address,
    joinedLines,
    seedSource && seedSource.unnormalized_address,
    seedSource && seedSource.full_address,
    seedSource && seedSource.situs_address,
  );

  const resolvedRaw = safeNullIfEmpty(resolveFirstNonEmptyString(rawCandidates));
  if (!resolvedRaw) {
    removeFileIfExists(addressPath);
    return false;
  }

  ensureDir(path.dirname(addressPath));
  const payloadSeed = {
    unnormalized_address: resolvedRaw,
  };

  if (requestIdentifier !== undefined) {
    payloadSeed.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  } else {
    payloadSeed.request_identifier = null;
  }

  const preparedSource = sourceHttpRequest
    ? prepareSourceHttpRequest(sourceHttpRequest)
    : null;
  if (preparedSource) {
    payloadSeed.source_http_request = preparedSource;
  }

  const submissionPayload =
    buildSchemaCompliantRawAddress(payloadSeed) || payloadSeed;

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(submissionPayload, null, 2)}\n`,
    );
  } catch {
    writeJSON(addressPath, submissionPayload);
  }

  return true;
}

function enforceFinalAddressSnapshot(addressPath, options = {}) {
  if (!addressPath) {
    return null;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    normalizedOptions = {},
  } = options || {};

  const existingPayload = readJSONIfExists(addressPath) || null;
  const rawSource = readJSONIfExists(unnormalizedPath) || null;
  const seedSource = readJSONIfExists(seedPath) || null;

  const requestIdentifier = resolveRequestIdentifierCandidate(
    existingPayload && existingPayload.request_identifier,
    rawSource && rawSource.request_identifier,
    seedSource && seedSource.request_identifier,
    seedSource && seedSource.parcel_id,
  );

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    existingPayload && existingPayload.source_http_request,
    rawSource && rawSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );
  const structuredSnapshotPath = path.join(
    path.dirname(addressPath) || ".",
    "address_structured_snapshot.json",
  );
  const structuredSnapshot = readJSONIfExists(structuredSnapshotPath) || null;

  if (structuredSnapshot) {
    const structuredRawCandidate = buildStructuredRawAddressCandidate({
      structuredSnapshot,
      currentPayload: existingPayload,
      defaultCountyName:
        normalizedOptions && normalizedOptions.defaultCountyName
          ? normalizedOptions.defaultCountyName
          : null,
      defaultStateCode:
        normalizedOptions && normalizedOptions.defaultStateCode
          ? normalizedOptions.defaultStateCode
          : null,
      defaultCountryCode:
        normalizedOptions && normalizedOptions.defaultCountryCode
          ? normalizedOptions.defaultCountryCode
          : "US",
      unnormalizedCandidates: [
        existingPayload && existingPayload.unnormalized_address,
        rawSource && rawSource.unnormalized_address,
        rawSource && rawSource.full_address,
      ],
      requestIdentifierCandidates: [
        requestIdentifier,
        rawSource && rawSource.request_identifier,
        seedSource && seedSource.request_identifier,
      ],
      sourceHttpRequestCandidates: [
        sourceHttpRequest,
        rawSource && rawSource.source_http_request,
        seedSource && seedSource.source_http_request,
      ],
    });

    if (structuredRawCandidate) {
      if (process.env.DEBUG_ADDRESS_FIELDS === "1") {
        console.error(
          "[exit structured raw]",
          JSON.stringify(structuredRawCandidate, null, 2),
        );
      }
      if (
        typeof hasNormalizedCountyCoverage === "function" &&
        hasNormalizedCountyCoverage({ ...structuredRawCandidate }) &&
        Object.prototype.hasOwnProperty.call(
          structuredRawCandidate,
          "unnormalized_address",
        )
      ) {
        delete structuredRawCandidate.unnormalized_address;
      }
      if (
        Object.prototype.hasOwnProperty.call(
          structuredRawCandidate,
          "__preserve_structured_fields",
        )
      ) {
        delete structuredRawCandidate.__preserve_structured_fields;
      }
      try {
        originalWriteFileSync.call(
          fs,
          addressPath,
          `${JSON.stringify(structuredRawCandidate, null, 2)}\n`,
        );
      } catch {
        writeJSON(addressPath, structuredRawCandidate);
      }
      return "raw";
    }
  }

  if (
    existingPayload &&
    typeof hasNormalizedCountyCoverage === "function" &&
    hasNormalizedCountyCoverage({ ...existingPayload })
  ) {
    const normalizedCandidate =
      typeof buildCountyNormalizedOneOfPayload === "function"
        ? buildCountyNormalizedOneOfPayload(
            { ...existingPayload },
            normalizedOptions || {},
          )
        : null;

    if (normalizedCandidate) {
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedCandidate,
          "unnormalized_address",
        )
      ) {
        delete normalizedCandidate.unnormalized_address;
      }

      if (requestIdentifier !== undefined) {
        normalizedCandidate.request_identifier =
          requestIdentifier === null ? null : requestIdentifier;
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedCandidate,
          "request_identifier",
        )
      ) {
        delete normalizedCandidate.request_identifier;
      }

      const preparedSource = sourceHttpRequest
        ? prepareSourceHttpRequest(sourceHttpRequest)
        : null;
      if (preparedSource) {
        normalizedCandidate.source_http_request = deepClone(preparedSource);
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedCandidate,
          "source_http_request",
        )
      ) {
        delete normalizedCandidate.source_http_request;
      }

      ensureDir(path.dirname(addressPath));
      try {
        originalWriteFileSync.call(
          fs,
          addressPath,
          `${JSON.stringify(normalizedCandidate, null, 2)}\n`,
        );
      } catch {
        writeJSON(addressPath, normalizedCandidate);
      }

      return "normalized";
    }
  }

  if (
    existingPayload &&
    typeof hasStructuredRawAddressCoverage === "function" &&
    hasStructuredRawAddressCoverage({ ...existingPayload })
  ) {
    return "raw";
  }

  return persistRawOnlyAddressSnapshot(addressPath, {
    existingPayload,
    rawSource,
    seedSource,
    requestIdentifier,
    sourceHttpRequest,
  })
    ? "raw"
    : null;
}


