process.on("exit", () => {
  try {
    const dataDir = path.join("data");
    const addressPath = path.join(dataDir, "address.json");
    if (!fs.existsSync(addressPath)) {
      return;
    }

    const payload = readJSONIfExists(addressPath);
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
      removeFileIfExists(addressPath);
      return;
    }

    const unnormalizedSource =
      readJSONIfExists("unnormalized_address.json") || null;
    const seedSource = readJSONIfExists("property_seed.json") || null;
    const normalizationOptions = {
      defaultCountyName: titleCaseCounty("Palm Beach"),
      defaultStateCode: "FL",
      defaultCountryCode: "US",
    };

    const normalizedCandidate =
      buildCountyNormalizedOneOfPayload(payload, normalizationOptions) ||
      buildCountyNormalizedOneOfPayload(unnormalizedSource, normalizationOptions) ||
      buildCountyNormalizedOneOfPayload(seedSource, normalizationOptions) ||
      null;

    const requestIdentifier = resolveRequestIdentifierCandidate(
      payload.request_identifier,
      normalizedCandidate && normalizedCandidate.request_identifier,
      unnormalizedSource && unnormalizedSource.request_identifier,
      seedSource && seedSource.request_identifier,
      seedSource && seedSource.parcel_id,
    );
    const sourceHttpRequest = resolveSourceHttpRequestCandidate(
      payload.source_http_request,
      normalizedCandidate && normalizedCandidate.source_http_request,
      unnormalizedSource && unnormalizedSource.source_http_request,
      seedSource && seedSource.source_http_request,
    );

    const persistAddressPayload = (value) => {
      if (!value) {
        removeFileIfExists(addressPath);
        return;
      }
      originalWriteFileSync.call(
        fs,
        addressPath,
        `${JSON.stringify(value, null, 2)}\n`,
      );
    };

    if (normalizedCandidate) {
      const normalizedOutput = { ...normalizedCandidate };
      if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "unnormalized_address",
        )
      ) {
        delete normalizedOutput.unnormalized_address;
      }
      if (requestIdentifier !== undefined) {
        normalizedOutput.request_identifier =
          requestIdentifier === null ? null : requestIdentifier;
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "request_identifier",
        )
      ) {
        normalizedOutput.request_identifier = safeNullIfEmpty(
          normalizedOutput.request_identifier,
        );
      }
      if (sourceHttpRequest) {
        const prepared = prepareSourceHttpRequest(sourceHttpRequest);
        if (prepared) {
          normalizedOutput.source_http_request = deepClone(prepared);
        }
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedOutput,
          "source_http_request",
        )
      ) {
        delete normalizedOutput.source_http_request;
      }
      persistAddressPayload(normalizedOutput);
      return;
    }

    const rawCandidates = [
      payload.unnormalized_address,
      payload.full_address,
      payload.site_address,
      payload.address,
      unnormalizedSource && unnormalizedSource.unnormalized_address,
      unnormalizedSource && unnormalizedSource.full_address,
      seedSource && seedSource.unnormalized_address,
      seedSource && seedSource.full_address,
    ];

    const rawString = safeNullIfEmpty(resolveFirstNonEmptyString(rawCandidates));
    if (!rawString) {
      removeFileIfExists(addressPath);
      return;
    }

    const rawOutput = {
      unnormalized_address: rawString,
    };

    if (requestIdentifier !== undefined) {
      rawOutput.request_identifier =
        requestIdentifier === null ? null : requestIdentifier;
    }

    if (sourceHttpRequest) {
      const prepared = prepareSourceHttpRequest(sourceHttpRequest);
      if (prepared) {
        rawOutput.source_http_request = deepClone(prepared);
      }
    }

    persistAddressPayload(rawOutput);
  } catch (error) {
    console.error("Failed to enforce terminal address variant:", error);
  }
});

process.on("exit", () => {
  try {
    const dataDir = path.join("data");
    const addressPath = path.join(dataDir, "address.json");
    enforceRawAddressNormalizedFieldPresence(addressPath);
  } catch (error) {
    console.error("Failed to enforce final raw address schema surface:", error);
  }
});

function collapseAddressPayloadToCountyOneOf(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressPath);
    return;
  }

  const {
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    extraRawCandidates = [],
    rawFallbackPaths = [],
  } = options || {};

  const unnormalizedSource = readJSONIfExists("unnormalized_address.json") || null;
  const seedSource = readJSONIfExists("property_seed.json") || null;

  let normalizedCandidate = null;
  if (typeof buildCountyNormalizedOneOfPayload === "function") {
    const normalizationContext = {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    };
    normalizedCandidate =
      buildCountyNormalizedOneOfPayload(payload, normalizationContext) ||
      buildCountyNormalizedOneOfPayload(unnormalizedSource, normalizationContext) ||
      buildCountyNormalizedOneOfPayload(seedSource, normalizationContext) ||
      null;
  }

  const requestIdentifier = resolveRequestIdentifierCandidate(
    payload.request_identifier,
    normalizedCandidate && normalizedCandidate.request_identifier,
    unnormalizedSource && unnormalizedSource.request_identifier,
    seedSource && seedSource.request_identifier,
    seedSource && seedSource.parcel_id,
  );

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    payload.source_http_request,
    normalizedCandidate && normalizedCandidate.source_http_request,
    unnormalizedSource && unnormalizedSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );

  const normalizedReady =
    normalizedCandidate &&
    typeof hasNormalizedCountyCoverage === "function" &&
    hasNormalizedCountyCoverage({ ...normalizedCandidate })
      ? ensureAddressOutputFieldPresence({ ...normalizedCandidate }) ||
        { ...normalizedCandidate }
      : null;

  if (normalizedReady) {
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedReady,
        "unnormalized_address",
      )
    ) {
      delete normalizedReady.unnormalized_address;
    }

    if (requestIdentifier !== undefined) {
      const normalizedIdentifier = safeNullIfEmpty(requestIdentifier);
      normalizedReady.request_identifier =
        normalizedIdentifier === null ? null : normalizedIdentifier;
    } else if (
      Object.prototype.hasOwnProperty.call(
        normalizedReady,
        "request_identifier",
      )
    ) {
      const normalizedIdentifier = safeNullIfEmpty(
        normalizedReady.request_identifier,
      );
      normalizedReady.request_identifier =
        normalizedIdentifier === undefined ? null : normalizedIdentifier;
    }

    if (sourceHttpRequest) {
      const prepared = prepareSourceHttpRequest(sourceHttpRequest);
      if (prepared) {
        normalizedReady.source_http_request = deepClone(prepared);
      } else if (
        Object.prototype.hasOwnProperty.call(
          normalizedReady,
          "source_http_request",
        )
      ) {
        delete normalizedReady.source_http_request;
      }
    } else if (
      Object.prototype.hasOwnProperty.call(
        normalizedReady,
        "source_http_request",
      )
    ) {
      delete normalizedReady.source_http_request;
    }

    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(normalizedReady, null, 2)}\n`,
    );
    return;
  }

  const rawCandidateStrings = [];
  const enqueueRawValue = (value) => {
    if (typeof value !== "string") return;
    const trimmed = value.trim();
    if (trimmed.length) {
      rawCandidateStrings.push(trimmed);
    }
  };

  const enqueueSourceCandidates = (source) => {
    if (!source || typeof source !== "object") return;
    enqueueRawValue(source.unnormalized_address);
    enqueueRawValue(source.full_address);
    enqueueRawValue(source.site_address);
    enqueueRawValue(source.address);
    enqueueRawValue(source.raw_address);
    enqueueRawValue(source.location_address);
    enqueueRawValue(source.mail_address);
  };

  enqueueSourceCandidates(payload);
  enqueueSourceCandidates(unnormalizedSource);
  enqueueSourceCandidates(seedSource);

  if (Array.isArray(rawFallbackPaths)) {
    for (const candidatePath of rawFallbackPaths) {
      if (typeof candidatePath !== "string" || !candidatePath.trim().length) {
        continue;
      }
      const fallbackSource = readJSONIfExists(candidatePath);
      enqueueSourceCandidates(fallbackSource);
    }
  }

  if (Array.isArray(extraRawCandidates)) {
    for (const candidate of extraRawCandidates) {
      enqueueRawValue(candidate);
    }
  }

  const rawString = resolveFirstNonEmptyString(rawCandidateStrings);
  if (!rawString) {
    removeFileIfExists(addressPath);
    return;
  }

  const rawOutput = {
    unnormalized_address: rawString,
  };

  if (requestIdentifier !== undefined) {
    const normalizedIdentifier = safeNullIfEmpty(requestIdentifier);
    rawOutput.request_identifier =
      normalizedIdentifier === null ? null : normalizedIdentifier;
  }

  if (sourceHttpRequest) {
    const prepared = prepareSourceHttpRequest(sourceHttpRequest);
    if (prepared) {
      rawOutput.source_http_request = deepClone(prepared);
    }
  }

  originalWriteFileSync.call(
    fs,
    addressPath,
    `${JSON.stringify(rawOutput, null, 2)}\n`,
  );
}

process.on("exit", () => {
  try {
    const dataDir = path.join("data");
    const addressPath = path.join(dataDir, "address.json");
    const extraCandidates =
      ADDRESS_FALLBACK_CONTEXT &&
      Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
        ? ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates
        : [];
    collapseAddressPayloadToCountyOneOf(addressPath, {
      defaultCountyName: titleCaseCounty("Palm Beach"),
      defaultStateCode: "FL",
      defaultCountryCode: "US",
      extraRawCandidates: extraCandidates,
    });
  } catch (error) {
    console.error(
      "Failed to collapse address payload to a single schema branch:",
      error,
    );
  }
});

function enforceTerminalRawCountyAddressPayload() {
  const dataDir = path.join("data");
  ensureDir(dataDir);
  const relationshipsDir = path.join("relationships");
  ensureDir(relationshipsDir);
  const addressPath = path.join(dataDir, "address.json");
  const existingPayload = readJSONIfExists(addressPath) || {};
  const unnormalizedSource =
    readJSONIfExists("unnormalized_address.json") || {};
  const seedSource = readJSONIfExists("property_seed.json") || {};

  const simplifiedPayload =
    buildSimplifiedRawCountyAddressPayload({
      existingPayload,
      unnormalizedSource,
      seedSource,
    }) || null;

  if (!simplifiedPayload) {
    removeFileIfExists(addressPath);
    overwriteAddressRelationshipFilesWithNull([dataDir, relationshipsDir]);
    return;
  }

  const trimmedRaw =
    typeof simplifiedPayload.unnormalized_address === "string"
      ? simplifiedPayload.unnormalized_address.trim()
      : "";
  if (!trimmedRaw.length) {
    removeFileIfExists(addressPath);
    overwriteAddressRelationshipFilesWithNull([dataDir, relationshipsDir]);
    return;
  }
  simplifiedPayload.unnormalized_address = trimmedRaw;

  for (const field of RAW_ADDRESS_ALLOWED_FIELDS) {
    if (!Object.prototype.hasOwnProperty.call(simplifiedPayload, field)) {
      simplifiedPayload[field] = null;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(simplifiedPayload[field]);
      simplifiedPayload[field] = Number.isFinite(numeric) ? numeric : null;
      continue;
    }
    if (
      typeof simplifiedPayload[field] === "string" &&
      simplifiedPayload[field].trim() === ""
    ) {
      simplifiedPayload[field] = null;
    }
  }

  if (
    simplifiedPayload.state_code &&
    !hasMeaningfulAddressValue(simplifiedPayload.country_code)
  ) {
    simplifiedPayload.country_code = "US";
  }

  const requestIdentifier = safeNullIfEmpty(
    simplifiedPayload.request_identifier,
  );
  simplifiedPayload.request_identifier =
    requestIdentifier === undefined ? null : requestIdentifier;

  originalWriteFileSync.call(
    fs,
    addressPath,
    `${JSON.stringify(simplifiedPayload, null, 2)}\n`,
  );
  overwriteAddressRelationshipFilesWithNull([dataDir, relationshipsDir]);
}

function buildStrictRawAddressPayload(payload, options = {}) {
  if (!payload || typeof payload !== "object") {
    return null;
  }

  const {
    unnormalizedSource = null,
    seedSource = null,
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    extraRawCandidates = [],
    coordinateCandidates = [],
  } = options || {};

  const rawCandidates = collectNonEmptyStrings(
    payload.unnormalized_address,
    payload.full_address,
    unnormalizedSource && [
      unnormalizedSource.unnormalized_address,
      unnormalizedSource.full_address,
    ],
    seedSource && [
      seedSource.unnormalized_address,
      seedSource.full_address,
    ],
    extraRawCandidates,
  );
  const resolvedRaw = rawCandidates.length ? rawCandidates[0] : null;
  if (!resolvedRaw) {
    return null;
  }

  const resolveCandidate = (...candidates) => {
    const values = collectNonEmptyStrings(...candidates);
    return values.length ? values[0] : null;
  };

  const cleaned = { unnormalized_address: resolvedRaw };

  const cityCandidate = resolveCandidate(
    payload.city_name,
    payload.municipality_name,
    unnormalizedSource && unnormalizedSource.city_name,
    seedSource && seedSource.city_name,
  );
  if (cityCandidate) {
    cleaned.city_name = cityCandidate.trim().toUpperCase();
  }

  const municipalityCandidate =
    resolveCandidate(
      payload.municipality_name,
      unnormalizedSource && unnormalizedSource.municipality_name,
      seedSource && seedSource.municipality_name,
    ) ||
    (cleaned.city_name
      ? toTitleCase(cleaned.city_name.toLowerCase())
      : null);
  if (municipalityCandidate) {
    cleaned.municipality_name = municipalityCandidate;
  }

  const countyCandidate = resolveCandidate(
    payload.county_name,
    unnormalizedSource &&
      (unnormalizedSource.county_name || unnormalizedSource.county_jurisdiction),
    seedSource && seedSource.county_name,
    defaultCountyName,
  );
  if (countyCandidate) {
    cleaned.county_name =
      typeof titleCaseCounty === "function"
        ? titleCaseCounty(countyCandidate)
        : countyCandidate;
  }

  const stateCandidate = resolveCandidate(
    payload.state_code,
    unnormalizedSource && unnormalizedSource.state_code,
    seedSource && seedSource.state_code,
    defaultStateCode,
  );
  if (stateCandidate) {
    cleaned.state_code = stateCandidate.trim().slice(0, 2).toUpperCase();
  }

  const countryCandidate = resolveCandidate(
    payload.country_code,
    unnormalizedSource && unnormalizedSource.country_code,
    seedSource && seedSource.country_code,
    defaultCountryCode,
  );
  cleaned.country_code = (countryCandidate || "US").trim().toUpperCase();

  const postalCandidate = resolveCandidate(
    payload.postal_code,
    unnormalizedSource && unnormalizedSource.postal_code,
    seedSource && seedSource.postal_code,
  );
  const sanitizedPostal = sanitizePostalCode(postalCandidate);
  if (sanitizedPostal) {
    cleaned.postal_code = sanitizedPostal;
  }

  const plus4Candidate = resolveCandidate(
    payload.plus_four_postal_code,
    unnormalizedSource &&
      (unnormalizedSource.plus_four_postal_code || unnormalizedSource.plus4),
    seedSource && seedSource.plus_four_postal_code,
  );
  const sanitizedPlus4 = sanitizePlus4(plus4Candidate);
  if (sanitizedPlus4 && sanitizedPostal) {
    cleaned.plus_four_postal_code = sanitizedPlus4;
  }

  const coordinateSources = [
    payload,
    unnormalizedSource,
    seedSource,
    ...(Array.isArray(coordinateCandidates) ? coordinateCandidates : []),
  ];
  for (const source of coordinateSources) {
    if (!source || typeof source !== "object") continue;
    const latitude = parseCoordinate(
      Object.prototype.hasOwnProperty.call(source, "latitude")
        ? source.latitude
        : null,
    );
    const longitude = parseCoordinate(
      Object.prototype.hasOwnProperty.call(source, "longitude")
        ? source.longitude
        : null,
    );
    if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
      cleaned.latitude = latitude;
      cleaned.longitude = longitude;
      break;
    }
  }

  const requestIdentifier = resolveRequestIdentifierCandidate(
    payload.request_identifier,
    unnormalizedSource && unnormalizedSource.request_identifier,
    seedSource && seedSource.request_identifier,
    seedSource && seedSource.parcel_id,
  );
  if (requestIdentifier !== undefined) {
    const normalizedIdentifier = safeNullIfEmpty(requestIdentifier);
    cleaned.request_identifier =
      normalizedIdentifier === undefined ? null : normalizedIdentifier;
  }

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    payload.source_http_request,
    unnormalizedSource && unnormalizedSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );
  if (sourceHttpRequest) {
    const prepared = prepareSourceHttpRequest(sourceHttpRequest);
    if (prepared) {
      cleaned.source_http_request = deepClone(prepared);
    }
  }

  if (!cleaned.postal_code) {
    delete cleaned.plus_four_postal_code;
  }

  return cleaned;
}

function enforceRawVariantFieldWhitelist(addressPath) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    removeFileIfExists(addressPath);
    return;
  }

  const hasStrictNormalized =
    typeof hasNormalizedCountyCoverage === 'function' &&
    hasNormalizedCountyCoverage({ ...payload });
  if (hasStrictNormalized) {
    return;
  }

  const unnormalizedSource =
    readJSONIfExists('unnormalized_address.json') || null;
  const seedSource = readJSONIfExists('property_seed.json') || null;
  const extraRawCandidates =
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
      ? ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates
      : [];
  const coordinateFallbacks =
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.coordinateCandidates)
      ? ADDRESS_FALLBACK_CONTEXT.coordinateCandidates
      : [];

  const cleaned = buildStrictRawAddressPayload(payload, {
    unnormalizedSource,
    seedSource,
    defaultCountyName: titleCaseCounty('Palm Beach'),
    defaultStateCode: 'FL',
    defaultCountryCode: 'US',
    extraRawCandidates,
    coordinateCandidates: coordinateFallbacks,
  });

  if (!cleaned) {
    removeFileIfExists(addressPath);
    return;
  }

  addressWriteLocked = true;
  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(cleaned, null, 2)}\n`,
    );
  } finally {
    addressWriteLocked = false;
  }
}

function finalizeNormalizedOrMinimalRawAddress(addressPath, options = {}) {
  if (!addressPath) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressPath);
    return;
  }

  const {
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  const normalizedCandidate = buildCountyNormalizedOneOfPayload(payload, {
    defaultCountyName,
    defaultStateCode,
    defaultCountryCode,
  });

  if (normalizedCandidate) {
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedCandidate,
        "unnormalized_address",
      )
    ) {
      delete normalizedCandidate.unnormalized_address;
    }
    if (
      Object.prototype.hasOwnProperty.call(payload, "request_identifier")
    ) {
      normalizedCandidate.request_identifier =
        safeNullIfEmpty(payload.request_identifier) ?? null;
    }
    if (payload.source_http_request) {
      const preparedSource = prepareSourceHttpRequest(
        payload.source_http_request,
      );
      if (preparedSource) {
        normalizedCandidate.source_http_request = deepClone(preparedSource);
      }
    }
    writeJSON(addressPath, normalizedCandidate);
    return;
  }

  const unnormalizedSource =
    readJSONIfExists('unnormalized_address.json') || null;
  const seedSource = readJSONIfExists('property_seed.json') || null;
  const strictRaw = buildStrictRawAddressPayload(payload, {
    unnormalizedSource,
    seedSource,
    defaultCountyName,
    defaultStateCode,
    defaultCountryCode,
  });

  if (!strictRaw) {
    removeFileIfExists(addressPath);
    return;
  }

  writeJSON(addressPath, strictRaw);
}

