function buildLeanRawOneOfPayload(
  rawValue,
  fieldSources = [],
  options = {},
) {
  const trimmedRaw = typeof rawValue === "string" ? rawValue.trim() : "";
  if (!trimmedRaw.length) {
    return null;
  }

  const candidateSources = Array.isArray(fieldSources)
    ? fieldSources.filter((source) => source && typeof source === "object")
    : [];

  const payload = {
    unnormalized_address: trimmedRaw,
  };

  const requestIdentifier = resolveRequestIdentifierCandidate(
    ...(Array.isArray(options.requestIdentifierCandidates)
      ? options.requestIdentifierCandidates
      : []),
  );
  payload.request_identifier =
    requestIdentifier === undefined
      ? null
      : safeNullIfEmpty(requestIdentifier) ?? null;

  const resolvedSource = resolveSourceHttpRequestCandidate(
    ...(Array.isArray(options.sourceHttpRequestCandidates)
      ? options.sourceHttpRequestCandidates
      : []),
  );
  payload.source_http_request = resolvedSource
    ? deepClone(prepareSourceHttpRequest(resolvedSource) || resolvedSource)
    : null;

  const schemaFields = RAW_ADDRESS_ALLOWED_FIELDS;

  schemaFields.forEach((field) => {
    const resolved = resolveFirstMeaningfulAddressField(field, candidateSources);
    if (resolved === undefined || resolved === null) {
      payload[field] = null;
      return;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(resolved);
      payload[field] = Number.isFinite(numeric) ? numeric : null;
      return;
    }
    if (typeof resolved === "string") {
      const value = resolved.trim();
      payload[field] = value.length ? value : null;
      return;
    }
    payload[field] = resolved;
  });

  const {
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
  } = options || {};

  if (!hasMeaningfulAddressValue(payload.county_name) && defaultCountyName) {
    payload.county_name = titleCaseCounty(defaultCountyName);
  }
  if (!hasMeaningfulAddressValue(payload.state_code) && defaultStateCode) {
    payload.state_code = defaultStateCode;
  }
  if (!hasMeaningfulAddressValue(payload.country_code) && defaultCountryCode) {
    payload.country_code = defaultCountryCode;
  }
  if (!hasMeaningfulAddressValue(payload.postal_code)) {
    payload.plus_four_postal_code = null;
  }

  return payload;
}

function emitStrictAddressSubmissionPayload(addressPath, options = {}) {
  if (!addressPath || typeof addressPath !== "string") {
    return null;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    extraRawCandidates = [],
    defaultCountyName = titleCaseCounty("Palm Beach"),
    defaultStateCode = "FL",
    defaultCountryCode = "US",
  } = options || {};

  const existingPayload = readJSONIfExists(addressPath) || null;
  const unnormalizedSource = readJSONIfExists(unnormalizedPath) || null;
  const seedSource = readJSONIfExists(seedPath) || null;

  const fieldSources = [existingPayload, unnormalizedSource, seedSource].filter(
    (source) => source && typeof source === "object",
  );

  const normalizedCandidate = (() => {
    for (const source of fieldSources) {
      if (
        source &&
        typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
        hasStrictCountyNormalizedSchemaCoverage({ ...source })
      ) {
        const normalized = buildNormalizedAddressOutputForSchema({
          ...source,
        });
        if (!normalized) {
          continue;
        }
        if (
          Object.prototype.hasOwnProperty.call(
            normalized,
            "unnormalized_address",
          )
        ) {
          delete normalized.unnormalized_address;
        }
        if (
          Object.prototype.hasOwnProperty.call(
            normalized,
            "request_identifier",
          )
        ) {
          delete normalized.request_identifier;
        }
        if (
          Object.prototype.hasOwnProperty.call(
            normalized,
            "source_http_request",
          )
        ) {
          delete normalized.source_http_request;
        }
        return normalized;
      }
    }
    return null;
  })();

  if (normalizedCandidate) {
    writeAddressJSONBypass(addressPath, normalizedCandidate);
    stripAddressRequestMetadataOnDisk(addressPath);
    return "normalized";
  }

  const supplementalRawCandidates = Array.isArray(extraRawCandidates)
    ? extraRawCandidates
    : [];
  const rawValue =
    resolveRawAddressStringFromSources(fieldSources) ||
    resolveFirstNonEmptyString(supplementalRawCandidates);

  if (existingPayload && typeof existingPayload === "object") {
    const workingPayload = deepClone(existingPayload);
    const hasRawString =
      workingPayload &&
      typeof workingPayload.unnormalized_address === "string" &&
      workingPayload.unnormalized_address.trim().length;
    if (!hasRawString && typeof rawValue === "string" && rawValue.trim().length) {
      workingPayload.unnormalized_address = rawValue.trim();
    }
    applyDerivedAddressFieldsFromRaw(
      workingPayload,
      workingPayload.unnormalized_address,
    );
    if (!hasMeaningfulAddressValue(workingPayload.county_name)) {
      workingPayload.county_name = titleCaseCounty(defaultCountyName);
    }
    if (
      hasMeaningfulAddressValue(workingPayload.state_code) &&
      !hasMeaningfulAddressValue(workingPayload.country_code)
    ) {
      workingPayload.country_code = defaultCountryCode;
    }
    if (Object.prototype.hasOwnProperty.call(workingPayload, "request_identifier")) {
      delete workingPayload.request_identifier;
    }
    if (
      Object.prototype.hasOwnProperty.call(
        workingPayload,
        "source_http_request",
      )
    ) {
      delete workingPayload.source_http_request;
    }
    enforceRawVariantAllowedFields(workingPayload);
    ensureCountyRawRequiredFieldSurface(workingPayload);
    writeAddressJSONBypass(addressPath, workingPayload);
    return "raw";
  }

  if (!rawValue || !rawValue.trim().length) {
    removeFileIfExists(addressPath);
    return null;
  }

  const leanRaw =
    buildLeanRawOneOfPayload(rawValue, fieldSources, {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) || { unnormalized_address: rawValue.trim() };
  applyDerivedAddressFieldsFromRaw(leanRaw, leanRaw.unnormalized_address);
  if (!hasMeaningfulAddressValue(leanRaw.county_name)) {
    leanRaw.county_name = titleCaseCounty(defaultCountyName);
  }
  if (
    hasMeaningfulAddressValue(leanRaw.state_code) &&
    !hasMeaningfulAddressValue(leanRaw.country_code)
  ) {
    leanRaw.country_code = defaultCountryCode;
  }

  if (Object.prototype.hasOwnProperty.call(leanRaw, "request_identifier")) {
    delete leanRaw.request_identifier;
  }
  if (Object.prototype.hasOwnProperty.call(leanRaw, "source_http_request")) {
    delete leanRaw.source_http_request;
  }

  enforceRawVariantAllowedFields(leanRaw);
  ensureCountyRawRequiredFieldSurface(leanRaw);
  writeAddressJSONBypass(addressPath, leanRaw);
  stripAddressRequestMetadataOnDisk(addressPath);
  return "raw";
}

function stripAddressRequestMetadataOnDisk(addressPath) {
  if (!addressPath || typeof addressPath !== "string") {
    return;
  }
  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object") {
    return;
  }
  let mutated = false;
  if (Object.prototype.hasOwnProperty.call(payload, "request_identifier")) {
    delete payload.request_identifier;
    mutated = true;
  }
  if (Object.prototype.hasOwnProperty.call(payload, "source_http_request")) {
    delete payload.source_http_request;
    mutated = true;
  }
  const hydratedPayload =
    ensureCountyRawRequiredFieldSurface(payload) || payload;
  enforceRawVariantAllowedFields(hydratedPayload);
  try {
    addressWriteLocked = true;
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(hydratedPayload, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to strip address metadata from disk:", error);
  } finally {
    addressWriteLocked = false;
  }
}

function enforceRawAddressTemplateOnDisk(addressPath) {
  if (!addressPath || typeof addressPath !== "string") {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object") {
    return;
  }

  const trimmedRaw =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!trimmedRaw.length) {
    return;
  }

  const surfaced =
    ensureRawAddressOutputSurface({
      ...payload,
      unnormalized_address: trimmedRaw,
    }) || null;
  if (!surfaced || typeof surfaced !== "object") {
    return;
  }

  if (!surfaced.postal_code) {
    surfaced.plus_four_postal_code = null;
  }
  if (surfaced.state_code && !surfaced.country_code) {
    surfaced.country_code = "US";
  }

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(surfaced, null, 2)}\n`,
    );
  } catch (error) {
    try {
      writeAddressJSONBypass(addressPath, surfaced);
    } catch {
      // Ignore secondary failures; upstream callers will handle missing payloads.
    }
  }
}

function enforceFinalAddressVariantSelection(options = {}) {
  const {
    addressPath = path.join("data", "address.json"),
    propertyPath = path.join("data", "property.json"),
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    relationshipDirectories = [],
  } = options || {};

  const addressPayload = readJSONIfExists(addressPath) || null;
  const unnormalizedSource = readJSONIfExists(unnormalizedPath) || null;
  const seedSource = readJSONIfExists(seedPath) || null;

  const fieldSources = [addressPayload, unnormalizedSource, seedSource].filter(
    (source) => source && typeof source === "object",
  );

  let normalizedCandidate = null;
  if (
    addressPayload &&
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...addressPayload })
  ) {
    normalizedCandidate =
      buildNormalizedAddressOutputForSchema({ ...addressPayload }) || null;
  }

  if (normalizedCandidate) {
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedCandidate,
        "unnormalized_address",
      )
    ) {
      delete normalizedCandidate.unnormalized_address;
    }
    writeAddressJSONBypass(addressPath, normalizedCandidate);
    if (propertyPath) {
      enforceNullPropertyAddressRelationships(propertyPath);
    }
    if (
      Array.isArray(relationshipDirectories) &&
      relationshipDirectories.length
    ) {
      overwriteAddressRelationshipFilesWithNull(relationshipDirectories);
    }
    return "normalized";
  }

  const fallbackRawCandidates = [];
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    fallbackRawCandidates.push(
      ...ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates,
    );
  }

  const rawValue =
    resolveRawAddressStringFromSources(fieldSources) ||
    resolveFirstNonEmptyString(fallbackRawCandidates);

  if (!rawValue || !rawValue.trim().length) {
    removeFileIfExists(addressPath);
    if (propertyPath) {
      enforceNullPropertyAddressRelationships(propertyPath);
    }
    if (
      Array.isArray(relationshipDirectories) &&
      relationshipDirectories.length
    ) {
      overwriteAddressRelationshipFilesWithNull(relationshipDirectories);
    }
    return null;
  }

  const leanRaw =
    buildLeanRawOneOfPayload(rawValue, fieldSources, {
      requestIdentifierCandidates: [
        addressPayload && addressPayload.request_identifier,
        unnormalizedSource && unnormalizedSource.request_identifier,
        seedSource && seedSource.request_identifier,
        seedSource && seedSource.parcel_id,
      ],
      sourceHttpRequestCandidates: [
        addressPayload && addressPayload.source_http_request,
        unnormalizedSource && unnormalizedSource.source_http_request,
        seedSource && seedSource.source_http_request,
      ],
      defaultCountyName: "Palm Beach",
      defaultStateCode: "FL",
      defaultCountryCode: "US",
    }) || null;

  if (!leanRaw) {
    removeFileIfExists(addressPath);
    if (propertyPath) {
      enforceNullPropertyAddressRelationships(propertyPath);
    }
    if (
      Array.isArray(relationshipDirectories) &&
      relationshipDirectories.length
    ) {
      overwriteAddressRelationshipFilesWithNull(relationshipDirectories);
    }
    return null;
  }

  writeAddressJSONBypass(addressPath, leanRaw);
  if (propertyPath) {
    enforceNullPropertyAddressRelationships(propertyPath);
  }
  if (
    Array.isArray(relationshipDirectories) &&
    relationshipDirectories.length
  ) {
    overwriteAddressRelationshipFilesWithNull(relationshipDirectories);
  }
  return "raw";
}

function enforceTerminalRawAddressSurface(addressPath, options = {}) {
  if (!addressPath) {
    return;
  }

  const {
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    rawSources = [],
  } = options || {};

  const existingPayload = readJSONIfExists(addressPath) || null;
  const hasNormalizedSurface =
    existingPayload &&
    typeof hasStrictCountyNormalizedSchemaCoverage === "function" &&
    hasStrictCountyNormalizedSchemaCoverage({ ...existingPayload });

  if (hasNormalizedSurface) {
    if (
      Object.prototype.hasOwnProperty.call(
        existingPayload,
        "unnormalized_address",
      )
    ) {
      delete existingPayload.unnormalized_address;
    }
    if (
      Object.prototype.hasOwnProperty.call(
        existingPayload,
        "request_identifier",
      )
    ) {
      delete existingPayload.request_identifier;
    }
    if (
      Object.prototype.hasOwnProperty.call(
        existingPayload,
        "source_http_request",
      )
    ) {
      delete existingPayload.source_http_request;
    }
    try {
      originalWriteFileSync.call(
        fs,
        addressPath,
        `${JSON.stringify(existingPayload, null, 2)}\n`,
      );
    } catch (error) {
      console.error("Failed to persist normalized county address payload:", error);
    }
    return;
  }

  const supplementalSources = Array.isArray(rawSources)
    ? rawSources.filter((source) => source && typeof source === "object")
    : [];
  const resolvedSources = existingPayload
    ? [existingPayload, ...supplementalSources]
    : supplementalSources;

  const projected =
    buildUnnormalizedOnlyAddressSurface(existingPayload, {
      defaultCountyName,
      defaultStateCode,
      defaultCountryCode,
    }) ||
    buildUnnormalizedOnlyAddressSurface(
      aggregateRawSourcesForUnnormalizedSurface(resolvedSources),
      {
        defaultCountyName,
        defaultStateCode,
        defaultCountryCode,
      },
    );

  if (!projected) {
    removeFileIfExists(addressPath);
    return;
  }

  pruneRawAddressFieldSurface(projected);
  enforceRawVariantAllowedFields(projected);

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(projected, null, 2)}\n`,
    );
  } catch (error) {
    console.error("Failed to persist final raw county address payload:", error);
  }
}

function resolveAddressFieldFallback(field, fallbackSources = [], fieldFallbacks = null) {
  let candidate = resolveFirstMeaningfulAddressField(field, fallbackSources);
  if (
    (!candidate ||
      (typeof candidate === "string" && !candidate.trim().length)) &&
    fieldFallbacks &&
    typeof fieldFallbacks === "object" &&
    Array.isArray(fieldFallbacks[field])
  ) {
    for (const fallbackValue of fieldFallbacks[field]) {
      if (fallbackValue === undefined || fallbackValue === null) {
        continue;
      }
      if (typeof fallbackValue === "string") {
        const trimmed = fallbackValue.trim();
        if (trimmed.length) {
          candidate = trimmed;
          break;
        }
        continue;
      }
      if (typeof fallbackValue === "number" && Number.isFinite(fallbackValue)) {
        candidate = fallbackValue;
        break;
      }
      candidate = fallbackValue;
      break;
    }
  }
  return candidate;
}

function enrichRawAddressPayloadForSchema(addressPath, options = {}) {
  const {
    defaultCountyName = titleCaseCounty("Palm Beach"),
    defaultStateCode = "FL",
    defaultCountryCode = "US",
  } = options || {};

  if (!addressPath || !fs.existsSync(addressPath)) {
    return false;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return false;
  }

  const rawValue =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  if (!rawValue.length) {
    return false;
  }

  const dataDir = path.dirname(addressPath);
  const structuredSnapshot =
    readJSONIfExists(path.join(dataDir, "address_structured_snapshot.json")) ||
    null;
  const unnormalizedSource = readJSONIfExists("unnormalized_address.json") || null;
  const seedSource = readJSONIfExists("property_seed.json") || null;
  const propertyPayload = readJSONIfExists(path.join(dataDir, "property.json")) || null;

  const fallbackSources = [
    structuredSnapshot,
    payload,
    unnormalizedSource,
    seedSource,
    propertyPayload,
  ].filter((source) => source && typeof source === "object");

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.fieldSources)
  ) {
    fallbackSources.push(
      ...ADDRESS_FALLBACK_CONTEXT.fieldSources.filter(
        (source) => source && typeof source === "object",
      ),
    );
  }

  const fieldFallbacks =
    ADDRESS_FALLBACK_CONTEXT &&
    ADDRESS_FALLBACK_CONTEXT.fieldFallbacks &&
    typeof ADDRESS_FALLBACK_CONTEXT.fieldFallbacks === "object"
      ? ADDRESS_FALLBACK_CONTEXT.fieldFallbacks
      : null;

  const enriched = { ...payload };
  let mutated = false;

  const assignFieldIfMissing = (field, value) => {
    if (value === undefined || value === null) {
      return;
    }
    if (hasMeaningfulAddressValue(enriched[field])) {
      return;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      if (!Number.isFinite(numeric)) {
        return;
      }
      enriched[field] = numeric;
      mutated = true;
      return;
    }
    const sanitized =
      typeof sanitizeAddressFieldValue === "function"
        ? sanitizeAddressFieldValue(field, value)
        : value;
    if (sanitized === undefined || sanitized === null) {
      return;
    }
    if (typeof sanitized === "string") {
      const trimmed = sanitized.trim();
      if (!trimmed.length) {
        return;
      }
      enriched[field] = trimmed;
      mutated = true;
      return;
    }
    enriched[field] = sanitized;
    mutated = true;
  };

  const assignFallbackField = (field) => {
    if (hasMeaningfulAddressValue(enriched[field])) {
      return;
    }
    let candidate = resolveAddressFieldFallback(field, fallbackSources, fieldFallbacks);
    if (!candidate) {
      if (field === "county_name") {
        candidate = defaultCountyName;
      } else if (field === "state_code") {
        candidate = defaultStateCode;
      } else if (field === "country_code") {
        candidate = defaultCountryCode;
      }
    }
    assignFieldIfMissing(field, candidate);
  };

  const derivedFromRaw =
    typeof deriveNormalizedAddressFieldsFromRaw === "function"
      ? deriveNormalizedAddressFieldsFromRaw(rawValue) || null
      : null;
  if (derivedFromRaw && typeof derivedFromRaw === "object") {
    Object.entries(derivedFromRaw).forEach(([field, value]) => {
      assignFieldIfMissing(field, value);
    });
  }

  [
    "street_number",
    "street_name",
    "street_pre_directional_text",
    "street_post_directional_text",
    "street_suffix_type",
    "unit_identifier",
    "route_number",
    "city_name",
    "municipality_name",
    "state_code",
    "postal_code",
    "plus_four_postal_code",
    "county_name",
    "country_code",
  ].forEach(assignFallbackField);

  const parcelCandidates = [];
  const enqueueParcelCandidate = (value) => {
    if (typeof value !== "string") {
      return;
    }
    const trimmed = value.trim();
    if (trimmed.length) {
      parcelCandidates.push(trimmed);
    }
  };
  enqueueParcelCandidate(payload.parcel_identifier);
  if (propertyPayload && typeof propertyPayload === "object") {
    enqueueParcelCandidate(propertyPayload.parcel_identifier);
  }
  if (seedSource && typeof seedSource === "object") {
    enqueueParcelCandidate(seedSource.parcel_id);
    enqueueParcelCandidate(seedSource.request_identifier);
  }
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.parcelIdCandidates)
  ) {
    ADDRESS_FALLBACK_CONTEXT.parcelIdCandidates.forEach(enqueueParcelCandidate);
  }

  for (const candidate of parcelCandidates) {
    const grid = parseGridFromPcn(candidate);
    if (!grid) continue;
    assignFieldIfMissing("township", grid.township);
    assignFieldIfMissing("range", grid.range);
    assignFieldIfMissing("section", grid.section);
    assignFieldIfMissing("block", grid.block);
    assignFieldIfMissing("lot", grid.lot);
    if (
      hasMeaningfulAddressValue(enriched.township) &&
      hasMeaningfulAddressValue(enriched.range) &&
      hasMeaningfulAddressValue(enriched.section)
    ) {
      break;
    }
  }

  const legalDescription =
    (propertyPayload && propertyPayload.property_legal_description_text) || null;
  if (typeof legalDescription === "string" && legalDescription.trim().length) {
    const gridFromLegal = extractGridComponentsFromLegalDescription(
      legalDescription,
    );
    if (gridFromLegal) {
      assignFieldIfMissing("township", gridFromLegal.township);
      assignFieldIfMissing("range", gridFromLegal.range);
      assignFieldIfMissing("section", gridFromLegal.section);
    }
    const lotBlock = extractLotAndBlock(legalDescription);
    assignFieldIfMissing("block", lotBlock.block);
    assignFieldIfMissing("lot", lotBlock.lot);
  }

  if (
    (!Number.isFinite(parseCoordinate(enriched.latitude)) ||
      !Number.isFinite(parseCoordinate(enriched.longitude))) &&
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.coordinateCandidates)
  ) {
    for (const candidate of ADDRESS_FALLBACK_CONTEXT.coordinateCandidates) {
      if (!candidate || typeof candidate !== "object") continue;
      const lat = parseCoordinate(candidate.latitude);
      const lon = parseCoordinate(candidate.longitude);
      if (Number.isFinite(lat) && Number.isFinite(lon)) {
        assignFieldIfMissing("latitude", lat);
        assignFieldIfMissing("longitude", lon);
        break;
      }
    }
  }

  if (
    !Number.isFinite(parseCoordinate(enriched.latitude)) ||
    !Number.isFinite(parseCoordinate(enriched.longitude))
  ) {
    const coordinateSources = [payload, structuredSnapshot, unnormalizedSource, seedSource];
    for (const source of coordinateSources) {
      if (!source || typeof source !== "object") continue;
      const lat = parseCoordinate(source.latitude);
      const lon = parseCoordinate(source.longitude);
      if (Number.isFinite(lat) && Number.isFinite(lon)) {
        enriched.latitude = lat;
        enriched.longitude = lon;
        mutated = true;
        break;
      }
    }
  } else {
    enriched.latitude = parseCoordinate(enriched.latitude);
    enriched.longitude = parseCoordinate(enriched.longitude);
  }

  if (
    (enriched.latitude == null && enriched.longitude != null) ||
    (enriched.latitude != null && enriched.longitude == null)
  ) {
    enriched.latitude = null;
    enriched.longitude = null;
    mutated = true;
  }

  for (const field of COUNTY_REQUIRED_NORMALIZED_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(enriched, field)) {
      continue;
    }
    enriched[field] = null;
    mutated = true;
  }

  const metaFieldsToRemove = [
    "__force_raw_variant",
    "__preserve_structured_fields",
    "__raw_minimal_surface",
    RAW_MINIMAL_SURFACE_FLAG,
  ];
  metaFieldsToRemove.forEach((metaField) => {
    if (Object.prototype.hasOwnProperty.call(enriched, metaField)) {
      delete enriched[metaField];
      mutated = true;
    }
  });

  if (!mutated) {
    return false;
  }

  try {
    originalWriteFileSync.call(
      fs,
      addressPath,
      `${JSON.stringify(enriched, null, 2)}\n`,
    );
    return true;
  } catch (error) {
    console.error("Failed to enrich county raw address payload:", error);
    return false;
  }
}

